INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12301370083', 'Sapato Feminino Scarpin Boneca Mary Jane Sapatilha Salto Grosso', 'Formal normal Material externo: verniz Solado: microgel pvc, não faz barulho Palmilha com espuma macia. Salto: 5,5 cm Proteção de envio: caixa individual, embalada com envelope plástico resistente. Foto real do nosso produto. Conservação, para conservar o seu modelo novo e bonito por muito mais tempo é fundamental seguir algumas recomendações: A limpeza deve ser feita com sabão neutro e pano úmido e não deve ficar de molho. Não usar nenhuma fonte de calor para secar. Guardar em local sem umidade e deixar descansar na sombra por 12 horas após o uso. Não utilize Máquina de lavar e secar. Independente do material do seu sapato, não esfregue com força ou passe esponjas grossas. Caso alguma dessas indicações não forem cumpridas, isso poderá danificar os materiais, a cor e a textura do seu calçado.', 89.99, 67.78, NULL, 'Women Shoes > Flats > Ballet Flats', 'https://cf.shopee.com.br/file/57f637063eb4d61c71dcb95fba38732b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F387348115%2F12301370083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
