INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394794260', 'Vestido Midi Ribana Canelada Básico Rovitex Roxo', 'O vestido midi é a escolha perfeita para quem procura conforto e estilo em uma única peça. Confeccionado em ribana canelada, ele oferece um toque macio e uma textura agradável ao corpo. Com sua fenda lateral, é possível adicionar um toque de sensualidade ao look, sem perder a elegância. Seu comprimento midi é ideal para diversas ocasiões, desde um passeio no parque até um jantar mais formal. Aposte nesse vestido versátil e arrase em qualquer lugar!', 119.99, 119.99, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-825b0-mr1l297aze2oc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23394794260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594156884', 'Limpa Vidros Para Brisa Espelho All Vision Jaça 500ml', 'ALL VISION é um limpa vidros altamente eficaz. Produto totalmente isento de Hidróxido de Amônia.Possui ação sobre gorduras, oleosidade corporal, marcas de digitais e outras sujidades provenientes das mais variadas fontes de contaminantes, naturais e ou sintéticos.Produto não inflamável com volatilidade perfeita após aplicação; pode ser direcionado também para uso doméstico, como limpeza de espelhos, box, vidros de casa, mesas de vidro e outras superfícies derivadas deste mesmo material.Remoção de manchas difíceis de vidros e também espelhos.Disponível:1 - All Vision 500ml Jaça Limpador De VidrosCaracterísticas:- Produto de Excelente QualidadeServe para os Modelos e Anos:UniversalEspecificação Técnica:- Marca Jaça- Material Plástico', 68.9, 31.66, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7rau0-mb4bm4pwo1k932', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F23594156884', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193529151', 'KIT 8 PANELAS COM ANTIADERENTE CERÂMICO TERRARA - OIKOS', '"conheça o kit 8 panelas antiaderentes da coleção Terrara da Oikos! antiaderentes, com alta qualidade e design moderno, são ótimas para fazer suas receitas favoritas sem perigo de grudar alimentos ou ingerir substâncias tóxicas. a combinação de cores em tons terrosos com acabamento fosco harmonizam com a decoração da cozinha e levam charme ao ambiente! além disso, possuem 5 camadas: antiaderente cerâmico, camada antidesgaste interna, alumínio, camada antidesgaste externa e pintura externa. a espessura é de 2mm: distribui melhor o calor e evita que os alimentos queimem! as panelas são de alumínio, cerâmica, aço inox, vidro temperado e baquelite. cuidados: • não utilize objetos pontiagudos ou de metal durante o cozimento; • para limpar basta utilizar esponja macia com detergente; • utilize um pouco de água, azeite, óleo ou manteiga antes de aquecer para ajudar na eficiência da antiaderência; • aguarde as panelas esfriarem completamente antes de lavar para evitar choque térmico e deformidades; • preparar alimentos pigmentados pode afetar a cor do revestimento interno, mas não prejudica a eficiência; • utilizar sempre em fogo baixo ou médio evita superaquecimentos e deformidades na pintura externa; • a exposição ao fogo fora do espaço delimitado do fundo das panelas pode causar manchas e desbotamento na pintura externa; • levantar a panela em vez de arrastar evita arranhões no fundo. como fazer a cura da panela: basta aplicar uma pequena quantidade de óleo vegetal com o auxílio do papel toalha, aquecer em fogo baixo por 1 a 2 minutos e, após esfriar, é só lavar e secar! fogões compatíveis: a gás, elétricos, cerâmicos e halogênio. as panelas não podem ir em fogões de indução, fornos ou em micro-ondas! leve modernidade e praticidade para sua casa! o kit contém: 1 panela 1,3L e 16cm de diâmetro 1 panela 1,65L e 18cm de diâmetro 1 frigideira 0,28L e 14cm de diâmetro 1 frigideira 0,75L e 20cm de diâmetro 1 caçarola 2,4L e 20cm de diâmetro 1 caçarola 4,25L e 24cm de diâmetro 1 frigideira grill 0,85L e 24cmx24cm de diâmetro 1 leiteira 1,15L e 12cm de diâmetro"', 1125.9, 599.9, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-8260i-mlgdimzu9lok03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F22193529151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
