INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10542336164', 'Misturador de tinta e argamassa em aço 60x10cm - Castor', 'O Misturador de Tintas e Argamassa em Aço 60 x 10 cm da Castor pode ser acoplado e acionado por furadeira elétrica, além de manualmente. É ótimo para misturar de forma homogênea as tintas, massas para textura, gesso, argamassas, resinas e impermeabilizantes de forma simples, rápida e limpa com o menor esforço. CARACTERÍSTICAS Aspectos: possui Haste sextavada que pode ser acoplado a uma furadeira. É revestido com tinta protetiva que não enferruja, não manchando a tinta misturada. Além da furadeira, o misturador também pode ser acoplado em um Martelete. Medidas: 60 cm x 10 cm Material: aço. Código do fabricante: 581 Limpeza e Conservação: após o uso, retirar os resíduos do produto utilizado e lavar com água e sabão. Guardar em local arejado. FERRAMENTAS QUE COMPLEMENTAM Para você que precisa de produtos especiais para ajudar a pintura a render mais, além de otimizar o tempo do trabalho, a Castor tem a solução! A linha de Especiais para Pintura oferece tudo que você precisa para conseguir um resultado profissional em todos os seus trabalhos. SEGURANÇA Compre com segurança! Nossa equipe de suporte sempre estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 82.12, 82.12, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/0f5c58f7f22e2d0a27cbc4f8b6a2bede', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F10542336164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392999680', 'Kit Montagem Chicote Conector Malha Termo Fueltech Pandoo Tc', 'Mundo Peças, Empresa com mais de 24 anos no mercado de peças para reposição automotiva, com garantia de preço justo, atendimento sempre dando preferência a Qualidade. A Loja do Auto Elétrico, tudo de elétrica para preparação automotiva. As melhores Marcas de Conectores do Mercado, o Kit vai com conectores da TC CHICOTES, conectores que travam de verdade e não ficam soltando. Outras marcas com trava mais frágil o terminal sai do plug sempre que vai encaixar em bobina ou sensores, atrapalhando todo o serviço!!! Kit composto por: 4 Conectores dos bicos injetores 1 Conector do sensor de temperatura do ar 1 Conector do sensor de temperatura da água 1 Conector da bobina ou sensor de rotação 3 fios. 1 Conector do distribuidor hall - 1.8 ou 2.0 1 Conector do sensor de posição borboleta- TPS 4 Concetores de Bobina 5 Metros MALHA NÁUTICA Preta 3mm 5 Metros MALHA NÁUTICA Preta 6mm 5 Metros MALHA NÁUTICA Preta 8mm 5 Metros MALHA NÁUTICA Preta 10mm 5 Metros MALHA NÁUTICA Preta 12mm 1 Metro TERMO RETRÁTIL PRETO 3,2MM 1 Metro TERMO RETRÁTIL PRETO 6,4MM 1 Metro TERMO RETRÁTIL PRETO 8,0MM 1 Metro TERMO RETRÁTIL PRETO 9,5MM 1 Fita de Tecido 25 metros para Chicote Tesa. Compatível: FuelTech FT 200/ 250 / 300 / 350 / 400 HIS Injepro Pandoo Motores: - 4 Cilindros - Aspirado ou Turbo - Com Distribuidor - 4 Bicos Temos toda a linha de Conectores Pronta entrega montados e desmontados, atendimento personalido, mande uma pergunta e monte o seu KIT. Mundo Peças Auto. PEÇA NOVA A MELHOR MARCA DO MERCADO. COMPRE DIRETO DO DISTRIBUIDOR COM TOTAL GARANTIA NA ENTREGA E NO PÓS VENDA, TIRE SUAS DUVIDAS DIRETO COM PESSOAS ESPECIALIZADAS NO RAMO AUTOMOTIVO!!', 214.9, 214.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial