INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44806268536', '2 Pilha Pequena AA Recarregável Com Cabo Tipo C 2000ma Elgin', '2 Pilhas AA Recarregáveis Elgin + Cabo Tipo C - 2000mAh. - Recarregue Fácil: Inclui cabo Tipo C para recarga rápida e conveniente, sem precisar de carregador específico. - Economia Inteligente: Reduza o desperdício e economize dinheiro, substituindo pilhas descartáveis por recarregáveis. - Longa Duração: Com 2000mA, garanta energia duradoura para seus dispositivos, como controles e brinquedos. As Pilhas AA Recarregáveis Elgin são a solução ideal para quem busca praticidade, economia e sustentabilidade. Com elas, você não precisa mais se preocupar em comprar pilhas descartáveis constantemente. Basta recarregar utilizando o cabo Tipo C incluso e seus dispositivos estarão sempre prontos para uso. Além de economizar, você contribui para um planeta mais verde, reduzindo o descarte de pilhas no meio ambiente. - Tipo: AA (Pequena). - Recarregável: Sim. - Capacidade: 2000mA. - Carregamento: Cabo Tipo C (incluso). - Marca: Elgin.', 99.98, 79.98, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mktq44b5zy0x01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F44806268536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
