INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792400091', 'Cabelo Humano Cacheado Na Tela 30cm - 400 Gramas Mega Hair', 'Desvende a Magia do Cabelo Cacheado Autêntico: Beleza Natural ao Alcance das Mãos! Apresentando o Cabelo 100% Humano Cacheado na Tela – com exatos 30cm e 400g de genuína elegância. Especificações Técnicas: Comprimento Real: Esticado revela 30cm e em sua forma cacheada, aproxima-se de 25cm. Cor Vibrante: Um rico castanho escuro que combina com diversas tonalidades de pele. Peso Preciso: 400 gramas (com uma variação máxima de 5g) asseguram consistência. Textura Incomparável: Cacheado com permanente a vapor seguido por choque térmico, produzindo cachos largos do tipo 3A. Dimensões da Tela: 1 tela tem cerca de 70cm de comprimento. Por que escolher nosso produto? Autenticidade Garantida: Este é um cabelo 100% humano, sem qualquer mistura. Versatilidade Suprema: Ideal para alongamentos e apliques. Condição Impecável: Cada fio foi selecionado, lavado, hidratado, higienizado e esterilizado para garantir a máxima qualidade. Flexibilidade de Estilo: Livre para tingir, descolorir ou estilizar como desejar. No entanto, recomendamos um teste de mechas antes de qualquer processo químico. Atenção: Evite futuros arrependimentos! Não aceitamos troca ou devolução após qualquer alteração no cabelo. Quantidade Ideal para Você: 50g para manutenções regulares. 100g para manutenção e adição de volume. 200g oferece um volume médio por toda a cabeça. 300g para aqueles que desejam uma cabeça cheia com muito volume. Perguntas frequentes: É genuinamente cabelo humano? Absolutamente! Não trabalhamos com misturas, garantimos a pureza. Qual é a garantia? Asseguramos tanto a entrega quanto a qualidade. Se, por acaso, não estiver satisfeito, a devolução é possível, desde que o cabelo não tenha sofrido alterações. Transforme seu visual com a verdadeira essência do cabelo cacheado. Adquira agora!', 873.77, 830.09, NULL, 'Fashion Accessories > Hair Accessories > Wigs & Extensions', 'https://cf.shopee.com.br/file/sg-11134201-7rbma-llphc097nns3f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375741503%2F23792400091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492399335', 'Capa Para iPhone 11 Pro Anti-impacto Crystal Matter - Laut', 'Capa Para iPhone 11 Pro protetora anti-riscos anti-impacto Crystal Matter Laut - Indigo! As Capas Laut são produzidas com foco na união de funcionalidade e design. Sendo a melhor opção para a proteção do seu iPhone, a capa capinha para iPhone 11 Pro Crystal Matter é a prova de quedas, capaz de suportar impactos de até 4 metros. Garantindo toda a segurança e funcionalidade do seu iPhone sem ocultar sua beleza e estilo. Características: • Traseira rígida, anti-riscos e cristalina; • Proteção anti-impacto de até 4 metros; • Botões de alumínio usinado táteis responsivos; • Estrutura resistente a impacto; • Design ergonômico de fácil aderência. • Material: Policarbonato; • Cor: Borda Indigo e Fundo Transparente. • Marca: Laut; • Garantia: 90 dias contra defeitos de fabricação.', 9.9, 7.92, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rbn1-llpa5bglnc6229', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068102132%2F22492399335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
