INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298316458', 'Espuma de Barbear Nivea Men Deep 200ml', 'Espuma de Barbear Nivea Men Deep 200ml - Conforto e Proteção para Seu Barbeado Diário Nivea Men Espuma de Barbear Deep é um produto de cuidado masculino que proporciona uma limpeza profunda e eficaz à pele durante o barbear. Para que serve? Com sua fórmula inovadora e a presença de carvão ativado em sua composição, esse produto oferece benefícios únicos, além disso, é Antibacteriano e possui uma fragrância suave que deixa uma sensação de frescor por muito mais tempo. Dermatologicamente testado, Nivea Men Espuma de Barbear Deep promove um barbear suave e é ideal para homens que desejam uma experiência de barbear completa, de qualidade e uma sensação prolongada de pele limpa. Benefícios - Carvão ativado atua contra as bactérias - Sensação de frescor - Limpa a pele - Previne vermelhidão e irritação - Amacia o pelo da barba Como usar a Espuma de Barbear Nivea Men Deep corretamente? -Prepare a pele: Lave o rosto com água morna para abrir os poros e amolecer os pelos. -Aplique a espuma: Agite bem a embalagem e aplique uma quantidade generosa de espuma nas áreas a serem barbeadas. -Barbeie-se com cuidado: Utilize uma lâmina de qualidade e faça movimentos suaves, sem pressionar. -Enxágue e hidrate: Enxágue com água fria para fechar os poros e finalize com um hidratante para o rosto.', 58.13, 58.13, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rd73-m770kmubpyxt05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23298316458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098341876', 'Aparelho de Barbear Descartável Gillette Prestobarba3 Sensitive 2 Unidades', 'Você tem pele sensível? Este é o aparelho de barbear descartável ideal para você. O Gillette Prestobarba3 Sensitive, agora com uma fita lubrificante melhorada, oferece até 10 barbas suaves por barbeador. A fita lubrificante com Aloe e mais lubrificação é ativada por água, proporcionando um barbear rente com menos irritação. Possui três (3) lâminas e uma cabeça móvel que se ajusta aos contornos do rosto para um barbear rente. Além disso, o cabo antiderrapante proporciona um maior controle durante o barbear. Para uma melhor experiência de barbear, experimente usá-lo com as Espumas para Barbear Gillette para peles sensíveis. - Barbear rente com menos irritação: Até 10 barbas suaves por barbeador, com menos irritação; - Mais lubrificação: a fita lubrificante melhorada com tecnologia Comfortgel e Aloe é ativada por água para um barbear suave; - Para pele sensível: O barbeador Gillette Prestobarba3 Sensitive é ideal para homens com pele sensível; - Barbear rente: Três (3) lâminas móveis de longa duração que se ajustam às irregularidades do rosto para um barbear rente; - Ajusta-se ao seu rosto: sua cabeça flexível se ajusta aos contornos do seu rosto; - Maior controle: o cabo antiderrapante, agora 50% reciclado, proporciona um bom controle durante o barbear; - Fácil de limpar: desenho aberto para um 100% melhor enxágue*(vs. Prestobarba Ultragrip); - Conteúdo: Este produto vem com 2 aparelhos de barbear Gillette Prestobarba3 Sensitive.', 40.66, 40.66, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rd3r-m76ub1zbm9w205', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22098341876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
