INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207501155', 'Elizavecca CER-100 Tratamento para Couro Cabeludo com Colágeno A+ Muscle Tornado - Shampoo 500ml', 'Shampoo para cabelos oleosos e com caspa. Elizavecca CER-100 Tratamento para Couro Cabeludo com Colágeno A+ Muscle Tornado limpa, refresca e recupera a maleabilidade dos fios. O Shampoo Elizavecca CER-100 Tratamento para Couro Cabeludo com Colágeno A+ Muscle Tornado limpa o excesso de oleosidade sem ressecar, proporcionando frescor imediato. Com ingredientes como colágeno, mentol, ceramidas e extratos vegetais, ele combate a caspa, alivia a descamação e mantém a saúde do couro cabeludo e dos fios, oferecendo sensação de frescor a cada lavagem. Como Usar: Aplique uma dose do produto, equivalente a um pump. Massageie os cabelos até obter espuma. Enxágue e repita a operação. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 222.9, 222.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261i-mm7juk8p20ht2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58207501155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694946970', 'Modelador Vulcan 220ºC - Laranja / Bivolt', 'A linha Vulcan cresceu! Unimos o desempenho, a temperatura e a beleza dos produtos da linha e criamos o modelador Vulcan. Com 220°C de temperatura, foi desenvolvido exclusivamente para profissionais, proporcionando uma modelagem super-rápida. O tubo mais longo, com 25mm e espelhado permite máximo deslizamento. E o resultado são fios com brilho intenso, bem tratados e com modelagem perfeita. O cabo giratório de 3 metros permite ao profissional maior mobilidade para os mais variados penteados e cachos. Tem ainda chave liga/desliga e é bivolt automático.', 339.18, 339.18, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zvo-mmw3cngtmmf533', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1787996512%2F22694946970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
