INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897753471', 'Top Fitness Power com Renda Arrastão', 'Top com forro, sem bojo (mas tem abertura no forro para quem quiser colocar bojo ). Tecido de suplex confort. Top desenvolvido em suplex, possuindo alça dupla e detalhe em tela abaixo do busto, com compressão moderada e elasticidade na medida certa que proporciona maior sustentação e liberdade na hora do treino. Todos esses detalhes garantem um top moderno e indispensável no seu guarda-roupa. ESPECIFICAÇÕES •Esta peça pode ser usada no dia a dia e para atividades físicas. •Este produto deve ser lavado apenas à mão e com sabão neutro. Prefira a secagem à sombra. Dispensa o uso de amaciante e ferro de passar. •Atenção: A forma das estampas podem variar de acordo com o corte do tecido em nossa linha de produção. Pode haver também, variação nas cores por conta de fatores como iluminação fotográfica e brilho de cada monitor; Nossa forma é pequena, sempre aconselhamos a pegar uma numeração maior para mais conforto. COMPOSIÇÃO DA PEÇA: • 90% Poliéster / 10% Elastano • Microfibra de alta qualidade • Tecido SUPLEX TABELA DE MEDIDAS •Tamanho M: Busto (cm): 92 x 96 | Cintura (cm): 76 x 82 •Tamanho G: Busto (cm): 98 x 102 | Cintura (cm): 84 x 90 •Tamanho GG: Busto (cm): 104 x 108 | Cintura (cm): 92 x 98', 29.9, 19.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-lzqjiiktd3ie60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303874852%2F22897753471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22695908129', 'Cinta de Poliéster Com Catraca P/ Amarração de Carga 6 metros 750kg (737111) - Onsite', 'A Cinta de Poliéster Com Catraca 6m X 750kg (737111) - Onsite, são acessórios que servem para amarrar cargas. As catracas são amarradas nas cintas por meio de costura e se mantém presa até que o equipamento seja acionado. Entre as cintas que realizam essa função, a cinta de poliéster com catraca é uma das mais utilizadas, pois a matéria-prima possui destaque e melhor desempenho se comparada com o material de outras cintas. Características: - Capacidade de Carga: 750kg. - Tamanho: 6m x 25mm. - Peso máximo suportado: 1500 kg. Código:737111. Marca: Onsite. Capacidade de Carga: 750kg. Peso Máximo: 1,500kg. Tamanho: 6m x 25mm. Ean: 6942629245841.', 55.62, 52.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjtwg0bzgsna26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22695908129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
