INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498683855', 'Kit com 10UN da Caixa de Sobrepor com Tampa 1 Posto Tramontina LizFlex - 57303001', 'O Kit com 10 Unidades da Caixa de Sobrepor com Tampa 1 Posto Tramontina LizFlex Branca – Ref. 57303001 é ideal para instalações elétricas que exigem praticidade, organização e acabamento moderno. Cada unidade é composta por caixa e tampa com encaixe de pressão, dispensando o uso de parafusos e facilitando a instalação. Fabricadas em termoplástico na cor branca, as caixas possuem sistema modular e janelas para inserção de canaletas de diferentes dimensões, adaptando-se a diversos projetos. Diferenciais: Instalação sem quebra de paredes: Ideal para reformas e ampliações, permite montagem rápida e limpa. Encaixe por pressão: Dispensa o uso de parafusos, proporcionando acabamento limpo e seguro. Sistema modular: Compatível com canaletas de diferentes tamanhos (20x10, 40x20, 50x20 mm), oferecendo flexibilidade no projeto. Material resistente: Fabricado em termoplástico branco de alta qualidade, garantindo durabilidade e segurança. Design discreto: Acabamento branco brilhante que se integra facilmente a diversos ambientes.', 96.12, 76.9, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra2j-mbgqd6vypitp72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F22498683855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
