INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56412110970', 'Espreguiçadeira Dobrável com Estofado Azuza Cadeira Confortável Acolchoada Casa Piscina Praia', 'Espreguiçadeira Dobrável com Estofado Azuza Todo o conforto de uma espreguiçadeira com o aconchego de um estofado acolchoado. A Espreguiçadeira Dobrável com Estofado Azuza funciona como cadeira reclinável ou cama — ideal para varanda, jardim, beira de piscina ou quarto. O estofado embutido garante mais maciez e conforto para longas horas de descanso. Quando não estiver em uso, dobra facilmente e ocupa apenas 70 x 70 x 8 cm. Especificações Técnicas Material: Estrutura em metal, assento com estofado acolchoado Dimensões aberta: 190 x 67 cm Dimensões dobrada: 70 x 70 x 8 cm Peso: 7,15 kg Uso: Cadeira reclinável ou cama O que acompanha o produto 1x Espreguiçadeira dobrável Azuza 1x Estofado acolchoado 1x Almofada de cabeça Garantia 30 dias contra defeitos de fabricação.', 399.9, 279.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-820md-mpl224u6y3gic3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F344415614%2F56412110970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197686343', 'Buzina Automotiva Caracol Chevrolet Onix 2012-2018 12v Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Buzina Automotiva Caracol Chevrolet Onix 2012-2018 12v Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Chevrolet Onix Buzina Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Chevrolet Onix 2012 Chevrolet Onix 2013 Chevrolet Onix 2014 Chevrolet Onix 2015 Chevrolet Onix 2016 Chevrolet Onix 2017 Chevrolet Onix 2018 Especificações Técnicas do Veículo: Veículo: Onix Montadora: Chevrolet Ano: 2012 a 2018 Especificação Técnica - Buzina: Cod Produto: Gb1052 Modelo: Buzina Caracol Voltagem: 12.0 Nivel Sonoro: 110.0 Quantidade De Conectores: 2.0 Quantidade Buzinas: 1.0 Quandidade De Cornetas: 1.0 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 46.99, 46.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kkqp2ik69e3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22197686343', NULL, NULL, '2026-07-28T02:11:31.708458+00