INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993198083', 'Coador De Cafe Individual Mini Aramado Preto Filtro De Pano Arthi', 'Coador de Café Fast Coffee Black - Arthi O Coador de Café Fast Coffee Black da Arthi oferece uma estrutura moderna e resistente para o preparo do seu café preferido por um processo super tradicional. Ideal para filtro de pano, o Coador Fast Coffee possibilita que as partículas de óleos essenciais do café sejam liberadas pelo pano, resultando em um cafezinho encorpado e marcante. Além de proporcionar um café saboroso, este clássico coador adiciona um charme especial à sua cozinha. Característica do Produto: Composição: Aço com Pintura Epóxi Cor: Preto Marca: Arthi Dimensões: Comprimento: 12,1 cm Largura: 16 cm Altura: 16,5 cm Loja do Primo Variedades', 25.5, 22.79, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-lycyq25c6ieif6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F22993198083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
