INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698109162', 'Lip Oil Epidrat Hyalu Choco FPS30 - 6mL', 'EPIDRAT HYALU LIP OIL FPS 30 CHOCOLATE hidrata, proporcionando o briho ideal, volume e preenchimento dos lábios, sem causar desconforto. Reduz os vincos, deixando os lábios realçados e nutridos. Possui ácido hialurónico, vitamina E e óleo de rosa mosgueta, ativos que proporcionam maior poder de hidratação, ação antioxidante e rejuvenescedora. Com tripeptideos que estimulam a produção de colágeno, previne o envelhecimento. O FPS 30 confere proteção contra os raios UVA e UVB. Este produto não é um protetor solar Hipoalergénico. Dermatologicamente testado. Não escorre nos lábios.', 79.9, 79.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-82619-mja5ql2c8z5s95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F18698109162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6784896946', 'Filtro De Ar Condicionado Azera E Santa Fé 2009+higienizadoR CES2306', 'Filtro Ar Condicionado Azera e Santa Fé 2009 em diante + 2 HIGIENIZADORES NEST KIT VAO 1 FILTRO CES2306 1 HIGIENADOR O higienizador enviado será da marca Radnaq ou Orbi ( conforme disponibilidade no estoque ) Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar. HIGIENIZADOR O higienizador desempenha a função de filtrar as impurezas do ar e bloquear a entrada de maus odores no veículo.', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz52rpq5kyad9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F6784896946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208588184', 'Conjunto Bebê Menina Com Capuz Coelhinhos Elian Rosa', 'O Conjunto Elian é composto por jaqueta e calça em moletom felpado. A jaqueta possui punhos ajustados nas mangas e barra, garantindo conforto para os movimentos, enquanto o capuz e fechamento em zíper trazem praticidade para o dia a dia. Além disso, sua estampa divertida de coelhinhos e elementos delicados cria um visual lúdico e superfofo. Já a calça conta com elástico no cós e punho nas barras. Ideal para dias fresquinhos e passeios, aposte nessa opção charmosa e confortável para sua bebê!Detalhes da peça: • Conjunto composto por jaqueta e calça • Feito em moletom felpado • Possui mangas longas • Possui capuz • Abertura frontal em zíper • Estampa de coelhinhos • Elástico no cós • Ideal para passeios e dias frescos', 129.9, 77.94, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mr1ttw36qt52f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58208588184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254789550', 'Conjunto Infantil Menino Regata Estampada Elian Amarelo', 'Indispensável no guarda-roupa dos meninos, o Conjunto Elian é composto por regata em meia malha e bermuda em moletom sem felpa. A regata possui modelagem tradicional e estampa frontal, trazendo um toque divertido e cheio de estilo para o visual. Já a bermuda conta com elástico no cós e estampa lisa. Ideal para curtir os dias de sol com leveza e liberdade, aposte nesse conjunto para os meninos aproveitarem cada momento com conforto e estilo!Detalhes da peça: • Conjunto composto por regata e bermuda • Feito em meia malha e moletom sem felpa • Possui estampa frontal • Possui elástico no cós • Ideal para dias de sol', 69.9, 55.92, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mr1tpm7kfw1zf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58254789550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208057926', 'Anti Respingo para Solda sem Silicone Spray com 400ml - ESAB', 'Anti Respingo para Solda sem Silicone Spray com 400ml - ESAB Antirrespingo ESAB um aerossol formulado para facilitar o trabalho dos soldadores, reduzindo consideravelmente o tempo gasto no acabamento. Quando aplicado sobre chapas metlicas, recobre a superfcie tratada com uma fina camada de leo que impede a aderncia dos respingos e resduos da solda, alm de dar proteo temporria contra a corroso. No afeta a qualidade e resistncia das soldas, pois o produto destrudo pela alta temperatura. Pode ser usado em todo tipo de solda, e no caso do antirrespingo sem silicone, ideal para superfcies onde haver pintura posterior. seguro para os soldadores, pois utiliza gs propelente no inflamvel. - Aplicar antirrespingo ESAB na regio da solda e nas reas onde os respingos de solda devem escorrer. - necessrio apenas a formao de uma leve camada oleosa. Efetuar a solda normalmente. A maior parte dos respingos deve escorrer at o cho. Os poucos que ficarem parados na chapa sairo com pequena presso, mesmo quando frios. - Antes da pintura, limpar a pea com desengraxante. Composio - Antirrespingo SEM SILICONE - Polmeros sintticos de glicis, solventes fluorados e gs carbnico como propelente.. Todas as informaes divulgadas so de responsabilidade do FabricanteFornecedor Imagem Meramente Ilustrativa', 45.33, 45.33, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zvj-mmj6wspcq8zn74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F58208057926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
