INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691900446', 'Aquabook Bluey - com Caneta Mágica', 'Livro de colorir inspirado na adorável série de animação "Bluey" que cativa o coração das crianças. Com ilustrações encantadoras dos personagens amados, este livro proporciona momentos de diversão e criatividade enquanto os pequenos fãs dão vida às aventuras da família Bluey.Dentro das páginas deste livro, as crianças encontrarão uma variedade de cenas emocionantes protagonizadas pela Bluey, sua família e seus amigos, esperando para serem preenchidas com cores vibrantes e alegres.', 29.9, 19.95, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luapyr18h36o35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F23691900446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
