INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13346338558', 'Shampoo Head & Shoulders Men 3em1 400ml', 'O Shampoo Head & Shoulders 3 em 1 possui 3 benefícios: Limpa profundamente, protege contra a caspa e suaviza o cabelo. Elimina até 100% da caspa*.Sua fórmula com pH balanceado possui uma tecnologia inteligente: Age diretamente no couro cabeludo, com 2x mais deposição** de ativos anticaspa. Um escudo de proteção duradouro.Use diarimente para ter um cabelo lindo e couro cabeludo bem cuidado.Um Shampoo que limpa, protege e suaviza só podia ser Head & Shoulders.Você até 100% livre de caspa* e 100% confiante.Confia, aqui é Head & Shoulders: experimente a marca N°1 de shampoo do mundo***. O Shampoo que limpa profundamente, protege contra a caspa e suaviza o cabelo.*Caspa visível, com uso regular. **Mais ingredientes anticaspa no couro cabeludo vs. tecnologia H&S anterior.***Cálculo de Procter & Gamble baseado em parte nos dados informados por NielsenIQ através de seus bancos de dados sindicados para a categoria de Shampoo para o período de Julho de 2022- Junho de 2023, para o banco de dados total do país, de acordo com a hierarquia de produtos padrão da NielsenIQ. Copyright © 2023, The NielsenIQ Company. • DEIXE SEU CABELO LINDOE cuide do seu couro cabeludo • LIMPA PROFUNDAMENTE, PROTEGE CONTRA A CASPA E SUAVIZA O CABELO • Fórmula com tecnologia inteligente: efetiva contra a caspa* e suave com o seu cabelo. Deixe seu cabelo lindo.*Caspa visível, com uso regular • Uso diário recomendado. Fórmula com pH balanceado • Experimente Head & Shoulders a marca de shampoo n° 1 do mundo*** • Um cuidado exclusivo do seu cabelo e couro cabeludo', 39.29, 36.28, NULL, 'Beauty > Men''s Care > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-lu6f395iscbn58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F13346338558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15048586828', 'Escova Elétrica Oral-B Disney Pixar Cars + 2 Pilhas AA', 'Escova Dental Oral-B Cars Disney Pixar + 2 Pilhas AA A Escova de Dentes Elétrica Oral-B Kids Pixar Cars para crianças maiores de 3 anos combina a diversão dos Carros com a limpeza suave e eficaz de uma escova de dentes Oral-B. Especialmente projetada para crianças, esta escova limpa os dentes suavemente e remove mais placa bacteriana do que uma escova manual normal, protegendo a saúde do seu filho. Além disso, sua cabeça redonda possui cerdas extra macias que protegem a gengiva dos pequenos. A escova de dentes elétrica Oral-B Kids possui um cronômetro para que as crianças escovem os dentes por dois minutos, tempo de escovação recomendado pelos dentistas, que ajudará seu filho a desenvolver bons hábitos de escovação para toda a vida. A escova é compatível com todos os refis de escovas elétricas Oral-B e possui cabo emborrachado, resistente à água e ergonômico, adaptado para as crianças. Para transformar a escovação ainda mais divertida, Oral-B recomenda o uso do aplicativo Disney Magic Timer, com adesivos, conquistas e muito mais para ajudar na saúde bucal infantil. - Contém: Cabo Ergonômico Refil 2 pilhas AA * Compre produtos Oral B', 192.79, 182.99, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/dc0919ebd520caf781d14ac721b13be8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F15048586828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
