INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259775649', 'Macacão Longo Bebê Kiko Baby Pelo Bordado Ursa Com Capuz', 'Macacão Longo Bebê Kiko Baby Pelo Bordado Ursa Com Capuz Encantador e super aconchegante, este macacão longo da Kiko Baby envolve o bebê com suavidade graças ao tecido em pelo sherpa, trazendo muito conforto e um visual adorável. O destaque fica para o capuz com detalhe de orelhinhas, o laço delicado e o bordado de rostinho de ursa na pala, criando um charme irresistível. Confeccionado com manga longa e fechamento em zíper, é prático para vestir e ideal para manter a pequena aquecida. Os tamanhos RN e P possuem pés fechados, enquanto os tamanhos M e G vêm com pés abertos, garantindo conforto de acordo com cada fase. Indicado para: meninas de 0 a 12 meses Características: Tecido em pelo sherpa macio e quentinho Bordado de rosto de ursa na pala Capuz com orelhinhas Aplicação de laço Manga longa Fechamento em zíper Pés fechados nos tamanhos RN e P Pés abertos nos tamanhos M e G Informações Adicionais: Tamanho:RN ao G Cores: Off White/Rose Referência:14900 Marca:Kiko Baby', 163.99, 163.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-820ln-mnls12kx9yipcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F58259775649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28829272639', 'MISSHA Time Revolution Ampola De Reparação Noturna Bálsamo Em Bastão, 10g', 'A ampola mais vendida da Missha vem em uma vara multi bálsamo! O Bastão de Ampola de Revolução de Tempo de Tempo de Revolução de Tempo de Múltiplos Reparação de Tempo Reparação Noite Ampola de Reparação Balm Cuida efetivamente de vários sinais de envelhecimento como linhas finas e rugas. Este soro nutritivo é infundido com 77,2% de Biome Extremo, formulado com 10 probióticos diferentes para ajudar a fortalecer e hidratar, firme e levantar, melhorar a elasticidade e o brilho e iluminar e suavizar a pele durante a noite. Os ingredientes da Missha''s EXTREME são fermentados com o FERMENTO EXTREMO da Missha α™ Método de fermentação única de três etapas que oferece um método único de fermentação de três etapas que fornece estavelmente um impulso extremo de ingredientes ativos à pele. O bastão de bálsamo de ampola de reparo noturno de revolução de tempo é clinicamente comprovado para melhorar a profundidade e a aparência das rugas com efeitos duradouros por até 24 horas. Recomendado para: pele normal a seca Tamanho da caixa: Tamanho: 10g / 0,35oz. Como usar A qualquer momento. Enrole o bálsamo nas áreas com rugas e seque-as. Pastilha leve para absorver. Para um cuidado mais direcionado e aplicação, Massageie as áreas do núcleo circular.Para um cuidado mais dica: Para um cuidado mais direcionado e aplicação, Massageie as áreas de aplicação do núcleo da vara. Ingredientes dos ingredientes Óleo DE SEMENTES DE ANÚNCIO HELIANTHUS (SOLFLOR), POLIGLICERIL-2 TRIISOSTEARADO, OCTILDODECANOL, CAPRÍLICO/TRIGLICASCAPRICA, ÓLEO DE SEMENTES DE MACADÂMIA POLIGLICARIL-6 ESTERS BEHENATE, EUPHORBIA CERIFERA (CANDELILLA) WAX, MICROCRISTALLINA, POLIACILADO DE BIS-DIGLICICLECILA-2, ACETADO DE TECOL, PARKI DE BUTY