INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293928957', 'Bacia Bebê Cajovil 15 Litros Translúcida Azul Ursinho', 'Bacia Cajovil 15 Litros Translúcida A Bacia Cajovil 15 Litros Translúcida é a escolha ideal para quem busca praticidade, resistência e versatilidade no dia a dia. Com capacidade de 15 litros, ela é perfeita para realizar tarefas domésticas como lavar roupas, armazenar itens ou organizar objetos de maneira eficiente. Seu design translúcido permite fácil visualização do conteúdo, facilitando o acesso. Fabricada com material durável e de alta qualidade, essa bacia é fácil de limpar e manter, tornando-se uma opção indispensável para diversos ambientes, como lavanderia, banheiro e cozinha.Destaques:Capacidade de 15 Litros, ideal para diversas tarefas e organizaçãoDesign translúcido que facilita a visualização do conteúdoMaterial resistente e durável, perfeito para o uso diárioFácil de limpar e manterVersátil, adequada para diversos ambientes da casaCom a Bacia Cajovil 15 Litros Translúcida, você garante funcionalidade, praticidade e organização de forma simples e eficiente! Informações Adicionais:Cores: Azul Bebê Referência: 934095 Marca: Cajovil', 51.9, 51.9, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tubs & Seats', 'https://cf.shopee.com.br/file/sg-11134201-7renq-m8z1wym3rymte7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23293928957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
