INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292528585', 'Flange Bomba Combustível Citroen C3 2005 a 2012 - 182273 - T030040', 'Flange Bomba Combustível Citroen C3 2005 a 2012 182273 T030040 MOTOR 1.4/1.6 FLEX (BOSCH) Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 72.06, 72.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823p4-mok39gntgl5938', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292528585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42865342280', 'ALTO FALANTE SPYDER 8 POL TRIO MG 250W RMS 8 OHMS MÉDIO GRAVE', 'Descrição do Produto A Linha MG de médio grave, foi desenvolvida para as médias frequências, ressaltando a parte da voz presente na música , sua utilização melhora em muito a equilibrar seu som ajudando a preencher as frequências faltantes entre a reprodução do alto falante e o driver. Médio‑grave bem definido, ideal para complementar sistemas onde os graves são reproduzidos por subwoofers e os agudos por drivers/tweeters. Projeto de caixa ideal (selada ou dutada) Caracteristicas MODELO MG 8 250 8 POLEGADAS 250W DIAMETRO 8 POLEGADAS BOBINA SIMPLES 8 OHMS POTÊNCIA MUSICAL 500 WATTS PMPO POTÊNCIA RMS 250 WATTS RESPOSTA DE FREQUENCIA 75 A 3800 HZ MATERIAL DA CARCAÇA AÇO CARBONO CONJUNTO MAGNÉTICO IMÃ SIMPLES EM FERRO 1020 DIÃMETRO DO IMÃ 1 X 125 MM CONE CELULOSE COM FIBRAS COM BORDA TECIDO BOBINA 45,0 COBRE, CORPO EM FIBRA CENTRAGEM TECIDO ALTA RESISTÊNCIA Parâmetros SENS 1W/1M 92,0 DB FS 78 HZ RE 5,4 ohms 6,8 ohms QTS 0,56 QES 1,17 QMS 2,12 VAZ 10,0 LITROS Dimnesões: DIAMETRO TOTAL EXTERNO – 20,4 cm DIAMETRO CORTE CAIXA – 18,3 cm TAMANHO IMÃ TOTAL – 12,5 cm PROFUNDIDADE TOTAL – 8,0 cm Conteúdo da Embalagem 01 Alto Falante Médio Grave 8 Pol Trio MG 250W RMS 8 Ohms', 219.9, 219.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-824gs-mdxbz5b4n1mtdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F42865342280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892670097', 'ZD- STROBO FLASH BEAT IR V4 - ZD-SFB-IR V4', 'Kit Strobo Flash Beat Ir Zendel Controle RemotoStrobo inovador, compacto e de instalação simplificado..Kit composto por 1 controle remoto + 4 faróis (ativo/passivo).Permite ligar mais 14 faróis, além do que vem com o kit, totalizando 16 faróis.Modo áudio: Pisca o led conforme a batida do Som.Ajuste de nivel do microfone.Farol de Led''s com central eletrônica interna, contendo efeitos pré-programados.Possul 10 modelos de efeitos + 1 modo de efeito automático que troca de efeitos a cada 15 segundos.2 modos de trocas de cores de forma automática: modo lento e modo rápido.Troca de cores e efeitos através das chaves existentes no farol ativoou pelo controle remoto que acompanha o produto.Cada farol contêm 3 led''s com potência total de 4,5 watts por farol.Faróis com led''s RGB, com lentes de alto desempenho.Possibilita 7 cores diferentes formadas através do led RGB: Amarelo, Azul, Branco, Ciano, Rosa, Verde e Vermelho.Conteúdo da Embalagem:04 - Faróis Led''s RGB01 - Controle RemotoManualNota Fiscal', 136.13, 136.13, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rd4q-lv6i0o7ckc14ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F23892670097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397028314', 'Palheta Limpador Para-Brisa Ford Fiesta 1996 a 2007 - 200610 - PVT19', 'Palheta Limpador Para-Brisa Ford Fiesta 1996 a 2007 200610 PVT19 (HATCH) 19" motorista/passageiro - Conexão gancho Os limpadores combinam duas tecnologias mecânicas. A primeira delas é uma combinação de motor elétrico com engrenagem redutora. Ela é responsável por gerar a força necessária para acionar os limpadores. A segunda delas é um inteligente sistema de transmissão por hastes, ela converte a rotação de saída do motor no movimento dos limpadores para de um lado para o outro.Elas funcionam como uma espécie de rodo. Estas hastes arrastam uma fina tira de borracha com a função de retirar a água.', 27.4, 27.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbme-lmsdyhwzz13t34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23397028314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
