INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259706381', 'Batavo Manteiga com Sal', 'A Manteiga com Sal Batavo é perfeita para realçar o sabor de suas receitas, desde o café da manhã até pratos mais elaborados. Produzida com creme de leite pasteurizado e um toque de sal, é cremosa e saborosa. Ideal para ser utilizada tanto em preparos doces quanto salgados. * Não contém glúten * Contém lactose', 13.79, 11.71, NULL, 'Food & Beverages > Dairy & Eggs > Butter & Margarine', 'https://cf.shopee.com.br/file/sg-11134201-8259s-mqneleyzpfy924', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F58259706381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206671525', 'Natty Chews Costelinis Costela Bovina 2 Unid', 'O Natty Chews Costelinis oferece duas unidades de costela bovina desidratada, pensadas para cães que valorizam uma mastigação duradoura e natural. Desenvolvido para atender ao instinto de mastigar, este petisco ajuda a manter a higiene bucal ao contribuir para a redução da placa bacteriana e do mau-hálito. Com acabamento natural e ingrediente único, é opção de alta qualidade para recompensa, distração ou enriquecimento ambiental. FICHA TÉCNICA Quantidade: 2 unidades de costela bovina desidratada Ingrediente principal: costela bovina 100 % natural Finalidade: petisco de mastigação para cães que estimula gasto físico e mental Benefícios: estímulo do instinto de mastigar, ajuda na manutenção da limpeza bucal, promove entretenimento prolongado Público-alvo: cães de todas as idades e portes (supervisionar cães de pequeno porte) Composição: sem conservantes, sem corantes, sem ingredientes transgênicos CUIDADOS COM O PRODUTO Ofereça sob supervisão, especialmente em cães de pequeno porte ou filhotes Mantenha água fresca sempre à disposição do cão Armazene em local seco, protegido da luz direta, e feche bem a embalagem após o uso Remova a unidade assim que for muito pequena ou apresentar partes soltas Produto destinado exclusivamente para cães, não consumo humano', 21.9, 21.9, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-8262s-mlnw5jjc3zsy1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F58206671525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794423038', 'Tênis Olympikus Volcan 2 Feminino Tamanho Grande', '👟 Tênis Olympikus Volcan 2 Feminino Este é um produto original Olympikus com garantia, vendido pela B2 Online ✅ O tênis ideal para quem busca conforto, leveza e durabilidade no dia a dia chega em sua segunda versão ainda mais moderna e macia 💖💨 O Olympikus Volcan 2 conta com solado equipado com a tecnologia EVASENSE, que garante amortecimento, flexibilidade e suavidade nas passadas, tornando cada movimento mais confortável 🏃‍♀️✨ Seu cabedal em laminado com detalhes em High Frequency e pintura em degradê oferece durabilidade, estilo e toque refinado, enquanto a lingueta acolchoada e o forro em poliéster com espuma elevam o conforto ao máximo. A palmilha anatômica em EVA e poliéster com estampa exclusiva proporciona ajuste perfeito e maciez extra para acompanhar sua rotina com leveza 🌸👣 Ideal para caminhadas, atividades leves ou uso casual, o Volcan 2 combina tecnologia e design para quem valoriza bem-estar e visual moderno em um só calçado. 💡 Destaques do Produto: • 👩 Gênero: Feminino • 👟 Modalidade: Caminhada / Uso diário • ⚙️ Tecnologia: EVASENSE – leveza e amortecimento • 💎 Material: Sintético de alta durabilidade • 🩷 Palmilha anatômica em EVA • 🇧🇷 Produto Nacional 📸 Foto do produto condiz com a realidade. As imagens passam por leve edição apenas para aproximar ao máximo as cores reais.', 319.9, 249.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgpd917nm4nbf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F535071110%2F22794423038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
