INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099567525', 'Máscara Restauração Pantene Pro-V Pearls 270ml', 'Ingredientes: Cada frasco da Pantene é resultado de anos de pesquisa científica. Fórmulas exclusivas cheias de ingredientes cuidadosamente desenvolvidos, em especial nossa Provitamina que deixa os cabelos mais fortes e com uma aparência saudável de dentro para fora. Esta Máscara Intensiva Pantene Pro-V Miracles Contém: Vitamina Pro-V Aceite de Argán Aminoacidos Bom Para Você e Para o Planeta! Sem Parabenos Sem Sulfatos Sem Óleo Mineral Sem Sal Frasco reciclável Como Usar: Aplique no cabelo molhado, da mitade até as pontas, deixe agir e enxágue bem, repita uma ou duas vezes por semana ou sempre que necessário, perfeito para ser usado como base para bomba de hidratação. Todos os Ingredientes: Aqua, Bis-Aminopropyl Dimethicone, Stearyl Alcohol, Behentrimonium Methosulfate, Cetyl Alcohol, Parfum, Benzyl Alcohol, Disodium Edta, Panthenol, Panthenyl Ethyl Ether, Histidine, Hexyl Cinnamal, Citric Acid, Lysine Hcl, Argania Spinosa Kernel Oil, Ci 19140, Hydrolyzed Wheat Protein, Methylchloroisothiazolinone, Ci 17200, Hydrolyzed Wheat Starch, Methylisothiazolinone e Ci 42090.', 40.84, 40.84, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j6-mpibku7erv289e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F20099567525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
