INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29871828540', 'LAIKOU KOJIC ACID TUMERIC Sabão Iluminador Reduz Manchas Escuras Textura Suave Da Pele Rosto E Corpo', 'O clareamento de sabonete TUMÉRICO LAIKOU KOJIC ACID Reduzir manchas escuras Textura de pele suave Rosto e corpo Informações básicas do produto Rede: 120g Vida útil da prateleira de 5 anos Ingrediente principal: VITAMINA C/ RETINOL/ COLÁGENO/ÁCIDO HIALURÔNICO/MANTEIGA DE CABEÇA/VITAMINA E/ÓLEO OLEVO Características do produto O sabonete melhora a textura áspera da pele e remove o excesso de oleosidade, revelando um brilho radiante. Equilibra o tom da pele, deixando-a mais macia e luminosa a cada uso. Como usar Coloque sabão na rede espumante, molhado para criar espuma, aplique no rosto ou corpo, massageie, e enxágue bem. Cuidados com os cuidados Apenas para uso externo. Manter fora do alcance das crianças. Não swallow. Não use em peles quebradas. Evite contato com os olhos. Interrompa o uso se ocorrer sinais de irritação ou erupção cutânea. Armazenar em local fresco e seco.', 120.0, 54.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m48priailow945', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250961519%2F29871828540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
