INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492868386', '2x Hmb 1500mg - 90 Cápsulas - Bruthal Sports Supplements', 'COMPOSIÇÃO DO ANÚNCIO 2x HMB - 90 CÁPSULAS - BRUTHAL SPORTS DESCRIÇÃO DO PRODUTO "HMB da Bruthal foi especialmente concebido para apoio a síntese proteica e evitar o catabolismo muscular, ajudando o desenvolvimento muscular antes e depois do treino, bem como aumentando os resultados dos seus esforços. Estudos mostram que se você está procurando por apoio à sua estrutura celular após treino intenso, suplementar com Hmb, um metabólito do aminoácido essencial leucina, ajudará a proteger o músculo esquelético e apoiará a sua recuperação. Quando combinado com um programa de exercícios adequado, ainda promove os ganhos de hipertrofia muscular, massa corporal magra, ajuda a reduzir os danos induzidos pelo músculo esquelético e pode acelerar a recuperação do exercício de alta intensidade. Benefícios: - Apoio a Síntese Proteica; - Desenvolvimento Muscular; - Aumento De Resultados; - Recuperação Muscular. Sugestão de Uso: Ingerir 3 cápsulas uma vez ao dia."', 99.8, 99.8, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ls8r7to85oo450', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1160496125%2F22492868386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
