INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897683036', 'Camiseta Manga Longa proteção UV50 Fast Dry Masculina Speedo - CHIC RED', 'A T-shirt Manga Longa UV Protection masculina é confeccionada em malha de 100% Poliamida, superconfortável. É Indicada para atividades que exigem exposição aos raios solares, ou mesmo em momentos de lazer na praia e piscina. Detalhes do produto: Malha leve com proteção UV Logo em silk Possui proteção UV 50+ Fio com tratamento químico que garante proteção permanente Produzido com FastDry Tecido: 100% Poliamida Dicas de Uso: Não guarde a peça úmida Não use amaciantes ou produtos com alvejantes à base de cloro Evite o contato com superfícies ásperas Sua peça possui instruções específicas para lavagem, secagem e formas de passar, veja na etiqueta Cloro e bronzeadores podem manchar o produto. Após o uso, enxague bem a peça em água fria A contínua exposição à luz forte do sol e água clorada podem deteriorar alguns tipos de tecidos e cores', 179.9, 179.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-lveqqtdvqijp81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242944993%2F21897683036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
