INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50160927615', 'Alumax Vintex Vonixx Limpador De Chassi Motor Pesados 1,5 Litros', '🧪 Alumax 1,5L Vintex – Desincrustante para Limpeza Técnica Pesada O Alumax Vintex é um desincrustante concentrado, ideal para limpezas técnicas de alta exigência. Desenvolvido para atuar com eficiência em superfícies metálicas como rodas, chassis, motores, baús de alumínio e carrocerias de inox ou madeira. 🔹 Marca: Vintex 🔹 Tipo: Desincrustante 🔹 Volume: 1,5 litros 🔹 Aspecto: Líquido límpido 🔹 Aplicação: Manual, com pulverizador ou pincel 🔹 Diluição sugerida: 1:10 (pode variar conforme a sujeira) 🔹 Rendimento: Variável conforme o grau de sujidade e diluição ✅ Indicado para: 🛞 Limpeza de rodas de alumínio 🚛 Baús de caminhão ⚙️ Motores, chassis e peças metálicas 🧱 Equipamentos com resíduos de cimento, cal ou oxidação leve 🏗️ Máquinas agrícolas e industriais ⚠️ Atenção: Não utilizar em superfícies sensíveis como pintura automotiva, plásticos, vidros ou mármore. ⭐ Benefícios: 💪 Alta performance na remoção de sujeiras minerais ⏱️ Ação rápida na desoxidação e desengraxe 🧼 Facilita a limpeza técnica pesada 🔧 Ideal para uso profissional em oficinas, indústrias e estética automotiva 🧴 Modo de uso: Dilua o produto conforme indicado. Aplique sobre a superfície com pulverizador ou pincel. Aguarde de 1 a 2 minutos. Remova com jato de água em abundância. 📦 Referências compatíveis: 35269 | 2008006 🛒 Disponível nas lojas oficiais: Camillo Parts | Genuine Automotive | Edumac Parts', 46.62, 30.3, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/sg-11134201-820of-mnob31l95q0wac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F50160927615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201955758', 'Sintra Fast 500ml Vonixx', 'Quer manter o interior do seu veículo limpo, higienizado e livre de odores? Características do Produto – Multilimpador flotador universal de pH balanceado – Ação bactericida e fungicida: elimina até 99,9% de microrganismos – Seguro para painéis, cantos de portas, carpetes, estofados, couro, vinil, plásticos e superfícies emborrachadas – Conteúdo: 500 ml – Cor: verde; odor característico – Densidade: 1,00 a 1,02 g/cm³ – Marca: Vonixx Por que escolher este produto? – Limpeza rápida de sujeiras, manchas e odores – Pronto para uso, sem necessidade de diluição – Seguro para várias superfícies, sem brilho artificial ou resíduos oleosos – Mantém o ambiente do veículo saudável e agradável Dicas de Uso – Pulverizar diretamente na superfície – Espalhar com pincel, escova macia ou aplicador de espuma – Remover o excesso com pano de microfibra úmido – Secar com pano de microfibra seco Perguntas Frequentes (FAQs) – Pode ser usado em estofados e carpetes? Sim, é indicado para tecidos, couro e carpetes. – Elimina bactérias e fungos? Sim, elimina até 99,9% deles. – Precisa diluir o produto? Não, o produto já está pronto para uso. Garanta agora Sintra Fast Vonixx 500ml Higienizador Interno!', 45.9, 28.46, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-820m9-mnokyg4725mr3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F58201955758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
