INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199123538', 'Escada Escadinha Banqueta Alumínio 3 Degraus MOR Resistente Domestica 120 kg', 'Escada Banqueta Alumínio A Escada Banqueta Alumínio da Mor vem para facilitar as tarefas do seu dia a dia. Em casa ou no trabalho ficará mais fácil alcançar lugares mais altos como armários, balcões e prateleiras sem muito esforço. Dobrável, ela facilita o seu trabalho além de ser fácil de carregar, já que possui prática alça de transporte. Apesar de sua estrutura compacta, a Escada Banqueta suporta até 120 Kg e se encaixa em qualquer espaço que você precisar. Leve, prática e funcional, além de escada de 3 degraus pode ser utilizada como uma confortável banqueta. É produzida com estrutura em tubo e chapas de alumínio em conjunto com peças plásticas de polipropileno, materiais de altíssima resistência que garantem segurança e estabilidade ao utilizá-la. Como se não bastasse todas essas vantagens, ainda são fabricadas de acordo com a portaria do INMETRO N° 219, de 06 de maio de 2021, o que garante a certeza de um excelente produto! Especificações Material Alumínio Capacidade 120 kg Garantia 3 Anos MOR', 267.22, 173.7, NULL, 'Home & Living > Tools & Home Improvement > Ladders', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mg6h27fccjyib1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F23199123538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
