INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798091440', 'Tenis Feminino Floather Madri Vizzano 1450102', 'O Tênis Feminino Vizzano 1450102 Floather Madri é uma combinação perfeita de conforto, estilo e modernidade. Confeccionado em material sintético de alta qualidade, apresenta acabamento liso e um design clean, ideal para compor looks do dia a dia. Sua cores garantem versatilidade, enquanto o solado floather traz leveza e amortecimento, proporcionando conforto durante todo o dia. O modelo conta com fechamento por cadarço, garantindo um ajuste seguro e personalizado. Perfeito para diversas ocasiões, este tênis reflete a sofisticação e a essência fashion da marca Vizzano. Preto/Branco (17689) Tênis en napa preto com detalhes no cabedal em suede preto suave ao toque como nobuck, lateral e calcanhar em branco, solado em emborrachado laranja claro com frisos Branco/Preto (102246) Tênis em napa branco com textura de courino, e napa bege com texura de couro comum lateral e calcanhar em preto, solado em emborrachado laranja claro com frisos Medidas: 33 - 22,5mc 34 - 23cm 35 - 24cm 36 - 24,5mc 37 - 25cm 38 - 25,5cm 39 - 26cm 40 - 27cm Produto ORIGINAL e com Garantia. *Após comprar, não esqueça de avaliar nosso produto e nosso atendimento, seu feedback é muito importante para nós, com ele temos como medir onde manter a qualidade e onde melhorar.*', 199.99, 179.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81zu4-mklfh5cs07wj7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325939221%2F19798091440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
