INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493248754', 'HEARTSTOPPER UM PASSO ADIANTE (VOL. 3) INSPIRAÇÃO PARA A SÉRIE DA NETFLIX', 'HEARTSTOPPER UM PASSO ADIANTE (VOL. 3) INSPIRAÇÃO PARA A SÉRIE DA NETFLIX No terceiro volume da série Heartstopper, acompanhamos os primeiros desafios do namoro de Charlie e Nick enquanto os garotos viajam a Paris. A HQ que inspirou a série original da Netflix!Depois de entenderem o que sentiam um pelo outro, Charlie e Nick se tornaram oficialmente namorados, e cada dia é uma nova oportunidade para se conhecerem um pouco mais. Mas nem tudo é fácil, principalmente quando se trata de se assumir enquanto casal para o mundo. Mesmo com medo da reação das pessoas, os garotos sabem que em breve terão de contar a verdade, pelo menos para os amigos mais próximos — ainda mais quando a turma toda viaja a Paris.Enquanto decidem como dar este próximo passo, os dois vão descobrir que, não importa qual seja o desafio, eles podem sempre contar um com o outro.Essa edição contémCapa duraIlustrações em duas coresFichas sobre cada personagemUma história exclusiva sobre Tao e Elle. Informações Adicionais Autor: OSEMAN, ALICE Data Publicação: 30/12/1899 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: HEARTSTOPPER UM PASSO ADIANTE (VOL. 3) INSPIRAÇÃO PARA A SÉRIE DA NETFLIX Idioma: INDEFINIDO Páginas: 384 Edição: 1 ISBN-13: 9788555341922 ISBN-10: 8555341922', 89.9, 76.42, NULL, 'Books & Magazines > Books > LGBTQ+ Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-lpm4rrn5yo7l04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23493248754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202879417', 'Flange Traseira Fixação Coroa Shineray Jet 125cc 2023 2024', 'FLANGE DA COROA DE TRANSMISSÃO SHINERAY JET 125 Descrição do Produto — Flange da Coroa de Transmissão A flange da coroa de transmissão é uma peça mecânica responsável por conectar e alojar a coroa (engrenagem traseira) ao cubo da roda ou eixo de transmissão da moto — garantindo que a força seja passada de forma estável da corrente até a roda traseira. Função principal: Serve como ponto de fixação entre a coroa e o cubo da roda traseira, mantendo o alinhamento e o torque corretos da transmissão por corrente. Garante que a roda traseira receba a força do motor de forma precisa e segura. É fundamental para evitar folgas, vibrações ou desgaste irregular da relação transmissão (pinhão, corrente e coroa). Aplicação: Compatível com Shineray Jet 125cc usada nos anos 2023 e 2024 (aplicação comum em Jet125 e versões similares da Jet). Também compatível com outros modelos da linha que utilizam a mesma relação de transmissão, dependendo da especificação da peça. Material e Construção: Geralmente produzida em alumínio ou aço de boa resistência, oferecendo equilíbrio entre durabilidade e leveza. Projetada para suportar esforço rotacional e atrito típico da transmissão por corrente. Instalação: Troca relativamente simples em oficinas mecânicas ou por quem já tem habilidade com manutenção de motos. Deve sempre ser feita com aperto correto dos parafusos e alinhamento da cadeia para evitar falhas prematuras.', 52.0, 52.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj70sdi7pnup49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337270308%2F58202879417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25445641950', 'Desodorizador Sanitário Pato Gel Adesivo Água 38g com Aplicador e Refil 6 Discos', 'Pato Desodorizador Gel Adesivo é a solução prática e higiênica para manter seu vaso sanitário limpo e perfumado a cada descarga por até 6 semanas. Fórmula com escudo de proteção anti-manchas e anti-odor, neutralizando as moléculas de mau cheiro. Disponível em diferentes fragrâncias, como Marine, Lavanda, Citrus, Lua de Flores, Planeta das Frutas. Instruções simples de uso para garantir a eficácia do produto e segurança para crianças e animais domésticos. Apenas para uso em vasos sanitários, mantendo o ambiente limpo e agradável com praticidade e eficiência.', 30.59, 30.59, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-m7832854haxie0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F25445641950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20298866753', 'Kit 2 Inseticidas Aerossol Raid Ação Total 285ml', 'Kit 2 Inseticidas Aerossol Raid Ação Total 285ml Raid Ação Total possui fórmula de alta eficácia, que age contra insetos voadores e rasteiros. Mata formigas, baratas e moscas e acaba com problemas de infestação de mosquitos, incluindo os que podem transmitir a dengue, o zika vírus e a febre Chikungunya.', 50.69, 50.69, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkqxspcch56682', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F20298866753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897463558', 'Regulador Pressão Fiat Palio 1996 a 2004 - 136547 - 1152', 'Regulador Pressão Fiat Palio 1996 a 2004 136547 1152 (Weekend) - Motor 1.0/1.5 8v /1.6 8/16v - (Pressão - 3,0 Bar) O sistema de injeção eletrônica de combustível tem por objetivo proporcionar ao motor um melhor rendimento com mais economia, em todos os regimes de funcionamento, fornecendo uma dosagem de combustível mais precisa com resposta mais rápida. Ele tem como função ajustar a pressão em toda a linha de combustível, desde a saída da bomba até os bicos injetores. O Regulador de Pressão pode estar montado em três posições. A localização depende do sistema de injeção eletrônica utilizado.', 90.98, 90.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-820l8-mqxxplzssop336', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22897463558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598010196', 'Pastilha Freio Kia Carens 2008 a 2013 - 507115 - SYL2276', 'Pastilha Freio Kia Carens 2008 a 2013 507115 SYL2276 (Traseira) (Sistema Mando) (Com Alarme Acústico) As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 96.0, 96.0, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-ln0r9rttr1h16c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22598010196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592462291', 'Fralda Turma da Mônica Baby Jumbo M com 28un', 'A Turma da Mônica Baby uniu proteção e conforto em uma nova opção de fralda, para garantir que seu bebê cresça feliz e tenha as melhores lembranças da sua infância. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho.', 40.64, 32.13, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-820o4-mnughw7dv11hcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22592462291', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11247195689', 'Fio Dental com Haste DenTek Floss Picks Triple Clean Advanced 90un', 'Fio dental com fio de limpeza extra forte remove os alimentos, a placa bacteriana, combate o mau hálito, evita cáries e doenças gengivais. - Inclui limpador de língua que remove os germes que causam mal hálito. - Haste / Palito higienizador texturizado para limpeza dos locais de mais difícil acesso. - Fio dental com garantia que não desfia e não arrebenta. Eles são compostos por mais de 200 fios individuais, mais fino e forte e alcançam os cantinhos e espaços mais apertados. O fio dental contém flúor e sabor de menta. *Compre produtos Dentek.', 35.32, 33.82, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/br-11134207-820lp-mmrfrl6nym874f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11247195689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898226430', 'CRUZETA DIREÇÃO MEC FORD KA 2004 2005 2006 2008 FURO 14MM - 92808 - AACD06001', 'CRUZETA DIREÇÃO MEC FORD KA 2004 2005 2006 2008 FURO 14MM Comprimento 91mm - Fixa - Direção Mecânica - Com Estria - Diâmetro Furo 14mm - Cruzeta', 102.61, 102.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd65-m6qn4cehew7u25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23898226430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898069807', 'Cilindro Freio FIESTA 2002/2015 - 50414 - CCR9225', 'Cilindro Freio FIESTA 2002/2015 TRASEIRO ESQ/DIR COM ABS (13/16" OU 20,64mm EM ALUMINIO - SISTEMA ATE) O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 63.57, 63.57, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbnc-lmuu8odi9n370f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23898069807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997175978', 'Carrinho de Bebe Moises Passeio Burigotto Convert Dark Grey', 'Carrinho de Bebê Burigotto Convert O Convert permite que você configure o carrinho da forma mais adequada para cada passeio ou etapa de crescimento da criança. No formato cadeira, o sistema reversível faz com que a criança fique voltada para o condutor, ou de frente, contemplando a paisagem. No formato berço com o assento totalmente reclinado, você pode deixar a criança dormindo tranquilamente. E também pode ser acoplado com o bebê conforto (Touring X, vendida separadamente), o que permite tirar o bebê do carro e colocá-lo no carrinho sem precisar incomodá-lo. Como os recém-nascidos até aproximadamente 6 meses não têm musculatura suficiente no corpinho para se erguer, eles precisam ficar deitados a maior parte do tempo. O Convert é ótimo para situações em que os pais e mães precisam sair de casa e levar o bebê junto. Assim, o bebê ganha uma espécie de bercinho portátil, podendo ser colocado para dormir independentemente de onde estiver. Pode ser utilizado também para facilitar a locomoção do bebê pelos diferentes cômodos da casa, mantendo ele sempre perto. Para crianças recém-nascidas até 15 kg 3 em 1: Berço, Passeio e Moisés Assento reversível Encosto reclinável em várias posições Cesto porta-objetos Rodas dianteiras com giratórios Capota regulável Cinto de segurança de 5 pontos regulável em 2 posições de altura Protetor frontal removível Rodas dianteiras e traseiras removíveis Apoio para os pés regulável Freio conjugado Material de composição: Estrutura em alumínio, Tecido poliéster com espuma em poliuretano, Poliacetal, Polipropileno e EVA Barra de proteção e manopla com acabamento especial Medidas do Carrinho de Bebe Convert da Burigotto: Aberto: Altura 115 cm x Largura 57 cm x Comprimento 100 cm Fechado: Altura 107 cm x Largura 57 cm x Comprimento 40 cm Peso: 9,8kg Certificado de Registro INMETRO nº 008798/2019 – Certificado: CE-CAR/IQB 000014 53131/19-001 Produto novo, original, lacrado, importado, com nota fiscal e certificado de garantia de fábrica válido por 1 (um) ano. Aproveite e garanta já o seu Carrinho de Bebe Burigotto Convert aqui na Maçã Verde Baby! Ficamos no aguardo de sua compra!', 1138.0, 1138.0, NULL, 'Mom & Baby > Baby Travel Essentials > Strollers & Travel Systems', 'https://cf.shopee.com.br/file/sg-11134201-7qveq-ljhaz11sxn9a19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F364932311%2F20997175978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998553667', 'Cabo DisplayPort 2.1 Ugreen Macho 16-30Hz 2Metros Preto', 'Cabo DisplayPort 2.1 Ugreen Macho 16-30Hz 2Metros Preto, Largura de Banda de 80 Gbps, Certificado VESA, Núcleo de Cobre Puro, Design Durável com Liga de Alumínio e Nylon Trançado - 15384 1. Este cabo DisplayPort 2.1 Ugreen 15384 oferece alta performance para transmissões de áudio e vídeo em alta definição, suportando resoluções impressionantes como 16K a 30Hz, 10K a 60Hz, 8K a 120Hz e 4K a 144Hz. Ideal para gamers, profissionais de design gráfico e entusiastas de multimídia que buscam qualidade superior. 2. Com largura de banda total de 80 Gbps, o cabo proporciona uma transferência rápida e estável de dados, garantindo que cada detalhe da imagem seja reproduzido com clareza, sem atrasos ou perda de qualidade. A certificação VESA reforça a compatibilidade e o padrão elevado do produto. 3. O núcleo do fio é fabricado com cobre puro, material reconhecido por sua excelente condutividade elétrica, que reduz interferências e melhora a estabilidade da conexão. Essa característica é essencial para manter a integridade do sinal em transmissões de alta resolução. 4. A construção robusta com liga de alumínio e revestimento em nylon trançado torna o cabo resistente ao desgaste do uso diário, além de oferecer maior flexibilidade e proteção contra dobras e emaranhados. Essa combinação de materiais garante durabilidade e praticidade em ambientes domésticos ou profissionais. 5. Suporta o efeito visual 3D supremo, oferecendo uma experiência imersiva para jogos, vídeos e aplicações 3D. O cabo DisplayPort Ugreen é a escolha certa para quem busca performance confiável e alta qualidade audiovisual em um produto compacto e durável. Garantia 90 dias.', 248.65, 248.65, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-macz46fmxzp592', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F22998553667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792966410', 'Rotor Distribuidor Vw Logus 1993 a 1996 - 106530 - 21300', 'Rotor Distribuidor Vw Logus 1993 a 1996 106530 21300 TODOS (IGNIÇÃO ELETRÔNICA) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 42.93, 42.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lufeitmgj0u859', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23792966410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254484752', 'Batedor de Silicone Tipo Fuet com Cabo em Inox Cuisinart ® - CTG-00-SWB', 'Batedor de Silicone Tipo Fuet com Cabo em Inox Cuisinart ® - CTG-00-SWB O Batedor de Silicone Tipo Fuet Cuisinart CTG-00-SWB oferece desempenho profissional para o preparo de massas leves, cremes, molhos e claras em neve. Projetado para garantir máxima eficiência, ele combina materiais de alta qualidade com design ergonômico, proporcionando resultados consistentes e precisos em cada preparo. Sua estrutura reforçada em aço inox premium garante maior estabilidade e durabilidade, além de excelente controle durante o uso. As hastes em silicone preto de alta resistência permitem uma incorporação superior de ar aos ingredientes, tornando o processo mais rápido, uniforme e silencioso. Ideal para uso em panelas, tigelas e recipientes antiaderentes, o batedor não risca nem danifica as superfícies, oferecendo segurança total durante o preparo. Leve, confortável e fácil de manusear, é um acessório indispensável para quem busca praticidade, eficiência e acabamento profissional na cozinha. Principais Benefícios - Alta performance: incorporação superior de ar para massas e cremes mais leves - Estrutura em inox premium: maior resistência, estabilidade e durabilidade - Hastes em silicone: uso seguro em superfícies e panelas antiaderentes - Ergonômico e leve: conforto e precisão no manuseio - Design moderno: elegante, funcional e fácil de limpar Ficha Técnica Marca: Cuisinart ® Modelo: Batedor de Silicone Tipo Fuet com Cabo em Inox Cuisinart ® - CTG-00-SWB Cor: Preto e Inox Materiais: hastes em silicone e cabo em aço inoxidável Dimensões: 7.62 x 6.05 x 31.12 cm Peso: 90g Garantia: 3 Meses Imagens meramente ilustrativas.', 109.9, 79.92, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82631-mk8abd6bt1j79e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507016444%2F58254484752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692978722', 'Condensador Distribuidor Gm Opala 1969 a 1983 - 106228 - 22662', 'Condensador Distribuidor Gm Opala 1969 a 1983 106228 22662 MOTOR 4 E 6 CILINDROS (IGNIÇÃO PLATINADO)O condensador é utilizado no sistema de ignição com a finalidade de armazenar cargas elétricas durante a abertura do platinado, evitando a formação de faíscas nos contatos do platinado, o que reduziria a sua vida útil.', 17.4, 17.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd4r-m7s3ls3e8verc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23692978722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294839436', 'Hot Wheels City Ataque do Gorila - Mattel', 'A cidade Hot Wheels está em perigo! Prepare-se para muita ação e adrenalina com o Hot Wheels City Ataque do Gorila – Mattel. Nesse conjunto emocionante, um gorila gigante invade a cidade, e cabe aos pequenos pilotos usar toda a velocidade e habilidade para escapar do ataque e salvar o dia! Com pista interativa, lançador de carrinhos e um gorila articulado que reage à ação, o playset garante desafios cheios de emoção a cada corrida. As crianças podem testar diferentes trajetórias, realizar manobras radicais e criar histórias incríveis no universo Hot Wheels City. Fabricante: Mattel Ref.: JHL92 Código Barras: 194735334964 Idade recomendada: Acima de 4 Anos Dimensões da Embalagem (AxLxC): 25X31X9cm Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 269.99, 269.99, NULL, 'Hobbies & Collections > Collectible Items > Vehicle Models & Diecast', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk9hu61ef0ua76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F23294839436', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10547615065', 'Kit 2 Mata Baratas e Formigas Raid Aerossol Base Água 420ml', 'Kit 2 Mata Baratas e Formigas Raid Aerossol Base Água 420ml Raid Multi Insetos garante proteção por 24h contra a maioria dos insetos, como mosquitos, moscas, baratas, formigas e problemas de infestações em geral, incluindo os mosquitos que podem transmitir a dengue, o zika vírus e a febre Chikungunya.', 63.39, 63.39, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkpfrz8rs1gw02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10547615065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193143182', 'Sofá Namoradeira 2 Lugares Orgânico Bouclê Luxo – Balaqui', 'Transforme o seu ambiente com aNamoradeira Orgânica.Esta cadeira é a combinação perfeita de conforto, durabilidade e um design moderno, ideal para mesas de jantar, áreas de estar e até mesmo ambientes comerciais. Especificações do produto Tecido emBouclê Espuma D-23 com Alta densidade Percintas Elásticas que oferecem suporte adicional Estrutura de madeira eucalipto proveniente de reflorestamento Informações Técnicas Altura: 75 cm Largura:132cm Profundidade:70cm Peso:22kg Capacidade de Suporte: O produto suporta até 120 kg Produto embalado Altura:77cm Largura:131cm Profundidade:70cm Peso:22 kg Observações Importantes O produto tem 3 meses de garantia contra defeitos de fabricação Produto possui uma embalagem segura, feita para evitar danos durante o transporte O Produto entregue é montado A cor real pode variar ligeiramente devido às configurações da tela e ao tratamento das imagens O Prazo de envio é de 8 dias úteis após a confirmação da compra e enviamos para todo o Brasil Não nos responsabilzamos por subida de escada no ato da entrega Perguntas Frequentes Como devolimpar? Realizar a limpeza do tecido com um pano seco ou levemente umedecido Quantos produtos irei receber nesta compra? Você receberá 1 volume, ou seja, apenas uma Namoradeira Orgânica. Para mais informações ou assistência com sua compra, nossa equipe está à disposição para ajudar', 1799.9, 1489.9, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-m7saahkvbfi517', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F758814499%2F23193143182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097330937', 'Creme De Pentear Widi Care Encaracolando A Juba 500g', 'O Creme De Pentear Widi Care Encaracolando A Juba 500g vai além de um simples cuidado capilar, é um ritual que define, nutre, condiciona, hidrata e empodera suas madeixas. Com a poderosa combinação de ativos como Manteiga de Murumuru Orgânica, Óleo de Linhaça Dourada e Extrato de Avelã, essa fórmula é simplesmente MARA! Agora é o momento de soltar sua juba, amar seus cachos e sentir-se plena, celebrando toda a beleza natural dos seus cabelos encaracolados. Este creme de pentear não é apenas um produto, é um convite para abraçar a autenticidade dos seus cachos e exibir sua verdadeira essência com confiança. Benefícios: Definição Excepcional: Proporciona uma definição excepcional aos seus cachos, realçando a beleza natural dos fios encaracolados. Nutrição Profunda: A Manteiga de Murumuru Orgânica oferece nutrição intensiva, deixando os cabelos macios e saudáveis. Hidratação Prolongada: O Óleo de Linhaça Dourada proporciona uma hidratação prolongada, mantendo os cachos hidratados ao longo do dia. Ação Condicionante: Com Extrato de Avelã, o creme condiciona os fios, promovendo uma textura suave e maleável. Controle Eficaz do Frizz: Controla de forma eficaz o frizz, proporcionando cabelos mais disciplinados. Mantém a aparência dos cachos mais alinhada e suave. Proteção e Fortalecimento: Protege os fios contra danos externos, fortalece a estrutura capilar, prevenindo a quebra. Modo de usar: Aplique o creme em mechas finas com cabelos úmidos, começando pela nuca e subindo. Deixe secar naturalmente ou use um difusor para manter a definição dos cachos. Sobre a marca: A WIDI CARE está presente no mercado de beleza há mais de 10 anos. Iniciou atendendo os principais salões cariocas e, posteriormente, expandiu por todo o Brasil com linhas profissionais. Em 2016, a empresa chegou à casa de suas consumidoras com a linha home care destinada a todos os tipos de fios - sejam eles cacheados, lisos, alisados ou coloridos. Afinal, a WIDI CARE acredita que toda beleza importa. Com mais de 80 produtos em linha e de fabricação própria, o portfólio da WIDI CARE oferece uma gama de tratamentos para todos os segmentos, sejam eles profissionais, semiprofissionais e home care, todos com forte apelo visual e características marcantes, como fragrâncias suaves, texturas únicas e resultados exclusivos.', 80.87, 65.89, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-825az-mqxdoq44tyiv51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22097330937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897546428', 'Rolamento Semi Eixo Câmbio Fiat Palio 2001 a 2012 - 1331345 - IR10165N', 'Rolamento Semi Eixo Câmbio Fiat Palio 2001 a 2012 1331345 IR10165N (WEEKEND) 1.0/1.3/1.4 - DIANTEIRO - (23x47,22x27mm) Rolamento é um dispositivo usado para permitir o movimento rotacional ou linear, reduzindo o atrito e o estresse. Os rolamentos reduzem o atrito através de rolo ou esferas de metal liso, que rolam sobre superfícies internas e externas igualmente lisas. Estas esferas ou rolos sustentam a carga, permitindo que o dispositivo gire suavemente.', 68.44, 68.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lvl1jzjz2nik4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22897546428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097143214', 'Multiuso Organizador Sapateira Berlim 4 Portas Com Pés de Madeira', 'Sapateira Berlim - Rede Móveis Multiuso Sapateira um móvel sofisticado e próprio para pessoas exigentes com organização. Seus sapatos, sapatilhas, melissas, tênis, chinelos e sandálias ficarão arrumados em um móvel compacto. Além disso, o produto possui uma fácil montagem. Sapateira Berlim - Rede Móveis Dimensões Medidas: Altura: 156 cm Largura: 66 cm Profundidade 23 cm OBSERVAÇÕES 4 Portas; Dobradiças metálicas; Pés em madeira Pintura UV Matéria Prima: MDP Garantia (meses): 3 Imagens meramente ilustrativa, não acompanha itens de decoração. Não limpar com álcool ou qualquer outro produto químico. Para limpeza e conservação do seu móvel, não use produto abrasivo como álcool, solventes, acetonas e etc... Use somente um pano macio e seco. A Loja Não Oferece Serviço De Montagem. Todos os nossos móveis possuem manual de montagem com passo a passo para você ou seu profissional de confiança montá-lo.', 749.29, 729.9, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lo77djajse9f43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F444869236%2F23097143214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797054491', 'Medidor Combustível PALIO 2006/2011 - 17379 - T010129', 'Medidor Combustível PALIO 2006/2011 Combustível: Flex (SISTEMA BOSCH) O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 100.7, 100.7, NULL, 'Automobiles > Automobile Spare Parts > Fuel System', 'https://cf.shopee.com.br/file/sg-11134201-7rblv-lmxerrl90ndl36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22797054491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092407658', 'Kit Desodorante Aerosol Rexona V8/Amarelo 150ml - 12 Unidades', '• O Desodorante Antitranspirante Aerosol Masculino Rexona V8 oferece 72 horas de proteção que se adapta a você; • Este antitranspirante possui um controle inteligente do odor e suor, com proteção que se ativa com o calor do seu corpo; • Desenhado para combater o suor que causa o mau odor e manter você fresco e confiante o dia todo; • O antitranspirante masculino Rexona V8 possui uma formulação com 0% de álcool etílico; • Desodorante com uma fragrância herbal amadeirada, garantindo sensação de frescor durante o dia inteiro; • Este desodorante antitranspirante não afeta a camada de ozônio, possui lata em alumínio 100% reciclável e é feito com energia elétrica 100% renovável. Conheça o novo Desodorante Antitranspirante Aerosol Masculino Rexona V8, desenvolvido para garantir controle inteligente do suor e do mau odor. Com tecnologia que se ativa com o calor do seu corpo, ele oferece 72 horas de proteção contínua, adaptando-se ao seu ritmo e às condições da sua pele para manter você seco, fresco e confiante ao longo do dia. Sua fórmula avançada foi desenhada para se adaptar às condições das axilas, a fim de proporcionar um controle altamente eficiente do suor e do odor por 72h. Atua em sincronia com a resposta natural do suor do corpo para fornecer controle eficaz da umidade, adaptando-se ao pH do corpo para formar uma barreira que combate o suor. A prevenção do suor prejudica o crescimento de bactérias causadoras de odores, o que leva a um controle eficaz do odor, mesmo nos momentos mais intensos. Sua formulação possui 0% de álcool etílico. Sua fragrância, herbal e amadeirada, garante a sensação de frescor durante o dia inteiro. Para melhores resultados, agite bem antes de usar e aplique nas axilas secas a uma distância de 15 cm. Este desodorante antitranspirante não afeta a camada de ozônio, possui lata em alumínio 100% reciclável e é feito com energia elétrica 100% renovável.', 242.84, 242.84, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-82593-mqlzz1xsix3g6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22092407658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209452061', 'Salgadinho Onda Requeijão Elma Chips Cheetos', 'Cheetos Onda é o salgadinho de milho assado, perfeito para compartilhar e se divertir a qualquer hora! Com o sabor irresistível de requeijão e o formato divertido de onda, é a combinação perfeita de cremosidade e crocância. Alérgicos: Contém lactose, derivados de leite e soja. Pode conter cevada, trigo, centeio e aveia. Contém glúten.', 15.49, 15.49, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqneljwydn2le2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58209452061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899829042', 'Capa Teclado TYPECASE Samsung Galaxy Tab A9+ 2023 11 pol', 'Capa Teclado TYPECASE para Samsung Galaxy Tab A9+ ou Tab A9 Plus 2023 (11 polegadas) Teclado Mecanismo Tesoura, Teclas Gravação a Laser e Percurso de 0,8 mm para Toques Firmes e Confortáveis, Sem Retroiluminação 1. Teclado removível e portátil A capa teclado TYPECASE KB16S-A9P para o Samsung Galaxy Tab A9+ 2023 oferece um teclado removível, permitindo usar seu tablet com ou sem a parte do teclado. Isso proporciona uma experiência de digitação prática e versátil, ideal para quem busca produtividade em qualquer lugar. 2. Teclas com mecanismo de tesoura e percurso de 0,8 mm O teclado possui um mecanismo de tesoura, proporcionando um toque firme e preciso. O percurso de 0,8 mm das teclas garante respostas rápidas e uma digitação confortável, ideal para quem precisa de agilidade no trabalho ou no estudo. 3. Layout de teclas otimizado para digitação eficiente Com teclas de 13,8 mm e espaçamento de 3,8 mm entre elas, o teclado oferece fácil reconhecimento tátil, permitindo digitar rapidamente com menos erros. O layout das teclas foi desenvolvido para proporcionar uma experiência de digitação fluida e precisa. 4. Durabilidade com teclas gravadas a laser As teclas são fabricadas em ABS e possuem caracteres gravados a laser, garantindo que os símbolos nunca desbotem. Isso assegura uma maior durabilidade e resistência ao desgaste, mantendo a legibilidade do teclado por muito mais tempo. 5. Design elegante e funcional Com um design preto discreto e elegante, a capa teclado TYPECASE oferece não apenas proteção para o seu tablet, mas também um toque de sofisticação ao seu dispositivo. Ideal para uso diário e para quem valoriza a praticidade e estilo. Garantia 90 dias.', 244.06, 244.06, NULL, 'Computers & Accessories > Peripherals & Accessories > Keyboard & Trackpad Covers', 'https://cf.shopee.com.br/file/br-11134275-7r98o-mbfdpb18u2yg2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F21899829042', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493532289', 'Reparo Bico Injetor Nissan Livina 2009 a 2014 - 830684 - 1249', 'Reparo Bico Injetor Nissan Livina 2009 a 2014 830684 1249 (Grand) - 1.8 16v Flex - (Multi Point) (Sistema Bosch/Rochester) (4 Ponteiras + 4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 43.02, 43.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reoy-m2ewhjnegwjab2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22493532289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793516556', 'Guarda-Roupas Closet Modulado 270cm 4 Peças com 4 Gavetas e Cabideiros Multimóveis MP4321', 'Transforme o seu espaço com o Guarda-Roupas Closet Modulado 270cm 4 Peças com 4 Gavetas e Cabideiros Multimóveis MP4321 e experimente a liberdade máxima de organização pessoal! Cada detalhe deste closet oferece não só beleza, mas também funcionalidade e durabilidade incríveis. Durabilidade e funcionalidade: Produzido em MDP de 15mm com acabamento acetinado (cerca de 20% de brilho), este móvel entrega sofisticação e resistência para o seu dia a dia. Composto por 4 módulos individuais, permite que você monte da forma que melhor se adaptarem ao seu ambiente, proporcionando flexibilidade total ao seu jeito de viver. Amplo espaço interno e elegância: O closet é equipado com 14 prateleiras espaçosas (suportam até 8kg em cada), ideais para acomodar suas roupas e calçados favoritos com estilo e organização inigualáveis. Os cabideiros de madeira revestidos garantem que suas roupas, sejam longas ou curtas, fiquem sempre impecáveis. Além disso, com 4 gavetas que possuem corrediças metálicas, o manuseio dos seus pertences ganha leveza e praticidade. Valorize cada peça do seu vestuário com um design aberto e moderno que realça qualquer espaço. Conteúdo da Embalagem: 2 (dois) Módulos com Prateleiras 62cm 2 (dois) Módulos com Gavetas e Cabideiro 73cm Manual de Montagem Kit Ferragem Especificações Técnicas: Dimensões do Produto Montado - Altura: 183cm | Largura: 270cm | Profundidade: 45cm Material: MDP 15mm Acabamento: Acetinado Quantidade de Prateleiras: 14 Quantidade de Gavetas: 4 Corrediças: Metálicas *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores dos produtos podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. *Obrigatório fixar o móvel na parede. Aqui na Loja Multimóveis, você pode concluir sua compra facilmente com toda segurança. A entrega é garantida e aqui você está em 1° lugar. Imagem meramente ilustrativa. Decoração não acompanha o produto. Os produtos serão entregues desmontados e não disponibilizamos o serviço de montagem.', 1889.9, 1249.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7ra2n-m51t4ip6qv9c2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23793516556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12811875956', 'Papel de Parede Personalizado Montanhas Cute Decoração Inove', '🟢 Papel de Parede Personalizado Autoadesivo – Venda por 1m² 📏 Cálculo de Compra: Para calcular a quantidade necessária para cobrir sua parede, basta multiplicar altura x largura em metros quadrados. Exemplo: parede de 3m x 3m = 9 m² → você precisará de 9 unidades, já que cada unidade cobre 1 m². ✨ Características do Papel de Parede: • Fácil Aplicação: Não precisa de cola! O papel é autoadesivo, rápido e limpo de aplicar. • Sobreposição: Cada rolo tem 3 mm de sobreposição, garantindo que as emendas fiquem perfeitas. • Entrega Organizada: Receba todos os rolos separados, nomeados e numerados, com manual de instruções. • Fácil Manutenção: Limpeza simples com água, sabão neutro e pano macio mantém seu papel impecável. ⚠️Observações Importantes: ✔ Emendas Precisas: Todos os modelos são conferidos e garantem 100% de encaixe lado a lado, desde que respeitada a sobreposição. 🎨 Variação de Tonalidade: As cores podem variar ligeiramente dependendo do monitor ou dispositivo. 📝 Planeje com Cuidado: Compre quantidade suficiente ou com sobras, para evitar diferenças de tonalidade caso precise de rolos avulsos. Cada pedido é feito em lote único.', 44.9, 34.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhq8wesijhou23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F12811875956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12680267245', 'Papel de Parede Personalizado Costela de Adão Verde', 'Papel de Parede Personalizado Autoadesivo - Venda por 1m² Cálculo de Compra:Para calcular a quantidade necessária para cobrir uma área específica, basta multiplicar a altura pela largura da parede ou local que você deseja decorar em metros quadrados. Por exemplo, se a área a ser decorada tem 3m x 3m, você precisaria de 9 unidades, já que cada unidade abrange 1m². Características do Papel de Parede: Fácil Aplicação: Não é necessário usar cola. O papel de parede é autoadesivo, garantindo uma aplicação rápida e limpa. Sobreposição: Cada rolo possui uma sobreposição de 3 milímetros para garantir que todas as emendas se encaixem perfeitamente. Entrega Organizada: Seu pedido será entregue com todos os rolos separados, nomeados e numerados no rodapé, acompanhados de um manual de instruções para facilitar a aplicação. Fácil Manutenção: Limpeza leve com água, sabão neutro e um pano macio é tudo o que você precisa para manter seu papel de parede com uma aparência impecável. Observações Importantes: Emendas Precisas: Nossos modelos são feitos com gabaritos e conferidos, garantindo que todas as emendas casem 100% lado a lado, desde que haja a sobreposição de 3 milímetros de um rolo sobre o outro. Variação de Tonalidade: Lembre-se de que a tonalidade do produto pode variar ligeiramente devido à qualidade e calibração de cores de monitores ou dispositivos móveis. Planeje com Cuidado: Para garantir uma aparência consistente, recomendamos comprar a quantidade suficiente ou com sobras para cobrir a parede ou local que deseja decorar. Caso falte ou haja danos e você precise de rolos avulsos, saiba que as tonalidades podem divergir, já que cada pedido é produzido em um lote único.', 44.9, 44.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhq8wwg6qo269d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F12680267245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998202182', 'Espelho Freio Dianteiro Nxr 125 Bros Ks Es 2003 a 2005 Nxr 150 Bros Es Ks 2003 2004 2005 2006 a 2015', 'Aplicação do Espelho de Freio Dianteiro: Compatível com: Aplicação Honda: Nxr125 Bros Ks Es 2003 a 2005 Nxr150 Bros Ks Es 2003 a 2015 Obs: Considerar o ano modelo de sua moto. Exemplo: ano fabricação 2009 / ano modelo 2010 - Equivale ao ano 2010. Especificações técnicas: Código do fabricante: 0015-EP A Marca: A Cobreq é a marca líder mundial de pastilhas para veículos comerciais, mercado para equipamento original e de reposição, oferecem segurança e desempenho em todos os produtos, que apenas os produtos originais conseguem garantir. Prazo de Garantia: 3 meses para defeitos de fabricação. Importante: - Para a instalação correta do produto, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto ou vícios de instalação.', 175.4, 175.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7ratv-maoji0jpoqxu0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369066095%2F20998202182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20477225308', 'Patrulha Canina Lap Top Bilíngue - Candide', 'Patrulha Canina Lap Top Bilíngue - Candide É um hit entre as crianças ter seu próprio laptop, levar na escola e mostrar aos amiguinhos. Mas o melhor é que esses pequenos aparelhos coloridos são didáticos e úteis, além de divertidos é claro. Estimulam os sentidos das crianças ao mesmo tempo em que ensinam! Com o laptop infantil Paw Patrol Bilíngue da Candide a criançada aprende brincando! Musical ele vem com diferentes atividades, sendo eles: letras, palavras, ortografia, perguntas e respostas, soma, divisão. São incontáveis atividades, muitas delas bilíngue, para a garotada aprender onde estiver. Idade recomendada: a partir de 2 anos de idade. Selo INMETRO: Em certificação.', 120.74, 120.74, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7qvf8-lezr6xerzt0va6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F20477225308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
