INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20164586912', 'Naninha Para Bebê com Coelhinho De Pelúcia Safari 15366 Buba', 'DESCRIÇÃO DO PRODUTO Aquele momento de soninho pode ficar ainda mais gostoso com a Naninha de animalzinho da Buba, pensadas e desenvolvidas para proporcionar momentos cheios de amor e conforto, o amiguinho inseparável do seu bebê. Confeccionadas em soft 100% poliéster, ainda tem o formato de um lindo animalzinho. Além disso, proporciona segurança e sensação de aconchego, enquanto a mamãe está longe. CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 1 Naninha Coelhinho Dimensões Aproximadas da Embalagem: 5 cm x 22 cm x 30 cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Pelúcia Idade Mínima Recomendada: A partir de 3 Meses Participantes: A partir de 1 pessoa Marca: Buba Referência: 15366 Garantia: 3 meses contra defeitos de fabricação Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Produto não recomendado para crianças menores de 3 anos, por conter partes pequenas que podem ser engolidas ou aspiradas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto 100% original, lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 69.2, 60.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-22110-i1nglil6v9jvee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F20164586912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797329119', 'Colágeno Verisol e Ácido Hialurônico + Hidratante Labial - Renova Be', 'Kit Colágeno Verisol + 1 Hidratante Labial Cereja Renova Be (Escolha o sabor) Somos Loja Oficial Renova Be. Trabalhamos com produtos originais, direto da fábrica, com qualidade, tecnologia e segurança. Informações do produto • Produtos com controle de qualidade na fabricação • Validade de 24 meses após a data de fabricação Este kit combina suplementação e cuidado diário, ideal para quem busca praticidade e cuidados com a pele de dentro para fora. O que contém o kit • 1 Colágeno Verisol Renova Be (sabor conforme variação) • 1 Hidratante Labial Cereja Renova Be Sabores disponíveis • Tangerina • Limão • Cranberry • Chocolate • Frutas Tropicais ⚠️ Importante: o sabor Chocolate contém lactose Colágeno Verisol Renova Be • Auxilia na firmeza e elasticidade da pele • Contribui para cabelos e unhas • Contém Ácido Hialurônico e Biotina Modo de consumo • Consumir 1 vez ao dia, preferencialmente à noite antes de dormir Hidratante Labial Cereja • Hidratação profunda • Auxilia na prevenção de ressecamento • Proteção diária Modo de uso • Aplicar sempre que necessário', 185.57, 109.9, NULL, 'Health > Food Supplement > Beauty Supplements', 'https://cf.shopee.com.br/file/br-11134207-820l9-mnn6mcqcoo3lc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F668638669%2F22797329119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
