INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299207354', 'Cera Líquida Amarela Ingleza Maxx 750ml', 'Cera autobrilhante! Ideal para proteger, conservar e dar brilho em todos os tipos de pisos. Fácil e prática de usar, não necessita lustrar. Dispensa o uso de enceradeira. Modo de usar: Aplique uniformemente sobre a superfície limpa e seca, com auxílio de um pano macio envolvido em um rodo. O brilho é instantâneo: secou, brilhou! Em piso virgem, completamente isento de cera ou após remoção, o melhor resultado ocorrerá após a terceira camada, com o intervalo de 45 minutos entra as aplicações. Atenção! Se o piso estiver com acúmulo de cera, use o Tira Ceras Ingleza para removê-la. Não use solventes.', 23.0, 23.0, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-821ep-mgxwiw8v2olqc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1658245933%2F22299207354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897499415', 'Seladora Para Madeira Base Agua 3,6l Sparlack Coral', 'Preparação de superfícies, visando eliminar porosidades e riscos de lixas. Possui excelente poder de enchimento a boa proteção anticorrosiva. O uso deste produto é exclusivo a profissionais devidamente treinados. CATÁLISE / DILUIÇAO: 100 partes em volume de Ultrafill Primer Alto Sólidos 020. 100 a 150% de Thinner para Laca Nitrocelulose 437. APLICAÇAO: Aplicar 2 a 3 passadas cruzadas com intervalo de 5 a 10 minutos entre passadas. Regular a pressão de ar entre 45 a 50 lbs/pol2. APLICAR SOBRE: Wash Primer Fundo Fosfatizante 05.00.00045 Massa Rápida 01.30.00031 Esmalte Original de Fábrica SECAGEM: Ao ar a 25oC: Toque 5 a 10 minutos Manuseio 30 minutos Final: 2 horas para lixamento PREPARAÇÃO: Desengraxar a área a ser pintada com Solução Desengraxante 400. Lixar a área a ser repintada para remover tintas descascadas e ferrugem (se necessário).', 361.68, 253.18, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-lv8wdim5iti842', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F23897499415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
