INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399662060', 'Kit Shampoo e Condicionador Melancia Meu Liso Kids', 'O Kit Meu Liso Kids Melancia, com Shampoo 300ml e Condicionador 200ml, garante limpeza suave, hidratação intensa e ação antifrizz, além de ser hipoalergênico e dermatologicamente testado. <>INDICAÇÕES$& Para quais tipos de cabelo? Liso e ondulado. Qual a indicação? Para cabelos opacos e embaraçados. Pode usar a partir de quantos anos? A partir de 3 anos. <>ATIVOS$& Quais os principais ativos? Óleo de Semente de Melancia:Nutre e hidrata os fios e controla o frizz. Aloe Vera:Garante hidratação e couro cabeludo saudável. <>MODO DE USO$& Qual a melhor forma de usar? Shampoo Meu Liso Kids Melancia Aplique o Shampoo sobre o cabelo molhado dos pequenos, evitando o rostinho. Massageie suavemente e enxágue bem. Condicionador Meu Liso Kids Melancia Após lavar os cabelos com o Shampoo, aplique o Condicionador no cabelo molhado, evitando o rostinho. Aguarde alguns instantes e enxágue bem. <>CARACTERÍSTICAS$& É produto vegano? O Kit Meu Liso Kids Melancia é vegano. É liberado? O Kit Meu Liso Kids Melancia não é liberado.', 31.0, 26.97, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7rd5e-m718c03qm53o90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F20399662060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13741121458', 'Régua poliestireno 60cm 516.0 Acrimet', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 010009/2013, SGS0040, INMETRO Régua poliestireno 60 cm - 516 - Acrimet Régua em poliestireno, com escala de 60 cm. Alta precisão da escala. Possui dois micro ressaltos na face que entra em contato com o papel para evitar o desgaste da escala. Cantos arredondados para maior segurança Detalhes: - Régua em poliestireno, com escala de 60 cm. - Alta precisão da escala. - Possui dois micro ressaltos na face que entra em contato com o papel para evitar o desgaste da escala. - Cantos arredondados para maior segurança.', 24.28, 24.28, NULL, 'Stationery > School & Office Equipment > Rulers, Protractors & Stencils', 'https://cf.shopee.com.br/file/sg-11134201-82619-ml4ykpk9qn0o73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F13741121458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
