INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198984998', 'Kit 3 Fraldas Geriátricas Bigfral Derma Plus M com 18un cada', 'O Kit contém: 3 pacotes de Fraldas Geriátricas Bigfral Derma Plus M com 18un cada. A Bigfral DermaPlus foi desenvolvida para adultos com incontinência urinária severa. Possui o exclusivo sistema de proteção total da pele, com extratos naturais hidratantes que ajudam a prevenir irritações, mantendo a pele protegida e saudável, além de sistema antiodor, trazendo até 10h de proteção e cuidado.', 286.99, 223.99, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lm6423keknkq10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F20198984998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16282244665', 'Hastes Flexíveis Cotonetes Pote 150 Unidades', 'Hastes Flexíveis Cotonetes Pote 150 Unidades Cotonetes é feito com algodão 100% puro e possui hastes plásticas flexíveis; por isso oferece toda a suavidade, conforto e absorção para o cuidado da sua pele; cotonetes é indicado para a higiene pessoal de toda a família; pode ser usado para limpar delicadamente a parte externa da orelha (desde que não atinja o canal do ouvido), como dobrinhas do pescoço e pernas do bebê, além de ser recomendado para aplicar e removedor de maquiagem. Feito com algodão 100% puro; hastes plásticas flexíveis. Oferece toda a suavidade, conforto e absorção para o cuidado da sua pele. Indicado para higiene pessoal de toda a família. *Compre Produtos Johnson''s.', 21.59, 21.59, NULL, 'Health > Personal Care > Hand Sanitizers', 'https://cf.shopee.com.br/file/6fb4f74add027fdff6032563ec62eb25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F16282244665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22191058613', 'Desodorante em Gel Secret Lavanda 45g', '"Da Um Check Wow, Voce vai amar!O Desodorante Secret Gel feminino pH Balanced Lavender protege a sua pele contra o suor e o mau cheiro nas axilas deixando-a suave e macia. Com seu formato desodorante em gel, proporciona uma proteção duradoura desde o primeiro uso. Por ser um desodorante em gel invisivel não deixa manchas brancas nem resíduos nas roupas. Além disso, o seu aroma suave e relaxante de lavanda lhe proporcionará uma sensação de frescor durante todo o dia.Esse desodorante antitranspirante em gel brinda uma proteção completa que se adapta à sua rotina, pois, controla o suor provocado pelo calor, pelo estresse e por atividades físicas. Além disso, Secret é uma marca livre de crueldade animal certificada pela PETA. Para usar o desodorante antitranspirante Secret Gel pH Balanced Lavender, remova o selo de segurança, use de 2-3 clicks por axila, e aplique diariamente apenas na região das axilas, não esquecendo de manter o frasco bem fechado após o uso.Desde 1956 Secret apoia as mulheres a demonstrarem o melhor de si, com uma hidratação e proteção contra o suor e odor nas axilas que contribuem com a confiança que elas necessitam para assumir qualquer desafio. • Protege a sua pele contra o suor e o mau cheiro nas axilas deixando-as suave e macia • Sua textura em gel invisivel proporciona uma proteção duradoura desde o primeiro uso sem deixar manchas brancas nem resíduos na aplicação • Possui um aroma suave e relaxante de lavanda que mantém uma sensação de frescor durante todo o dia • Controla o suor provocado pelo calor, pelo estresse e por atividades físicas. Além de ser é uma marca livre de crueldade animal certificada pela PETA • Fácil de aplicar, basta aplicar 2-3 clicks diretamente apenas na região de cada uma das axilas', 33.69, 32.13, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7qvez-lfzjw46gqh3ib7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22191058613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
