INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998031633', 'Bom Ciclo - 60 Capsulas - Central Nutrition', 'INFORMAÇÕES DE DESTAQUE • Óleo de Linhaça • Óleo de Borragem e de Prímula • Vitamina E • Contém 60 Cápsulas DESCRIÇÃO Suplemento alimentar em cápsulas composto por uma combinação de óleos vegetais de linhaça, borragem e prímula, além de vitamina E. INGREDIENTES Óleo de linhaça (Linum usitatissimum L.), óleo de prímula (Oenothera biennis L.), óleo de semente de borragem (Borago officinalis L.), água purificada, acetato DL-alfa-tocoferol, gelificante gelatina e umectante glicerol. MODO DE USO Ingerir 2 cápsulas ao dia ou conforme orientação de um médico ou nutricionista. IMPORTANTE Este produto não é um medicamento. Não exceder a recomendação diária de consumo indicada na embalagem. Manter fora do alcance de crianças.', 145.0, 145.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-m7kthdsz2u6l03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F22998031633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
