INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17173914507', 'Caneta hidrográfica SuperSoft Azul 1.0mm BPSS/AZZF\356551 Faber-Castell', 'As canetas SuperSoft Pen são perfeitas para escrever, contornar e desenhar. Com ponta média de 1.0mm, a SuperSoft Pen proporciona escrita macia e confortável, além do design moderno e arrojado característico da linha SuperSoft.', 21.03, 17.88, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-82583-mqxussnj99mu17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F17173914507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12356331607', 'Caneta esferográfica 1.0 Trilux Colors SM/032ESC10\343210 com 10 unidades Faber-Castell', 'A Caneta Esferográfica Trilux Colors SM/032ESC10 da Faber-Castell é ideal para quem busca mais criatividade, organização e praticidade na escrita. O estojo contém 10 canetas em cores vibrantes, perfeitas para anotações, resumos, planners, bullet journals, trabalhos escolares, atividades profissionais e uso diário. Com ponta média de 1,0 mm, proporciona uma escrita suave, uniforme e confortável, garantindo traços consistentes e excelente fluidez da tinta. As diferentes cores permitem destacar informações, organizar conteúdos e tornar a escrita mais dinâmica e visualmente atrativa. O tradicional corpo triangular ergonômico da linha Trilux oferece maior conforto durante a escrita, proporcionando melhor encaixe dos dedos e reduzindo o cansaço mesmo em longos períodos de utilização. Principais Benefícios Estojo com 10 canetas coloridas Ponta média de 1,0 mm Escrita macia e uniforme Traços consistentes e sem falhas Corpo triangular ergonômico Maior conforto durante a escrita Cores vibrantes e intensas Excelente rendimento de tinta Ideal para planners, bullet journal, resumos e organização Qualidade e tradição Faber-Castell Detalhes do Produto Marca: Faber-Castell Linha: Trilux Colors Modelo: SM/032ESC10 Tipo: Caneta esferográfica Quantidade: 10 unidades Espessura da ponta: 1,0 mm Formato do corpo: Triangular ergonômico Cores: Sortidas Aplicação: Escrita, anotações, estudos, planners, bullet journal, organização e uso diário A Caneta Esferográfica Trilux Colors Faber-Castell combina conforto, qualidade e uma ampla variedade de cores para tornar a escrita mais organizada, criativa e divertida em qualquer ocasião. INMETRO 004015/2012', 34.55, 29.37, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-8258i-mqypk32jdgjk4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F12356331607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098067465', 'Tampo para Balcão Évora Carvalho Nature 80 cm', 'Que tal o Tampo para Balcão Évora?Balcões de cozinha são móveis que ajudam a deixar a rotina mais prática e organizada, por isso eles precisam ser acompanhados pelo tampo perfeito. O modelo Évora é estruturado em material com boa resistência para as atividades do dia a dia e é ideal para complementar vários modelos de base - que precisam ser adquiridas à parte, tá? Com cor versátil, ele facilita a personalização do seu ambiente e traz muito charme, além de casar bem com outras mobílias e variadas decorações, permitindo que você coloque seu lado decorador para trabalhar e crie assim um espaço de bom gosto. Seja para preparar alimentos ou apoiar enfeites, ele é sempre bem-vindo no seu cantinho de chef ;) Cor: Carvalho Garantia em Meses: 6.0 Cores do Produto: Carvalho Instruções/Cuidados: Limpar com pano levemente umedecido Conteúdo da Embalagem: 1 Tampo - Entregue em: 1 Volume Modelo: Évora Número de Volumes: 1.0 Material: O Tampo Évora possui estrutura em MDP 15mm | acabamento fosco Material para Filtro: MDP Descrição do Tamanho: Altura: 10 cm | Largura: 80 cm | Profundidade: 53 cm Altura do Produto (cm): 10.0 Largura do Produto (cm): 80.0 Comprimento do Produto (cm): 53.0 Peso do Produto (Kg): 7000.0 Produto precisa de Montagem?: Sim, sugerimos a contratação do nosso serviço de montagem (para os CEPs em que o serviço está disponível) ou de algum profissional experiente de sua preferência Número de portas: Sem portas Número de gavetas: Sem gavetas Material da estrutura: MDP Necessita fixação na parede: Não Possui chaves: Não Possui espelho/vidro: Não Possui Fruteira: Não PROFUNDIDADE x LARGURA x ALTURA: 53 x 80 x 10 Fornecedor: HERVAL INDUSTRIA DE MOVEIS COLCHOES E ESPUMAS LTDA. Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Is Fragile: Não Número da peça: Não Produto: Tampo', 226.88, 226.88, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7renm-m81zbc2cknjqf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F23098067465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497998379', 'Flexível Freio Kia Besta 1993 a 1998 - 118796 - 8304', 'Flexível Freio Kia Besta 1993 a 1998 118796 8304 DIANTEIRO (FÊMEA/FURO - 300mm) É o componente que transmite a pressão hidráulica da tubulação para as rodas, permitindo o livre movimento das mesmas. Promover o controle do veículo em situações de baixo atrito entre pneu e solo, através da modulação da pressão hidráulica de frenagem impedindo assim o bloqueio das rodas. (Mangueira que tem a função de conduzir o fluído Hidráulico entre o cilindro mestre até a pinça de freio).', 38.66, 38.66, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd69-luzmdpq75tg620', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19497998379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
