INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12197219455', 'Painel TV 60" c/ suporte, espelho e prateleiras vidro Nairóbi Multimóveis Preto', 'Prático e moderno para deixar sua sala de estar confortável para aproveitar o aconchego do seu lar. O Painel TV até 60 polegadas com suporte, espelho e prateleiras vidro Nairóbi Multimóveis é uma escolha inteligente e super em conta para deixar o seu ambiente bonito e organizado. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, resistência e facilidade na limpeza, possui painel para TV de até 60” (suporta até 28 kg) com espaçamento para a passagem dos fios, o que deixa um visual clean e os cabos organizados. Possui 4 prateleiras em vidro, com detalhes em espelho, que deixam o móvel mais requintado e 2 nichos para acomodar os equipamentos eletrônicos. Os espelhos são de vidro (o que evita que a imagem fique distorcida) e lapidados, ou seja, passam por um processo para que as bordas não fiquem cortantes, o que garante maior segurança. Para facilitar a sua vida, este produto acompanha também o kit para fixação da TV. Muito prático e de fácil instalação, pode ser utilizado para TV’s LCD, LED e plasma de 14” a 71”. Totalmente sobreposto, acompanha gabarito de montagem que auxilia na instalação. Conta com um sistema de encaixe rápido, possui 16mm de deslocamento que permite o ajuste do encaixe das peças. Conteúdo da Embalagem: 1 (um) painel para TV 1 (um) kit com 4 prateleiras de vidro 1 (um) kit com 6 espelhos 1 (um) kit com suporte para TV Dimensões do produto montado: Altura: 108 cm | Largura: 191 cm | Profundidade: 31,5 cm Tamanho Painel TV: 136 x 90cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Não recomendamos utilizar suporte de TV articulado. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 759.9, 549.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22100-qvm8qsphv4iv9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F12197219455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16736439519', 'Caneta esferográfica Cristal Fashion 1.2 AZ/PT/VM com 3 unidades Bic', 'INMETRO 000911/2015 As canetas esferográficas BIC Cristal Fashion tem ponta grossa e escrita intensa, que proporciona maciez e um deslizar ultra fácil. Possui tampa ventilada que garante a segurança do produto. Detalhes: - Corpo transparente. - Corpo hexagonal não rola na mesa. - A cor da tampa indica a cor da tinta. - Tampa ventilada. - Ponta média de cobre de 1.2 mm com esfera de tungstênio.', 19.84, 16.67, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-824gp-mphxergxcf0i72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F16736439519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19464295765', 'Rack Estante com Suporte TV 65" e Espelho Oslo Multimóveis Madeirado/Branco', 'O Rack Estante com Suporte TV 65" e Espelho Oslo Multimóveis é perfeito para você deixar seu ambiente organizado e muito bem decorado. Produzido em MDP, que garante maior durabilidade e facilidade na limpeza, além de um acabamento superior, possui 2 portas articuladas com um excelente espaço interno para organizar seus pertences, prateleiras para que você possa personalizar a decoração e nichos para acomodar todos os equipamentos. Os detalhes com espelhos nas portas e prateleiras deixam o móvel mais requintado, criando um ambiente moderno e charmoso. Os espelhos são de vidro (o que evita que a imagem fique distorcida) e lapidados, ou seja, passam por um processo para que as bordas não fiquem cortantes, o que garante maior segurança. O painel com suporte para TV de até 65” (suporta até 30kg) possui espaçamento para passagem dos fios, que permite deixar os cabos mais organizados. Para facilitar a sua vida, este produto acompanha também o kit para fixação da TV. Muito prático e de fácil instalação, pode ser utilizado para TV’s LCD, LED e plasma de 14” a 71”. Totalmente sobreposto, acompanha gabarito de montagem que auxilia na instalação. Conta com um sistema de encaixe rápido, possui 16mm de deslocamento que permite o ajuste do encaixe das peças. Conteúdo da Embalagem: 1 (uma) estante 1 (um) kit com suporte TV 1 (um) kit com 2 (dois) espelhos 1 (um) kit com 4 (quatro) espelhos Dimensões do produto montado: Altura: 171cm | Largura: 213cm | Profundidade: 38cm Painel - Altura: 98cm | Largura: 150cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1449.9, 999.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22100-1wnu35dw24iv5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19464295765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597921053', 'Creme Hidratante de Patas Patinhas Cachorro e Gato Pet Clean - 150 g', 'PERGUNTAS FREQUENTES POSSO UTILIZAR EM FILHOTES? É indicado para todas as idades, inclusive filhotes acima de 3 meses. OS PRODUTOS SÃO APLICADOS DA MESMA FORMA PARA CÃES E GATOS? Sim! A aplicação é a mesma para ambos animais. O QUE FAZER SE OS PRODUTOS TOCAREM OS OLHOS? Se vier a tocar os olhos, recomendamos que enxague com água em abundância. OS PRODUTOS SÃO HIPOALÉRGICOS? Não, apesar de não possuírem componentes nocivos e tóxicos aos animais, o produto não é especial para cães alérgicos. O QUE ACONTECE SE O CACHORRO OU GATO LAMBER O PRODUTO? Não indicamos o consumo do produto para nenhum animal. Porém, eventualmente caso o animal venha a ingerir o produto, não haverá nenhum risco para a saúde do mesmo. Mas, caso algum comportamento diferente ocorra, indicamos a consulta de um médico veterinário de sua confiança. POSSO UTILIZAR NO MEU AMIGUINHO CASO ELE TENHA ALGUM PROBLEMA DE PELE? Não indicamos, o correto é consultar o médico veterinário do seu pet. COM QUAL FREQUÊNCIA POSSO UTILIZAR O HIDRATANTE? Pode ser utilizado diariamente, sem problemas. Faça a hidratação das patas do seu pet! Você sabia que não hidratar as patas de cães e gatos trazem riscos a longo prazo? Alergias, infecções, inflamações e outros problemas podem ser causados pelo ressecamento e rachaduras. Para a hidratação correta das patas de cães e gatos, é necessário um bom creme hidratante! O Hidratante de Patinhas para Cães e Gatos da Pet Clean é um creme elaborada especialmente para hidratar a pele das patinhas de cães e gatos. Simples, prático e eficiente, o hidratante de patinhas previne rachaduras e ressecamentos das patas do animal. BENEFÍCIOS DO HIDRATANTE DE PATINHAS PET CLEAN: - Hidratação das patinhas de cães e gatos. - Prevenção a rachaduras. - Evita ressecamentos. - Não agride o animal. - Restauração da pele. INFORMAÇÕES TÉCNICAS: Produto: Creme Hidratante de Patinhas Pet Clean - 150 g Marca: Pet Clean Tipo: Creme Animal: Cachorros e Gatos Porte: Pequeno, Médio e Grande. Raça Específica: Não Sexo Específico: Não Itens Inclusos: Creme Hidratante de Patinhas Pet Clean - 150 g Apresentação: Frasco em Plástico Composição: Álcool Cetoestearílico, Glicerina, Silicone. MODO DE USAR Certifique-se de que a patinha do seu pet não esteja suja. Aplique (em pouca quantidade) diretamente nos coxins o produto massageando e espalhando bem para não ficar resíduo. Se o produto for aplicado em excesso remova com um pano limpo e seco apenas o excesso. Evite que o pet lamba o local após a aplicação. PRECAUÇÕES Uso externo. Evite contato com os olhos e mucosas do animal. Manter em local fresco e seco, fora do alcance de crianças e animais domésticos. Caso houver a constatação de hipersensibilidade, suspender o uso. Não utilizar em filhotes com menos de 2 meses de vida. Manter longe de alimentos, medicamentos e produtos domésticos ou de higiene pessoal.', 47.9, 25.9, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-m0uhennrhcvuae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363040730%2F19597921053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392497261', 'Água Oxigenada Beauty Color 20 Volumes 1000ml', 'BeautyColor Água Oxigenada nos volumes 10, 20, 30 e 40é Indicada como agente oxidante (revelador) para colorações capilares. Com uma fórmula estabilizada, a água oxigenada Beauty Color garante uma ótima aderência ao pó descolorante. Liberada para as técnicas de No e Low poo. Textura Cremosa Produto perfumado, neutralizando o odor da amônia. Prova de Toque: Antes de usar faça a Prova de Toque. Aplique uma quantidade do produto no antebraço ou atrás da orelha; deixe a área aplicada livre e retire o produto após 45 minutos; aguarde 48 horas, e se neste período surgir irritação na pele, coceira ou ardência no local ou na sua proximidade, fica provada a hipersensibilidade da pessoa ao produto e portanto, o mesmo não deverá ser utilizado. Modo de uso: Misture a Água Oxigenada Cremosa BeautyColor na proporção 1:1,5 com as colorações BeautyColor. Exemplo: 67,5ml de Água Oxigenada Cremosa BeautyColor para 45g das colorações BeautyColor. Resultado:Desenvolvida para a mudança dos fios sem danificar, a utilização da BeautyColor água oxigenada trás resultados ainda mais incríveis! #html-body [data-pb-style="646BA6468986B"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64689880"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 51.25, 51.25, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-lmf5d95toxmhc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22392497261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10462012817', 'Garrafa de tinta Canon GI190BK Preto 135ml', 'Cartucho Canon GI190BK - Preto 135mlO cartucho Canon oferece qualidade e tintas resistentes á luz, calor e gases ambientais, durabilidade e qualidade de impressão.', 134.48, 134.48, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/sg-11134201-7qve4-lgcybr3j56qe3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F10462012817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899548102', 'Fundo Fotográfico Pet Shop Painel para Foto Cenário Em Tecido 1,20x1,70m Vertical – Vários Modelos', 'Todos os nossos Fundos Fotográficos Sublimados são confeccionados em tecido especial, com excelente acabamento e imagens nítidas que possibilitam fotos incríveis sem reflexos no resultado final. Por serem muito práticos, os fundos podem ser utilizados em estruturas como tripés (presos por garras) ou fixado em paredes e até mesmo placas de MDF com o auxílio de fita crepe ou dupla face (de formato largo, preferencialmente). Características: Tecido: Malha (estica e não amassa) Composição: 95% Poliéster + 5% elastano Gramatura: 140g m² Acabamento: Pode ser em overloque ou à laser, à depender da demanda. Ambos com acabamento perfeito que garantem sua durabilidade. ** Itens inclusos: 1 fundo fotográfico em tecido Malha ** Indicação de uso: Produção de fotos em estúdio fotográfico Informação complementar: As cores podem variar nas fotografias devido à qualidade da câmera fotográfica, ajustes/configurações da câmera, lente e iluminação do ambiente. Além disso, as configurações brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. ** Todos os nossos produtos passam pelo processo de sublimação, sendo uma etapa onde passam por uma temperatura muito alta, podendo ter uma pequena variação em seu tamanho de até 5cm.** Nossos fundos fotográficos têm uma qualidade incomparável e é simplesmente incrível! Nosso tecido é maravilhoso, proporciona um toque suave e sem marcas de dobras, as cores são bem vivas e a nitidez da resolução incrível. Praticidade e economia de espaço, podem ser lavados, dobrados, guardados e é só esticar e arrasar nas fotografias. Possui acabamento impecável, não desbota e o caimento é perfeito! Uma combinação de qualidades especiais.', 78.9, 59.9, NULL, 'Cameras & Drones > Camera Accessories > Lighting & Studio Equipments', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2o6l1fifwjbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F19899548102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592986905', 'Aéreo Modular 3 Portas Nancy Cinza/Cedro/Grafite', 'O Aéreo Modular 3 Portas Nancy é perfeito para quem precisa de um móvel versátil e que se encaixe com a necessidade do seu espaço. Foi pensado para trazer beleza e sofisticação para o seu dia a dia. O móvel conta com 2 prateleiras e 3 portas. Pensando na durabilidade do móvel, os puxadores são em alumínio no padrão preto fosco e as portas possuem dobradiças metálicas caneco 35mm. É um móvel que se encaixa no seu ambiente trazendo modernidade e praticidade. Modular: Sim Peso (kg): 34 Garantia: 06 Meses Altura (cm): 61.5 Acabamento: BP Melamínico Largura (cm): 126.7 Possui Pés: Não Possui Nichos: Não Possui Portas: Sim Tipo de Porta: Bater Possui Gavetas: Não Suporta Até (kg): 5 Profundidade (cm): 39.8 Escala de Brilho: Semi-Brilho Material da Porta: MDP Origem do Produto: Nacional Possui Cabideiros: Não Ambiente Principal: Quarto Material Principal: MDP Necessita Montagem: Sim Possui Prateleiras: Sim Acabamento da Porta: BP Melamínico Sapatas Niveladoras: Não Tipo de Guarda-roupa: Modulado Espessura do Fundo (mm): 3 Material da Prateleira: MDP Espessura das Portas (mm): 15 Tipo de Módulo do Móvel: Ponte Acabamento da Prateleira: Pintura Texturizada UV Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Puxador da Porta: Externo Espessura da Estrutura (mm): 15 Peso Máximo por Prateleira: 5 Largura do Colchão Indicado: 193cm Material do Puxador da Porta: Alumínio Tipo de Dobradiça/Corrediça da Porta: Simples O Módulo Pode ser Utilizado Individualmente: Sim Marca: Herval Composição: MDP Cor Interna: Bege Cor do Produto: Cedro/Grafite Itens Inclusos: 1 Módulo Ponte, Kit Ferragens e Manual de Montagem Cor Predominante: Cinza Linha ou Coleção: Nancy Quantidade de Prateleiras: 02 Prateleiras Quantidade de Portas: 3 Portas', 390.21, 390.21, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mr3dbyx70tfr1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23592986905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394562375', 'Mochila de Costas G Stitch Pelúcia & Paetê AZUL Luxcel - Fofura e Brilho Disney!', 'A Mochila dos Sonhos Chegou! Conforto Acolhedor e Brilho Turquesa com o Stitch! Apaixone-se pelo visual encantador desta mochila do Stitch, licenciada pela Luxcel! Perfeita para quem ama o azul e o turquesa, ela combina a fofura do personagem em uma pose cativante com um design cheio de texturas. O painel frontal apresenta um fundo de Pelúcia/Plush macio que imita o degradê das cores candy, e o bolso inferior é um show de brilho com o Glitter/Paetê Turquesa, complementando o azul vibrante da mochila. É a união ideal de estilo e conforto! Com amplo espaço interno (Tamanho G) e alças acolchoadas, esta mochila é a escolha perfeita para acompanhar as crianças em todas as aventuras do dia, mantendo os materiais organizados e a coluna confortável. Características do Produto: Marca: Luxcel (Licenciado Disney) Personagem: Stitch (Lilo & Stitch) em pose fofa e pensativa, com corações. Cor Predominante: Azul Turquesa e Lilás. Texturas Especiais: Painel Central: Estampa do Stitch com fundo em material Plush/Pelúcia macio. Bolso Frontal: Coberto por Glitter/Paetê Brilhante na cor turquesa/azul claro, com o logo Stitch. Tamanho (G): Ideal para o Ensino Fundamental e Médio, comporta cadernos grandes e pastas. Ergonomia: Alças de costas acolchoadas e ajustáveis, para máximo conforto no ombro. Organização: Amplo compartimento principal com fechamento em zíper. Bolso frontal com zíper e acabamento em glitter. Bolsos laterais em tela/rede (mesh) com detalhes em glitter, ideais para garrafas. Detalhes: Puxadores de zíper personalizados e alça de mão. Leve a fofura do Stitch e o brilho do azul para a sua rotina! A Mochila Perfeita para quem não abre mão de conforto e estilo. Garanta a sua agora! Fabricante: Luxcel Ref.: IS42411SC Código Barras: 6926845702760 Dimensões da Embalagem (AxLxC): 44X31X16cm Peso: 460g Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 299.99, 299.99, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg598cbp6bcw98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F22394562375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797283512', 'Toalha de Mesa Borboleta Decoração de Festa Veste Fácil Tecido - MSA-32', 'Capa de mesa decorativa em Tecido veste fácil. Com a Toalha de Mesa Veste Fácil Decorativa, transforme seu ambiente em segundos, adicionando charme e praticidade à sua decoração. DICA DE USO: • Decorações de mesa veste fácil • Utilizar duas mesas de plástico tamanho tradicional de 70cmx70cm lado a lado, proporcionando uma cobertura elegante e ajustada em um instante. MEDIDA DA CAPA DE MESA MONTADA: >>> Tamanho Único - 0,70x1,40 com corte laser, evitando que seu produto desfie! BENEFÍCIOS DOS PAINÉIS PISTACHE DECOR: • Arte Exclusiva. • Não amassa - tecido especial. • Não desbota, pode ser lavado quantas vezes desejar. • Alta durabilidade. • Não reflete luz. • Leve elasticidade • Acabamento à laser nas laterais. FICHA TÉCNICA: • Tecido Malha New (Que estica e não amassa). • Tecido Leve com ótimo caimento • Gramatura: 140g/m de excelente qualidade. • Composição do Tecido: 95% Poliéster e 5% de Elastano. ITEM INCLUSO: 1 Capa de mesa em tecido com acabamento à laser. OBSERVAÇÃO: Todos os nossos produtos não acompanham a mesa! DÚVIDAS FREQUENTES: TRABALHAM COM PERSONALIZAÇÃO? Não! Nós optamos para uma melhor eficiência no processo de postagem do pedido, trabalharmos com produtos prontos. POSSUI GARANTIA? Nosso painel possui garantia contra defeito de fabricação. PRODUTO COM NOTA FISCAL? Todos os produtos acompanham de nota fiscal. >>> Tem alguma dúvida antes de finalizar sua compra? Envie uma mensagem para nós que ajudaremos você! <<<', 88.9, 88.9, NULL, 'Home & Living > Decoration > Table Cloths', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqdfvpa8tvrz54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F22797283512', NULL, NULL, '2026-07-28T02: