INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198481109', 'Blusão Estampado Infantil Menina Quimby', 'Blusão estampado infantil para meninas, confeccionado em molecotton. O blusão exibe uma vibrante estampa em flores, complementada pelo design das mangas bufantes. O elástico franzido na barra e nas mangas não só adiciona um toque de elegância, como também garante um ajuste perfeito e confortável. Um visual aconchegante para acompanhar todas as aventuras do dia a dia.Tecido: Molecotton Composição: 96% Algodão 4% ElastanoModelagem: AmplaComprimento Manga: LongaForro: NãoDecote/Gola: Redondo', 174.9, 52.47, NULL, 'Baby & Kids Fashion > Girl Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-7rfh6-m9hmj5wy1j0x9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F22198481109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9459551377', 'Calculadora científica FX-82MS Casio', 'Calculadora científica FX-82MS - Casio Teclas plásticas - Projetadas e desenvolvidas pensando na facilidade de operação. S-V.P.A.M. (Super Visually Perfect Algebraic Method) - Toda a funcionalidade da já conhecida série V.P.A.M. acrescentada do visor de 2 linhas e da prática função de repetição. Isso tudo ajuda a tornar a matemática mais fácil de entender e utilizar. Editor de dados STAT - Exibição de retrocesso de etapas e edição de dados. Funções de multiexecução - Chamada fácil e rápida de fórmulas previamente executadas para edição e reexecução. Dígitos 10 + 2 - Visor para mantissa de 10 dígitos + expoente 2. Exibição em matriz - A tela de alta resolução produz gráficos de visual excelente. Características - Cálculos de frações - Combinação e permutação - Estatística (editor de dados STAT, desvio padrão, análise de regressão) - 9 variáveis - Vem com tampa protetora de encaixe - Dimensões (A x L): 19,3 cm x 76 cm.', 110.48, 87.9, NULL, 'Stationery > School & Office Equipment > Calculators', 'https://cf.shopee.com.br/file/sg-11134201-7qveq-lgd22r8gx79c29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F9459551377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
