INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213389148', 'KIT NIVEA Sabonete Líquido Derma Control Defende 250ml - 2 Unidades', 'O que é? NIVEA Derma Control Defende é um sabonete líquido corporal desenvolvido para promover uma limpeza eficaz e suave, especialmente formulado com Ácido Hialurônico Puro e Pró-Vitamina B5. Sua fórmula combina vitaminas e óleos, proporcionando hidratação intensa enquanto limpa, em equilíbrio com o pH natural da pele. Para que serve? O sabonete líquido limpa suavemente a pele enquanto a protege contra o ressecamento. Com fragrância suave e fórmula dermatologicamente testada, é perfeito para quem busca manter a pele macia, suave e saudável todos os dias. Benefícios e diferenciais: - Limpa suavemente sem agredir - Previne o ressecamento da pele - Ácido Hialurônico e Pró-Vitamina B5 - Pele macia, suave e saudável - Fragrância suave - Fórmula com Vitaminas e Óleos Modo de Uso Massageie suavemente até formar espuma e enxágue em abundância.', 31.8, 31.8, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/br-11134207-820mf-mq23346rebcw73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F58213389148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
