INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693830830', 'HAVAIANAS SLIM SQUARE METTALIC PARTY', 'Bem Vindo(a) à AT4U - Loja Oficial do Mercado Livre !! Chinelo Havaianas Slim Square Mettalic Party Este modelo é da coleção Slim Square Metallic Party, que traz aquele toque especial de sofisticação e leveza, sendo a sandália ideal para montar looks lindos e fresquinhos. Além disso, as tiras em PVC contam com aplicação do logo da marca, dando um charme a mais para o calçado. O solado, por sua vez, é macio, flexível e antiderrapante, feito de borracha de alta qualidade. Características: - Marca Havaianas; - Cores: Branco, Dourado e Citronela; - Solado Slim; - Material: Borracha; - Modelo Slim Square Mettalic Party; - Tiras lisas com logo padrão; - Feito com borracha de alta qualidade; - Confortável e macio; - Altura do Solado 1cm; - Antiderrapante; Tamanhos do Pé: 33/34...........................21,1 - 22,3cm 35/36...........................22,4 - 23,6cm 37/38...........................23,7 - 25,0cm 39/40...........................25,1 - 26,3cm *SELECIONAR A COR NO ANÚNCIO ANTES DA COMPRA* Conteúdo da Embalagem: 01 Par de Chinelo Havaianas Slim Square Mattalic Party IMPORTANTE: *Postagem em até 24h.* *Entrega Garantida.* *Produtos Originais e Certificados.* *COMPRE COM SEGURANÇA.* *Tire suas dúvidas via chat com nossos especialistas.*', 67.77, 67.77, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rd4z-m7i23no7mkig8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F22693830830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21664855684', 'Kit 2 Tintura Creme Biocolor Louro Cinza Moderno 6.1 Mini Kit', 'TINTURA CREME BIOCOLOR LOURO CINZA MODERNO 6.1 Mini kit. Biocolor proporciona cores vivas, brilhantes e duradouras, garantindo cobertura perfeita da cor desejada, inclusive dos fios brancos. Sua fórmula possui filtro solar, que protege a cor dos danos causados do dia a dia. O sachê de tratamento possui fórmula enriquecida com ingredientes condicionantes que conferem maciez aos cabelos. Com silicone, proteína e filtro UV. Cobertura perfeita dos fios brancos. Proteção total da cor. Conteúdo da embalagem: 1 bisnaga de coloração creme 50g. 1 frasco aplicador de emulsão reveladora condicionante 30 Volumes 50ml. 1 sachê de máscara de tratamento condicionante 10g. 1 par de luvas. Dicas: * Para primeira coloração, escolha um tom mais claro do que deseja. Será mais fácil escurecer do que clarear na próxima coloração. * Para cabelos longos ou volumosos, use 2 kits na primeira aplicação. * Para cabelos naturais, pode escurecer quantos tons desejar, realçar a cor natural e clarear até 3 tons. * Se são cabelos coloridos, pode escurecer quantos tons desejar ou realçar a tonalidade atual utilizando a mesma cor da última aplicação. Se for clarear, realize uma dacapagem antes de usar a coloração. * Para maior duração da cor, após a coloração, hidrate os fios semanalmente.', 23.98, 23.98, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mqme8db01lotab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21664855684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
