INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794304780', 'Jaqueta Infantil Suede Sarjado Trick Nick Preto', 'A Jaqueta Infantil Suede Sarjado Trick Nick combina conforto e estilo em uma peça versátil e sofisticada. Confeccionada em suede sarjado de alta qualidade, oferece um toque macio e aconchegante, ideal para os dias mais frescos. Seu design moderno é complementado por botões que proporcionam praticidade e um ajuste perfeito. Perfeita para compor looks casuais e elegantes, a jaqueta é uma excelente opção para garantir conforto e charme para as crianças em qualquer ocasião.', 209.99, 167.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-825b6-mr0h398snuva9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F22794304780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21226599776', 'Bicicleta De Equilíbrio Andador 4 Rodas Brinq Kids Retro Sem Pedal', 'Bicicleta de Equilíbrio Infantil Sem Pedal | Estável, Resistente e Confortável Características: - Modelo de equilíbrio, ideal para a criança aprender a se equilibrar sozinha. - Estrutura estável, rodas largas e design pensado para uso infantil. - Recomendada para crianças em fase inicial de desenvolvimento motor. - Produto de montagem simples e rápida. - Suporta até 30 kg. Benefícios: * Auxilia no desenvolvimento do equilíbrio e coordenação. * Estrutura resistente e durável. * Rodas largas que oferecem mais estabilidade. * Assento confortável para maior segurança. * Design moderno e ergonômico. * Fácil de limpar. Informações do produto: * Suporta até: 30 kg. * Dimensões: Altura 35 cm x Comprimento 50 cm. * Quadro em: Plástico PP (Polipropileno) ou PE (Polietileno de alta densidade). * Materiais: Aço carbono + EVA + Espuma + Vinil. * Fabricante: Brinq Kids.', 199.9, 169.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjse1d0otatf9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405000440%2F21226599776', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12312560896', 'Halter Emborrachado 1Kg Ferro Fundido PVC S1-R Rosa Acte', 'Características: O Halter Emborrachado de 1 kg da Acte é ideal para treinos completos, projetado para oferecer segurança e conforto. Seu revestimento emborrachado de PVC proporciona aderência e previne escorregamentos, garantindo praticidade para diferentes exercícios. Recursos: Versátil e eficiente, este halter é perfeito para uma variedade de atividades, como musculação, fisioterapia e treinos de fortalecimento muscular. Seu uso regular promove ganho de força, definição e melhora o condicionamento físico de forma prática. Design: Com design ergonômico e tamanho compacto, o halter S1-R é fácil de manusear e armazenar. Feito em ferro fundido com revestimento emborrachado, combina durabilidade com conforto, adaptando-se ao seu treino, onde quer que esteja. Especificações: Pesando 1 kg, este halter mede 19,3x6,3x6,3 cm, sendo um acessório eficiente e fácil de transportar. Ideal para iniciantes e usuários avançados, sua estrutura resistente é projetada para suportar o uso intenso em qualquer local. Uso: Seja em casa, na academia ou em fisioterapia, o halter da Acte é perfeito para treinos diários e grupos de exercício. Proporciona benefícios como ganho muscular, resistência e fortalecimento cardiovascular, podendo ser utilizado a qualquer momento. Características Gerais: Modelo: S1-R Peso: 1 kg Cor: Preto Material: Ferro fundido com revestimento em PVC Dimensões: 19,3x6,3x6,3 cm (CxLxA) Contém: 1 Halter Emborrachado Garantia de 3 meses', 43.9, 41.71, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-7rfgf-m33fo7lngf749a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424114018%2F12312560896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
