INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694398252', 'Caleçon Hanes sem Costura 5755', 'DESCRIÇÃO: O caleçon Hanes é perfeito para diversas ocasiões, pois além de garantir muito conforto ele é discreto e não marca sob a roupa, compondo looks incríveis. Cool Touch: Adapta-se a temperatura do corpo. Aumenta e diminui a sensação de frescor dependendo do ambiente e atividades praticadas. Ajuda a manter você o dia inteiro confortável. Go Tagless: Sem etiquetas costuradas. Não irrita e não arranha a pele. Seamless: Sem costura nas laterais para maior conforto e liberdade de movimento, não marca sob a roupa. COMPOSIÇÃO: 90% Poliamida e 10% Elastano. PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Lavagem a mão; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; não passar a ferro e/ou não vaporizar; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 unidade. TABELA DE MEDIDAS: P - 38 ao 40 - Cintura de 64 à 68 cm M - 42 ao 44 - Cintura de 72 à 76 cm G - 46 ao 48 - Cintura de 80 à 84 cm GG - 50 ao 52 - Cintura de 88 à 92 cm Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 27.9, 27.9, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-824jd-mefvgy5jjbie2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421856066%2F22694398252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297517779', 'Almofada Formato Infantil Pterodáctilo - Zonacriativa', 'Seu filho passa o dia descobrindo novas maneiras de se divertir, mas a hora da soneca é sempre uma dificuldade? A gente te ajuda! Com essa almofada a hora do sonho é confortável e fofinho! Com enchimento em fibra e um toque aveludado, é a melhor companhia para a hora das suas sonecas! O produto é produzido em território nacional, com enchimento em fibra e tecido em Poliéster, possui detalhes incríveis que vão fazer você se apaixonar! Se você precisa de uma mãozinha para viajar cada mais, essa almofada é para você! Com toque macio e aveludado é a companhia perfeita para te ajudar a ter um bom descanso! Não importa em qual lugar você vai tirar sua próxima soneca, essa almofada te acompanha em todos os seus sonhos! Especificações: Altura: 46cm| Comprimento: 13cm| Largura: 30cm| Enchimento: Fibra| Tecido: Poliéster Cuidados e recomendações de uso: Passar com temperatura máxima de 110° (sem vapor). Não alvejar. Permitido uso de centrifuga e máquina secadora. Temperatura máxima de lavagem 40°. Não limpar a seco.', 44.9, 44.9, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-822x0-mi087u0l5wcla3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F22297517779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
