INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263563765', 'Garrafinha De Água Inox e Pote Hello Kitty Rosa 800ML Plástico Com Tampa Alça Infantil', 'Kit Garrafa + Potinho Hello Kitty | Prático, Fofo e Perfeito para o Dia a Dia Leve mais charme e praticidade para a rotina com esse lindo Kit Hello Kitty, composto por 1 garrafa com alça e 1 potinho com tampa. Ideal para levar água, sucos, frutas, lanches e pequenas porções para a escola, trabalho, passeios, viagens ou academia. Com uma estampa delicada e divertida da Hello Kitty, o kit combina funcionalidade com um visual encantador, deixando o momento do lanche muito mais especial. A garrafa possui design moderno e fácil de transportar, enquanto o potinho é compacto e prático para organizar alimentos no dia a dia. ✨ Benefícios do produto: ✅ Kit completo com garrafa e potinho ✅ Estampa fofa e charmosa da Hello Kitty ✅ Ideal para escola, trabalho, passeios e viagens ✅ Potinho prático para lanches, frutas e porções ✅ Garrafa com alça para facilitar o transporte ✅ Ótima opção para presentear 🎀 Perfeito para quem ama produtos delicados, funcionais e com muito estilo! Garanta já o seu kit e deixe sua rotina mais prática, organizada e cheia de fofura.', 59.9, 39.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lc-mq6ht5dwqosg31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421977782%2F58263563765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
