INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52402897643', 'PASTILHA FREIO TRASEIRO DIAFRAG YAMAHA LANDER / TENERE 250 / FZ25 / FAZER 250 / CROSSER 150 / FZ15', 'Pastilha de freio Traseira. Marca: Diafrag. Aplicação: Compatível com as motos: Yamaha FZ15 2023 em diante. Yamaha Fazer 250 2011 a 2021 Yamaha Lander 250 até 2021 Yamaha Tenere 250 até 2015 Yamaha XTZ150 Crosser todos os anos Produzida com compostos orgânicos, a linha de pastilhas de freio Urban Tech é ideal para motocicletas de baixa cilindrada e uso urbano. Diferenciais: Alto conforto na frenagem; Baixo desgaste do disco de freio; Excelente progressividade; Ótimo custo benefício; Sem ruídos. As pastilhas de freio Diafrag apresentam: - Alta durabilidade comparada as pastilhas orgânicas ou kevlar; - Baixo desgaste do disco; - Melhor opção para uso em terreno molhado, seco ou arenoso. Código do fabricante: DFP-20839 EAN: 7898477873233', 23.0, 23.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-822xz-mi3i8z74m96q64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F52402897643', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898805686', 'Tripé / Cavalete Central Para Honda Pop 110 Pop110i', 'Tripé / Cavalete Central Honda Pop 110i. COMPATÍVEL COM: Honda Pop 110 2016 a 2024 Fabricante: Pro Tork. Cor: Preta. Embalagem contém: 1 Cavalete central completo, pino e mola. Características: Design arrojado e esportivo. Fácil instalação. Fixado no chassi da moto. Leve e mais resistente. Com design surpreendente. Maior capacidade de peso. Desenvolvido em material resistente a corrosão. Não enferruja. Código do Fabricante: CA-123HP. EAN: 7899730949207.', 63.9, 63.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-mdha75q2iatx44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F23898805686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20930051068', 'Forma Ovo Achatado Partes Coelhinho Especial - Porto Formas', '✨ Forma Ovo Achatado Partes Coelhinho Especial Ref. 1054 01 Unidade ideal para facilitar seu dia a dia com praticidade e eficiência! O Forma Ovo Achatado Partes Coelhinho Especial Ref. 1054 01 Unidade combina funcionalidade e qualidade, sendo uma excelente escolha para quem busca praticidade e um ótimo resultado no uso diário. Descrição Técnica: Produto: Forma Ovo Achatado Partes Coelhinho Especial Ref. 1054 Modelo: 01 Unidade Quantidade: 01 Unidade Marca: Rizzo Embalagens Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 9.9, 9.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/55937f839cf43bc4da