INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897923750', 'Combo Passatempo 365 Caça-Palavras', 'Descubra um mundo onde o tédio se torna apenas uma lembrança distante! O "Combo Passatempo 365 Caça-Palavras 01" reúne duas edições cativantes do "Almanaque Passatempo Sabe-tudo 365 Caça-Palavras 01 e 02", que transformam cada página em uma nova aventura linguística. Esses livros não são meros passatempos; são convites para uma jornada educativa que aguça não apenas seus olhos, mas também sua mente, desafiando você a explorar o vasto território das palavras de maneira divertida e envolvente. Além disso, o "Passatempo Megamente 365 Caça-Palavras" acrescenta ainda mais emoção ao combo. Com 365 quebra-cabeças meticulosamente elaborados, este livro é um verdadeiro deleite para os amantes de desafios. Cada caça-palavras apresenta palavras temáticas cuidadosamente selecionadas, garantindo horas de diversão para todas as idades.', 89.7, 85.22, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1fxjecrj9xk5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22897923750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
