INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594252109', 'Engate Reboque NIVUS 2018 a 2026 500kg', 'DESCRIÇÃO: O engate Fixo NIVUS da Engates Reforcel foi desenvolvido com máxima qualidade e segurança, oferecendo praticidade e funcionalidade para o transporte de cargas. Ideal para quem busca um produto confiável e eficiente, este engate foi projetado especialmente para o modelo NIVUS, atendendo às exigências técnicas do veículo. COMPATIBILIDADE: - Modelo: NIVUS - Ano: 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026 CARACTERÍSTICAS: - Marca: Reforcel - Material do Engate: Aço Carbono - Pintura eletrostática. - Fixo - Capacidade do reboque: 500 Kg - Incluí bola/esfera: Sim - Peso máximo sobre a bola/esfera: 30 Kg - Necessário Furação: Não há necessidade de furar - Acompanha kit de fixação: Acompanha Kit de Fixação - Regulamentado pelo INMETRO (012587/2022). - Resistência testada e garantida. PESO E MEDIDAS: - Peso Bruto: 9.505 - Altura: 26.4 - Largura: 59.4 - Comprimento: 118.19999999999999 CONTEÚDO DA EMBALAGEM: - 01 Bola Cromada (Pino Esférico) - 01 Chapa de inox - 01 Tomada Plástica (Fêmea) - 01 Fio De 1,2 Metros (4 Vias) - 01 Jogo De Parafusos + Porcas ATENÇÃO: - A empresa não se responsabiliza pela má instalação/utilização do produto.', 329.9, 329.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcjv2ar74hf65e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1567915284%2F23594252109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
