INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23702900137', 'L''Oréal Professionnel Metal Detox Máscara 250g', 'Máscara Protetora Anti-Depósito Metal Detox Protege a Fibra de Depósitos de Partículas Após Qualquer Serviço de Cor, Mechas ou Descoloração. o Metal Dentro da Fibra Cria Um Risco de Quebra e Afeta Negativamente Os Resultados da Cor Durante Os Serviços de Coloração, Mechas ou Descoloração. esta Rica Máscara em Creme Traz Cosmeticidade e Evita Que Novas Partículas de Metal Voltem. Além Disso a Máscara Protetora da L''oréal Professionnel Garante Menos Risco de Quebra do Cabelo, e Um Incrível Resultado de Cor Confiável. o Que É a Molécula de Glicoamina? a Glicoamina É o Principal Ativo do Novo Tratamento Metal Detox, Considerada a Grande Descoberta Que Permite a Entrega da Fórmula de Sucesso. Por Ser Bem Pequena, Ela Penetra Profundamente Na Fibra Capilar e Desintoxica o Fio, Promovendo Os Efeitos Satisfatórios Nos Processos de Coloração e Garantindo Cabelos Intensamente Brilhantes.', 323.9, 298.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22100-xhhkhxw4k7ivb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23702900137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
