INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593570473', 'Multímetro Alicate Amperímetro Digital Minipa Et-3201a 300v', 'Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito. O Alicate amperímetro digital ET3201A da Minipa é um instrumento pode ser usado em medições básicas na área de eletricidade, como tensão AC e DC, corrente AC e resistência. Possui a função Peak Hold, utilizada para medições de picos RMS de forma de onda, não abandonando a mobilidade de um alicate amperímetro. Segurança O ET3201A está de acordo com a IEC-61010, sobretensão CAT III 600V e CAT IV 300V. Como determinado pela norma de segurança NR-10, utilize sempre equipamentos de proteção individual A precisão é dada por ±(% leitura + número de dígitos), caso não especifi cado de outra maneira, para 23°C±5°C e umidade relativa < 75%, garantido por 1 ano. Especifi cação válida para 10% a 100% da faixa de medida. O ciclo de calibração recomendado é de 1 ano. Especificações Técnicas: Tela: Display LCD 3 1/2 dígitos 2.000 contagens; Indicação de sobrefaixa: Indica “OL” no Display; Mudança de Faixa: Manual; TRUE RMS AC; Peak Hold; Indicação automática de polaridade: Indica “-” no Display; Indicação de Bateria Fraca; Ambiente de Operação: 0°C a 50°C, U.R. Itens Inclusos: Pontas de Prova (1 par). Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito.', 369.9, 329.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3f8ejs9doagd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350962329%2F23593570473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
