INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699193719', 'Quincas Borba - Machado de Assis', 'Quincas Borba" é um aclamado romance escrito por Machado de Assis e publicado em 1891. A obra é uma continuação temática de "Memórias Póstumas de Brás Cubas" e apresenta a história de Rubião, um ingênuo professor de filosofia que herda uma fortuna do excêntrico filósofo Quincas Borba. O livro aborda temas como a loucura, a ambição, a hipocrisia social e a fragilidade da natureza humana.', 29.9, 29.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rcd9-lqtbcwvc99j5a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F18699193719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
