INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16026211871', 'Kit 18 Unidades De Azulejo Português', 'Kit de Azulejo Português Sem sujeira e fácil de aplicar! Renove sua casa sem fazer Reforma! É só aplicar o adesivo sobre o azulejo ou parede e pronto! Uma forma prática e rápida para deixar seu ambiente de forma mais autêntica e com a sua cara. Se seu revestimento estiver velhinho, não se preocupe, pois o adesivo de azulejo tem o poder de transformá-lo e deixá-lo como se fosse novo! Características Técnicas do Kit Adesivo Azulejo: Tamanho: 15 x 15 cm cada azulejo Cada Kit é composto por 18 unidades Gramatura: 130 gramas Material: 100% PVC Vinílico de Alto Brilho Textura: Sem relevo Cola: Não Necessita. Observações: Os adesivos aderem em paredes preparadas com massa corrida, gesso, tinta látex e acrílica, azulejos (sem texturas). Podem ser aplicados em superfícies planas ou com curvaturas simples, na decoração de portas, divisórias, vidros, entre outros. É necessário que a superfície seja lisa, livre de qualquer tipo de textura. Não pode estar úmida ou empoeirada, pois esses fatores prejudicam o processo de aplicação e durabilidade do material. O produto pode apresentar uma tonalidade diferente da visualizada no monitor e na fabricação em lotes, portanto é recomendado sempre comprar a quantidade desejada toda de uma vez e com sobras, produção em lotes diferentes ocasionam tonalidades diferentes.', 32.68, 32.68, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/9186000b3ed55379a855688681abbbe8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303439692%2F16026211871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57009629143', 'Armário de Cozinha Completa Compacta Armário Organizador Com Pés Reforçados', 'Armário de Cozinha Compacto e Funcional – Organização Completa Otimize o espaço da sua cozinha com este armário versátil e moderno. Ideal para quem busca praticidade sem abrir mão do estilo, ele oferece compartimentos inteligentes para eletrodomésticos, utensílios e mantimentos. Destaques do Produto: Design Inteligente: Inclui nichos superiores abertos para decoração ou itens de uso frequente. Amplo Armazenamento: Portas espaçosas e gaveta central para talheres e acessórios. Material de Qualidade: Acabamento resistente e fácil de limpar. Pés Elevados: Facilitam a limpeza do piso e garantem maior durabilidade ao móvel. Medidas Técnicas: Altura: 169 cm Largura: 86 cm Profundidade: 34 cm Dicas de Conservação: Para manter seu móvel novo por muito mais tempo, utilize apenas uma flanela seca ou levemente umedecida com água. Evite produtos químicos, solventes ou esponjas de aço. Garanta já o seu e transforme sua cozinha com praticidade e elegância!', 574.98, 343.44, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-820mq-mnlk5fj1xq8824', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F57009629143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
