INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9915739997', 'Filtro de Óleo Cbx 250 Twister / Xr 250 Tornado / Xre 300 / Cb 300r / Cb 250f Twister', 'Filtro de Óleo Valflex A função do filtro de óleo é basicamente reter as diversas partículas e impurezas existentes circuito de lubrificação, geradas pelo uso do motor, tais como oxidantes, partículas de metal, poeira e sujeiras. Praticando uma manutenção rigorosa do sistema de lubrificação, trocando o filtro de óleo regularmente você estará estendendo a vida do motor, evitando desgaste excessivo das partes móveis, aumentando o desempenho e reduzindo o consumo de combustível. Compatível Com HONDA: CB300R 2009 — 2015 CBX250 TWISTER 2001 — 2008 XR250 TORNADO 2001 — 2008 XRE300 2010 — 2020 FOREMAN TRX400FW FOUR TRAX 1995 — 2003 NT650 HAWK GT 1988 — 1991 NX350 SAHARA 1990 — 1999 NX4 FALCON 1999 — 2008 TRX 350 FOURTRAX FM 2004 — 2004 TRX 350 TM QUADRICICLO 2004 — 2004 TRX400EX FOUR TRAX 1999 — 1999 TRX400EX SPORTRAX 2000 — 2003 TRX450 FOREMAN ES 1998 — 2002 TRX450 FOREMAN S 1998 — 2002 TRX450 FOUR TRAX 1998 — 2002 XL250R 1984 — 1987 XL350R 1984 — 1990 XLX250R 1995 — 1995 XLX350 1990 — 1991 XLX350R 1990 — 1991 XR250L 1991 — 1996 XR350 1995 — 1995 XR400R 1996 — 2002 XR600R 1985 — 1998 XR650L 1993 — 2003 XR650R 2000 — 2003 Kawasaki: BN125 1998 - 2003 KLX110 2002 - 2013 KLX125 2010 - 2011 KLX140 2008 - 2011 KLX140L 2008 - 2013 KLX250 1993 - 2012 KLX300 1997 - 2007 KLX450R 2008 - 2014 KXF450 2006 - 2014 Piaggio: Beverly350 4T 2011 - 2012 Suzuki: DRZ110 2003 - 2005 Gas-Gas: SM400FSE 2003 - 2007 EC450F 2003 - 2012 Polaris: Outlaw500 2006 - 2007 Predator500 2003 - 2007 Especificações: - Marca: VALFLEX - Código do Produto: 189 - Código Original (OEM): 15412HM5A10 / 15412KFO00 - Quantidade Embalagem: 1 Unidade - Posição: MOTOR FILTRO DE OLEO - Cor: Amarelo - Tamanho: 5.5 cm - Material: Papel Celulose - Com Oring - Alta Qualidade - Máxima Eficiência - Produto Acompanha Borracha De Vedação Da Tampa Filtro De Óleo Importante !! Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 29.9, 19.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m94hgzci86iqf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F9915739997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097668855', 'Sensor Temperatura Nissan Livina 2009 a 2014 - 152719 - 4000', 'Sensor Temperatura Nissan Livina 2009 a 2014 152719 4000 1.8 16v - 2 Pinos - Preto - Água Cebolinha de temperatura ou Sensor Temperatura - Informa com precisão para o painel do veículo, como para o computador da injeção eletrônica o valor exato dessa temperatura, para evitar imprevistos e grandes prejuízos. Veículos mais novos aciona a ventoinha no lugar do Interruptor Térmico e a partida a frio nos veículos Flex. É possível encontrar o sensor de temperatura no cabeçote, ou seja, a parte mais quente do motor e onde a temperatura pode ser medida com uma precisão mais assertiva.', 100.91, 100.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd4m-lufdt5rcgayr18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19097668855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497672226', 'Retentor Comando Válvulas Gm Vectra 1993 a 1996 - 172368 - R240013P', 'Retentor Comando Válvulas Gm Vectra 1993 a 1996 172368 R240013P Motor 2.0 8/16v - (Altura - 7 mm) (Diâmetro do Alojamento - 48 mm) (Diâmetro do Eixo - 35 mm) São pequenas peças de borracha e metal, que tem como principal função vedar e reter óleos, graxas e qualquer outro tipo de fluído. Além disso, o retentor não permite que impurezas, como terra ou poeira, entrem no motor. A manutenção destas peças não tem um tempo certo estabelecido ou que possa ser programado, devendo ser feita a partir observação visual e tátil. Assim que você perceber algum vazamento de óleo no veículo, é a hora certa de trocar o retentor.', 26.11, 26.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5c-lufbsfj9wn7nc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20497672226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19019864132', 'Par de Rolamentos Roda Traseira Xj6 N / Xj6 F Nachi', 'Jogo de Rolamentos Roda Traseira Compatível com: YAMAHA XJ6 N - 2013 / 2014 / 2015 / 2016 / 2017 / 2018 / 2019 / 2020 XJ6 F - 2015 / 2016 / 2017 / 2018 / 2019 /2020 Conteúdo da Embalagem: 02 Rolamentos Roda Traseira (Vedação de borracha nos 2 lados do rolamento) 17x47x14 Especificações Técnicas: - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Confeccionado com a melhor matéria-prima - Material leve e resistente - Ótimo acabamento, proporcionando uma instalação sem adaptações - Excelente qualidade e acabamento Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Elaborado com matéria-prima de alta qualidade - Testado e aprovado dentro das normas de segurança. Importante: - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo mau uso do produto.', 119.9, 107.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3kpg0s3pk54de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19019864132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999553322', 'Vinil Beastie Boys - Licensed To Ill - Importado', 'Vinil Beastie Boys - Licensed To Ill - Importado Lançado em 15 de novembro de 1986, Licensed to Ill é o álbum de estreia gravado pela banda Beastie Boys. Este álbum está na lista dos 200 álbuns definitivos no Rock and Roll Hall of Fame. Foi o primeiro álbum de hip-hop a atingir o topo da parada Pop da Billboard. Atingiu também o número 2 da parada de Hip Hop/R&B. Repertório do LP: Lado A: A1. Rhymin & Stealin A2. The New Style A3. She''s Crafty A4. Posse In Effect A5. Slow Ride A6. Girls (Album Version) A7. (You Gotta) Fight For Your Right (To Party) (Album Version) Lado B: B1. No Sleep Till Brooklyn (Album Version) B2. Paul Revere (Album Version) B3. Hold it now, hit it (Album Version) B4. Brass Monkey (Album Version) B5. Slow And Low B6. Time To Get Ill', 299.9, 239.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-820nu-mnkmmdk4u03q3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F20999553322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199245947', 'Interruptor Cebolao Radiador GM 1969/1992 - 21709 - 17057570', 'Interruptor Cebolao Radiador GM 1969/1992 TDS MODELOS 75/70° No trânsito é importante o acionamento da ventoinha do radiador. A peça responsável por isso é o Interruptor Térmico. São comutadores (Liga-Desliga) que acionam diversos produtos no sistema de arrefecimento em função da temperatura. Localizado no radiador, aciona a ventoinha quando a temperatura ultrapassa a temperatura ideal de trabalho, evitando assim o superaquecimento do motor.', 44.78, 44.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ras8-maiv5i7eod8j66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20199245947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599159768', 'Vinil Apocalyptica - Plays Metallica, Vol. 2 (2LP) - Importado', 'Vinil Apocalyptica - Plays Metallica, Vol. 2 (2LP Transparent Blue Vinyl) - Importado Lançado em 7 de junho de 2024, Plays Metallica, Vol. 2 é o décimo álbum de estúdio da banda finlandesa de Cello Metal, Symphonic Metal e Heavy Metal Apocalyptica. Repertório dos LPs: Lado A: A1. Ride The Lightning A2. St. Anger A3. The Unforgiven II Lado B: B1. Blackened B2. The Call Of Ktulu (In Memory Of Cliff Burton) B3. The Four Horsemen (Ft. Rob Trujillo) Lado C: C1. Holier Than Thou C2. To Live Is To Die C3. One Lado D: D1. One (Instrumental) Content owned and licensed by BMG (Conteúdo de propriedade e licenciado pela BMG).', 349.9, 349.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mkmtkn0vfl6pfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22599159768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792574075', 'Mangueira Radiador Fiat Elba 1994 a 1999 - 102866 - 7598', 'Mangueira Radiador Fiat Elba 1994 a 1999 102866 7598 Inferior Radiador MTR 1.5 SPI O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 96.36, 96.36, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-ln1uuw1u715799', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792574075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797020469', 'Filtro Óleo Gm Monza 1992 a 1996 - 6841 - WO130', 'Filtro Óleo Gm Monza 1992 a 1996 6841 WO130 (Classic/GL/SE/SL) - Motor 1.6/1.8/2.0 8v EFI /(Classic/GL/GLS/SE) - Motor1.6/1.8/2.0 8v MPFI - Álcool/Gasolina - (Mecânico) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 21.01, 21.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lmqimfrff8ex91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22797020469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
