INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263204825', 'KIT 4 Pneus Lanvigator Milemax 155 R12C 88Q', 'KIT 4 Pneus Lanvigator Milemax 155/R12C Aro 12C 88/86Q 8 Lonas Dirija com tranquilidade sabendo que o Pneu Lanvigator Milemax 155/R12C Aro 12C 88/86Q equivalente a 8 Lonas atende aos mais altos padrões de segurança. Com suas excelentes capacidades de frenagem e estabilidade. O índice de velocidade Q indica especificamente uma capacidade de velocidade máxima de até 160 km/h, enquanto o índice de carga máximo é indicado por 88 (560 Kg) / 86 (530 Kg).', 1433.38, 879.84, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-824ix-mpwkx9g05j42d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F540643031%2F58263204825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898037168', 'Cano Água HYUNDAI HR 2005/2012 VC634A - 98249 - VC634A', 'Cano Água HYUNDAI HR 2005/2012 VC634A Motor 2.5 TCI/TD O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 91.24, 91.24, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rata-majb4m233gwy5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21898037168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
