INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250938971', 'BROCA PARA CONCRETO, 10 X 210MM, ENCAIXE SDS PLUS, 1PC // SPARTA', 'A Broca para Concreto Sparta 7116955, com 10 mm de diâmetro e 210 mm de comprimento, é destinada a perfuradores com mandril para cabo SDS Plus. Permite fazer furos em materiais duros como concreto, tijolo, pedra artificial e natural, sendo ideal para a realização de trabalhos de médio porte no doméstico. A preparação simples para o trabalho é garantida, pois o cabo SDS Plus é fixado de forma rápida e segura no mandril do perfurador. A broca terá longa duração graças à qualidade dos seus componentes. Sua resistência ao desgaste é notável: a pastilha de corte é feita de liga dura ??8 e temperada para uma dureza de 87-90 HRC, por isso mantém suas propriedades de trabalho por muito tempo. Para garantir alta resistência, o corpo em aço ligado temperado 40? suporta cargas dinâmicas sem risco de quebra. Além disso, a resistência à fratura é reforçada pelo revestimento protetor anticorrosivo, que previne a formação de corrosão e prolonga a vida útil da ferramenta.', 13.5, 13.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8227v-mhg7y1rbv9c7ae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58250938971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42517538466', 'AOC-ACD3521 Fones De Ouvido Bluetooth Aberto Versão AI HIFI Redução De Ruído Smart Touch Dual Mode', 'Fones de ouvido Bluetooth AOC-ACD3521 AOC-ACD3521 Aberto Orelha Fones de ouvido Bluetooth -Fones esportivos, não intra-auriculares usando, Maior vida útil da bateria! Características da chave principal: Design de clipe de clipe O leve e ergonômico, oferece uma experiência confortável ao longo do dia Cancelamento de ruído alimentado por IA Com redução avançada de ruído de chamada AI-driven, AOC-ACD3521 isola efetivamente os sons ambientais, garantindo uma qualidade de chamada cristalina mesmo no ambiente barulhento. Vida útil da bateria impressionante Desfrute de até 12 horas de música com uma única carga, tornando esses fones de ouvido perfeitos para longos deslocamentos ou viagens. Som de alta qualidade O driver dinâmico de diafragma composto de 12 mm oferece som rico e detalhado com clareza de alta definição. Experimente áudio estéreo imersivo de experiência e grave profundo para uma experiência de audição premium. Bluetooth 5.4 - Conectividade estável e eficiente Equipado com tecnologia Bluetooth 5.4, esses fones de ouvido oferecem baixo consumo de energia, emparelhamento rápido e transmissão estável. Desfrute de desempenho confiável e resistência ao sinal mais forte, mesmo em áreas lotadas. Desfrute de desempenho confiável e resistência ao sinal mais forte, mesmo em áreas lotadas. Modo de baixa Latência (38ms) Modo de latência AOC-ACD3521 38ms para sincronização suave entre áudio e vídeo, tornando-o ideal para jogos, assistir filmes, ou chamadas de vídeo. Estojo de carregamento rápido e conveniente Especificações do: Modelo do modelo: AOC-ACD3521 Material da caixa: ABS + PC Versão Bluetooth da versão Bluetooth: 5.4 Tempo de carregamento: 1 hora Faixa sem fio: Até 10 metros Tempo de reprodução: 20 horas (a 70% de volume) Interface de Interface: Tipo-C Compatível com: Todos os dispositivos habilitados para Bluetooth', 130.0, 89.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/cn-11134207-820l4-me9fktygy8li00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1022889520%2F42517538466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598565467', 'Kit 3 Car Flush Car 80 Limpeza Motor Pré Troca Óleo 400ml - Econômico Remove Borra', 'CAR FLUSH CAR80 – Limpeza Interna do Motor Antes da Troca de Óleo Mantenha o motor mais limpo, protegido e preparado para receber o óleo novo. O Car Flush CAR80 foi desenvolvido para remover borras, resíduos e impurezas acumuladas no sistema de lubrificação, ajudando a melhorar o desempenho e a eficiência do motor. APLICAÇÃO / COMPATIBILIDADE Indicado para motores Gasolina, Etanol, Flex, Diesel e GNV Uso antes da troca de óleo Compatível com motores leves e utilitários Aplicação direta no óleo velho do motor DADOS TÉCNICOS Tipo: Limpador interno de motor Função: Remoção de borras, gomas e resíduos Aplicação: Cárter e sistema de lubrificação Uso recomendado: Antes da troca de óleo Modo de uso: Adicione o produto ao óleo velho Deixe o motor em marcha lenta por 10 a 15 minutos Não acelere o motor Drene o óleo e substitua o filtro antes de colocar o óleo novo BENEFÍCIOS Ajuda a remover sujeiras acumuladas no motor Melhora a circulação do óleo novo Auxilia na redução de resíduos no sistema Fórmula com aditivos protetores Não agride juntas e retentores em bom estado Aplicação prática e rápida RECOMENDAÇÕES IMPORTANTES Utilize conforme as instruções do fabricante Recomendado realizar a troca do filtro de óleo após a aplicação Produto indicado para limpeza preventiva do motor Em caso de dúvidas, consulte um profissional especializado antes da aplicação', 112.0, 112.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-majntt4vb3pre8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1424408486%2F22598565467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00