INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599583193', 'Kit 2 Hidratante para Banho Nivea Milk 250ml', 'Loção Nivea para Banho Milk para Pele Seca 250ml Sua fórmula com Óleo de Amêndoas foi especialmente desenvolvida para desodorizar e hidratar a pele durante o banho, logo após o uso do seu sabonote diário. Sua fórmula exclusiva é rapidamente absorvida pela pele molhada. Aguarde alguns segundos e enxágue suavemente. Saia do banho com a sensação de uma pele macia e hidratada. Você pode se vestir imediatamente, sem a necessidade de aplicar uma loção hidratante após o banho. - Sensação de pele macia e suave - Fórmula com Óleo de Amêndoas - Possui ação desodorante - Não é necessário aplicar um hidratante corporal após utilização - Dermatologicamente testado - Produto Biodegradável, conforme método OECD 301 B Indicação Pele seca Modo De Uso 1) SABONETE Utilize seu sabonete diário e enxágue a pele. 2) APLIQUE Aplique esta loção deo-hidatante com a pele ainda molhada. 3) ENXÁGUE Enxágue o corpo para retirar o excesso do produto. 4) SEQUE Seque o corpo normalmente Ingredientes Aqua, Paraffinum Liquidum, Glycerin, Cetearyl Alcohol, Carbomer, Phenoxyethanol, Ethylhexylglycerin, Sodium Hydroxide, Linalool, Citronellol, Benzyl Alcohol, Alpha-Isomethyl Ionone, Citral, Geraniol, Parfum, Cera Microcristallina, Hydrogenated Coco-Glycerides, Stearyl Alcohol, Myristyl Alcohol, Prunus Amygdalus Dulcis Oil, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Geraniol, Benzyl Benzoate, BHT, Benzyl Salicylate Registro Anvisa 25351.508429/2016-96', 59.98, 59.98, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-823pv-mojpsbx0lcsudb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19599583193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598460265', 'Projetor Portátil 4k Smart Android Wi-fi Hd 1280x720 Espelhamento celular IDALI LIFE', 'Projetor Full HD Idali Life HY320 com Tecnologia Wi-Fi 6 e Bluetooth 5.0 Transforme sua experiência visual com o projetor Idali Life HY320, perfeito para amantes do cinema em casa e apresentações dinâmicas. Equipado com recursos de última geração, este projetor é a combinação ideal de desempenho e conveniência. Alta Qualidade de Imagem: Resolução Nativa: 1280*720p, suporta conteúdo 4K, proporcionando imagens claras e nítidas. Brilho: 10000 lúmens e contraste de 10000:1, garantindo imagens vibrantes e ricas em detalhes. Áudio Imersivo: Alto-falantes Estéreo Integrados: Desfrute de uma qualidade de som estéreo sem a necessidade de alto-falantes externos. Bluetooth 5.0: Conecte fones de ouvido, alto-falantes e outros dispositivos de áudio sem fio. Flexibilidade e Conveniência: Projeção de 40-150 polegadas: Ideal para uma variedade de configurações, desde salas de estar a espaços ao ar livre. Correção Automática de Keystone: Ajuste automático da imagem para projeção perfeita. Conectividade Avançada: Wi-Fi 6: Acesso mais rápido e estável à internet para streaming e jogos sem interrupções. Espelhamento de Tela: Suporte a Miracast e Airplay para compartilhar conteúdo do seu dispositivo diretamente no projetor. Sistema Operacional Android 11: Navegue e baixe aplicativos diretamente no projetor, transformando-o em uma Smart TV. Conteúdo da Embalagem: 1x Projetor Full HD Idali Life HY320 1x Controle Remoto 1x Cabo de Alimentação 1x Manual do Usuário', 500.0, 289.99, NULL, 'Home Appliances > Projectors & Accessories > Projectors & Projector Screens', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ahr0owqdkp8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175743084%2F22598460265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209229846', 'Chuveiro Elétrico Lorenzetti Top Jet Turbo 4 Temperaturas Branco', 'O Chuveiro Elétrico Lorenzetti Top Jet Turbo 4 Temperaturas é ideal para quem busca conforto, eficiência e maior pressão de água no banho. Equipado com sistema Turbo, auxilia no aumento da pressão, proporcionando um banho mais forte e uniforme, sendo indicado para locais com baixa pressão hidráulica. Conta com 4 temperaturas, permitindo escolher o nível ideal conforme a necessidade, oferecendo maior conforto em diferentes estações do ano. Seu sistema de aquecimento é eficiente, garantindo água quente de forma rápida e estável. Disponível nas versões 127V 5500W e 220V 7500W, permite ao cliente escolher a opção mais adequada conforme a rede elétrica e a necessidade de aquecimento. Modelos com maior potência proporcionam aquecimento mais intenso. Fabricado com a qualidade Lorenzetti, apresenta boa durabilidade e fácil instalação. Seu acabamento na cor branca combina com diferentes estilos de banheiro. CARACTERISTICAS Marca LorenzettiLinha Top Jet TurboTipo Chuveiro elétricoTemperaturas 4 níveisSistema Turbo com pressurizaçãoCor BrancoUso Residencial BENEFICIOS Maior pressão de águaAquecimento rápidoControle de temperaturaMais conforto no banhoIdeal para baixa pressãoProduto resistenteFácil instalação ESPECIFICACOES TECNICAS Marca LorenzettiLinha Top Jet TurboTipo Chuveiro elétrico Versão 127VPotência 5500WEAN 7896451859433 Versão 220VPotência 7500WEAN 7896451859471', 499.9, 389.9, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/sg-11134201-820n2-mnaayhdemy2oa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F58209229846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398129223', 'KIT 02 PNEUS 175/55R16 EV LINGLONG E80H GREENMAX EP 100 BYD DOLPHIN MINI ARO 16', 'Pneu de Alta Qualidade para Carros – Durabilidade, Segurança e Desempenho Descrição do Produto: Adquira pneus novos com excelente custo-benefício. Ideal para quem busca segurança, desempenho e conforto na direção. Produzido com materiais de alta qualidade, este pneu oferece ótima aderência em pistas secas e molhadas, além de garantir menor desgaste e maior durabilidade. Benefícios: Alta durabilidade e resistência Excelente desempenho em diferentes condições climáticas Conforto e estabilidade na direção Design moderno com ótima aderência Produto novo, com garantia do fabricante Observações: Consulte a compatibilidade com seu veículo antes da compra. Produto com envio rápido e seguro.', 1599.0, 1007.37, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7reoc-m8xqmo2pcnfr8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F381964247%2F21398129223', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207521937', 'Tênis Olympikus Soma 2 Masculino Original com Nota Fiscal e Garantia', '👟 Tênis Olympikus Soma 2 Masculino – Leveza, Amortecimento e Performance O Tênis Olympikus Soma 2 Masculino é ideal para quem busca conforto, leveza e desempenho em treinos ou no dia a dia. Com tecnologias modernas, ele oferece uma experiência de uso mais estável, flexível e responsiva a cada passada. 🏃‍♂️🔥 🛍 Produto 100% original Olympikus 📦 Vendido com garantia pela B2 Online ☁️ Amortecimento com Tecnologia ELEVA+ O grande destaque do modelo está na entressola com ELEVA+: ✔ Alta absorção de impacto ✔ Maior retorno de energia ✔ Passadas mais leves e eficientes 🧦 Ajuste Perfeito com HYPERSOX O cabedal conta com tecnologia que se adapta ao pé: ✔ Sensação de meia (fit anatômico) ✔ Mais conforto e flexibilidade ✔ Facilidade ao calçar 🛡️ Estrutura e Durabilidade Detalhes que garantem mais resistência e estilo: ✔ Aplicações em High Frequency ✔ Estrutura reforçada ✔ Visual moderno e esportivo 👟 Conforto Interno Pensado para uso prolongado: ✔ Forro com espuma macia ✔ Toque confortável ✔ Ajuste firme com atacador texturizado 🎯 Versátil para Sua Rotina Perfeito para diferentes momentos: 🏃‍♂️ Treinos 🚶 Caminhadas 🏋️ Atividades leves 😎 Uso casual 📋 Informações do Produto • Gênero: Masculino • Tecnologias: ELEVA+, HYPERSOX, High Frequency e EVA • Solado: Alta resiliência com ELEVA+ • Material: Têxtil com aplicações estruturais • Produto Nacional 📸 Sobre as fotos do anúncio: As imagens representam fielmente o produto. Pode haver leve variação de cor devido à iluminação ou tela. ✅ Produto original Olympikus 🚚 Envio rápido e seguro 🔥 Ideal para quem busca tênis leve, confortável e com ótimo amortecimento', 340.92, 249.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lq-mpcnnw