INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24461803938', 'Dr.Jart SleepAir máscara de reparo intensiva intensiva, 75ml', 'A máscara noturna que suaviza instantaneamente, reduz A vermelhidão visível e uma máscara noturna que suaviza instantaneamente, reduz A vermelhidão visível e repara A barreira da pele. Enquanto você dorme, hidrata a pele e aumenta o reparo da barreira para uma pele mais resistente que está pronta para enfrentar o dia. A máscara noturna deixa a pele brilhante com hidratação pela manhã. Dermatologista testada. Adequado para peles sensíveis. Clinicamente mostrado a: Aumente o reparo noturno da pele Reduza instantaneamente a vermelhidão visível* Melhore o brilho natural de aparência saudável da pele ao longo do tempo* Testes clínicos em 32 mulheres, após o uso do produto por 28 dias. O que o torna exclusivo: Esta máscara noturna de gel leve começa a se preparar a pele para a cama alisando a pele e acalmando-a com Cica Complex (extratos de Centella Asiatica). Noite, alantoína ajuda a construir a resiliência da pele para amanhã. Com o tempo, esta máscara noturna aumenta o brilho natural e saudável da pele. O que está nele: Cica Complex (Extratos de Cica Asiatica) e R-Protetor acalmam instantaneamente a pele para reduzir a vermelhidão visível. A alantoína repara a barreira da pele para uma pele mais resistente e saudável para uma pele com aparência mais resistente e saudável. Livre de: Parabenos, Formaldeídos, Ftalatos, Óleo Mineral, Sulfatos, Triclocarban, Triclosan, Sem Glúten.', 176.8, 168.0, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134207-7rd3x-lwgt3ygz41jef5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24461803938', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598890181', 'Kit Protetor de Molas 1,83m + Rede de Proteção 1,83m + 6 Isotubos Médios + 6 Ponteiras Coloridas', 'O KIT INCLUI: 1 Rede de Proteção para Cama Elástica Redonda 1,83m 1 Proteção de Molas para Cama Elástica Redonda 1,83m 6 Isotubos Médios de 1,10m 6 Ponteiras Coloridas para Haste Proteção de molas para Cama Elástica (1,83M) Imagine um protetor de molas colorido e divertido para cama elástica, feito de material resistente e adornado com bagunzitos. Projetado para segurança, proporciona uma experiência segura e visualmente estimulante em parques, áreas recreativas ou em casa, transformando qualquer espaço em um playground encantador. Atenção: antes de realizar a compra, favor medir o diâmetro total da cama elástica (de ponta a ponta da ferragem, não apenas onde a proteção de molas vai cobrir). Assim saberá a medida correta para comprar. Outra observação; a proteção de molas é feita apenas para garantir a segurança, não recomendamos que a criança pule no produto, pois pode interferir na durabilidade.', 263.15, 228.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98p-ll3ia5dlrlsm61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438656550%2F20598890181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
