INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598923633', 'Churrasqueira Elétrica Rotativa 5 espetos Arke Vitta Smart-05, Preta', 'Churrasqueira Elétrica Rotativa Arke Vitta Smart-05, 5 espetos Características Marca: Arke Modelo: Vitta Smart-05 Aplicação: Doméstica Cor: Preta Especificações Espetos: 5 espetos - 4 simples e um triplo; Capacidade por espeto: 1,5 Kg; Giro dos espetos: 5,5 rpm; Nº de queimadores: 2 dois; Material: Aço carbono; Acabamento: Pintura Epóxi; Vidro curvo: assa frangos inteiros e permite melhor circulação do ar. Sistema de rotação dos espetos; Porta de vidro transparente: melhor visualização e acompanhamento do preparo do alimento. Pés antiderrapantes; Ecologicamente correto: não produz fumaça; Bandeja coletora de gordura; Tempo para assar*: Salsichão - 50 minutos; Carne de gado - 1 hora; Carne suína - 1h30 min; Carne de frango em pedaços - 1h30 min; Carne de frango inteira - 2h Alimentação Potência: 2x1.250W Consumo aproximado de energia: 2,53 kW/h Itens Inclusos 01 Churrasqueira Arke Elétrica 05 Espetos 01 Bandeja coletora de gordura 04 Pés de apoio de borracha Manual de instrução Dimensões Tamanho interno (AxLxP): 61,9 x 42 x 25 cm Tamanho externo (AxLxP): 67 x 55,1 x 34 cm Medidas do espetos: 55 cm de lâmina + 12 cm de cabo Distância entre os espetos: 11,3 cm Peso: 24 Kg Garantia: 6 meses Atenção! *Estes tempos podem variar conforme a espessura da carne ou regulagem dos queimadores. * NÃO FATURAMOS PARA CNPJ', 1290.9, 1290.9, NULL, 'Home & Living > Kitchenware > Grills & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-820n6-mo48hx2xm134bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1541325700%2F22598923633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299847786', 'Piscina Estruturada 1500 Litros Azul Quadrada Mor Infantil', 'A Diversão que Cabe em Qualquer Lugar: Piscina Infantil Mor 1500 Litros! Prepare-se para refrescar os pequenos com a Piscina Infantil Quadrada Mor de 1.500 litros! Com um design moderno e estampa em ondas, essa piscina é perfeita para garantir a alegria da garotada nos dias de sol, seja em pequenos espaços ou para levar para onde a diversão estiver. Fabricada com material resistente em PVC e uma estrutura robusta toda em aço, a montagem é simples e o armazenamento é super fácil. A lona, com maior espessura, oferece mais resistência, e o sistema de solda dos pés garante maior estabilidade ao produto. Além de ser prática, a piscina conta com válvula para deságue, facilitando a limpeza e manutenção. A Mor assegura um rigoroso controle de qualidade, entregando um produto excelente para o lazer de toda a família. Principais Características: Capacidade: 1.500 litros Formato: Quadrada Material: PVC resistente e estrutura em aço Design: Lona colorida com estampa em ondas Durabilidade: Lona de maior espessura e sistema de solda dos pés reforçado Praticidade: Fácil de montar, guardar e com válvula para deságue Dimensões (AxLxP): 42,0 cm x 1,89 m x 1,89 m Peso: 7,20 kg', 314.9, 254.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mc7xsqjw040re1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F19299847786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257249120', 'Jogo De Panelas Tramontina Turim 12 Peças Antiaderente com Utensílios de cozinha', 'Jogo de Panelas Tramontina Turim em Alumínio com Revestimento Interno e Externo em Antiaderente Starflon Max Vermelho 07 Peças Se você busca deseja uma cozinha completa e preparada para o preparo das suas refeições, conte com o jogo de panelas Tramontina Turim em alumínio com revestimento interno e externo em antiaderente Starflon Max vermelho 07 peças. Com ele, você tem os itens essenciais para garantir um arroz soltinho, um refogado de legumes ou um bife grelhado suculento de maneira rápida e uniforme, sem grudar na superfície, pois a produção de suas peças é em alumínio com revestimento Starflon Max. Os cabos, alças e pegadores são em materiais antitérmicos, não aquecem e proporcionam maior segurança no manuseio. Além de todas essas características, o jogo pode ir à máquina de lavar louças e tem panelas e caçarolas com tampas de vidro temperado com bordas de aço inox! Dimensões 733x435x131 mm Peso 3.05 kg Corpo de alumínio com espessura que proporciona cozimento rápido e uniforme. Revestimento interno e externo de antiaderente Starflon Max que não gruda, é fácil de limpar, mais durável e não é prejudicial à saúde, pois é livre de PFOA. Tampas de vidro temperado com bordas de aço inox. Cabos, alças de baquelite antitérmico e pegadores de nylon que oferecem segurança durante o manuseio. Podem ir à máquina de lavar louças facilitando seu dia a dia. A capacidade volumétrica máxima para cozimento é de 3/4 da capacidade total da peça. Posicione os cabos dos utensílios voltados ao centro do fogão. Em fogões com grade, centralize as peças sobre a chama ou fonte de calor e alinhe os cabos com a grade. Utensílios quentes devem estar fora do alcance das crianças. Para descarte dos produtos e embalagem siga as orientações de reciclagem vigentes. Composição - 01 Caçarola Ø 18 cm 2 L Turim - 01 Caçarola Ø 20 cm 2,8 L Turim - 01 Fervedor Ø 12 cm 1,0 L Turim - 01 Frigideira Ø 16 cm 0,4 L Turim - 01 Frigideira Ø 20 cm 0,8 L Turim - 01 Panela Ø 16 cm 1,4 L Turim - 01 Panela Ø 18 cm 2,0 L Turim Kit c/5 talheres em nylon para servir Lindo conjunto de utensílios em Nylon antiaderente, super resistente, suporta até 190ºC Contém: 1 Pegador de Massas 1 Concha 1 Espátula 1 Colher 1 Escumadeira Medidas Aprox. Comprimento 29cm Os Utensílios não são da marca Tramontina', 402.3, 342.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/br-11134207-820lu-mm0u5hqzbabo4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826682830%2F58257249120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
