INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598788845', 'Sapato Feminino Modare Anabela Bege', 'O Sapato Feminino Modare apresenta um visual supermoderno e despojado, perfeito para compor uniformes de trabalho e looks casuais. Confeccionado em napa, oferecendo o máximo de conforto para os seus pés! A palmilha macia em espuma evita qualquer tipo de desconforto ou incomodo para o seu dia a dia. O solado emborrachado, antiderrapante, com salto de 3 cm, permite que você tenha passadas mais firmes e estáveis. O detalhe matelassê na lateral é puro charme e elegância!', 129.89, 129.89, NULL, 'Women Shoes > Flats > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257t-mq7ou60bedqk6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F22598788845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098776490', 'Top Feminino Fila Nadador Essential Sustentação Preto', 'Renove seu visual esportivo com o Top Feminino Fila Nadador Essential Sustentação Preto, perfeito para acompanhar seus treinos com conforto e segurança. Confeccionado em malha leve de poliamida com elastano, oferece toque suave e alta elasticidade, proporcionando liberdade total de movimentos. O forro frontal garante maior conforto, enquanto a barra elástica firme assegura boa sustentação durante o uso. Com modelagem justa ao corpo e costas estilo nadador, o Top Feminino Fila é ideal para práticas esportivas, unindo desempenho e proteção. O tecido ainda conta com tecnologia UV50+, que oferece proteção solar, além de secagem rápida e estabilização térmica. Funcional, leve e resistente, o Top Feminino Fila Nadador é a escolha certa para quem busca uma peça versátil e eficiente na rotina de atividades físicas. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Top Feminino Fila Nadador Essential Sustentação Preto Indicado: Dia a dia; Esportiva Composição: 86% Poliamida, 14% Elastano Modelagem: Justa ao corpo Costas: Estilo nadador Barra: Elástica Diferencial: Elástico firme, auxilia na sustentação Tamanho: P Peso: 100g', 109.89, 99.89, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/sg-11134201-820m9-mnd0tkiyncao69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F22098776490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
