INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594430719', 'Tênis Infantil Novopé Calce Fácil Preto', 'O Tênis Infantil Novopé Calce Fácil Preto une praticidade e conforto para acompanhar o dia a dia das crianças. Com design moderno e versátil, é ideal para escola, passeios e viagens. Seu cabedal em têxtil e sintético garante respirabilidade e ajuste leve, enquanto o solado em borracha flexível acompanha o movimento natural dos pés, proporcionando segurança e firmeza em cada passo. O calce fácil torna o modelo ainda mais prático, facilitando a rotina das crianças. A palmilha em EVA completa o conforto com leve amortecimento, garantindo bem-estar para uso prolongado. Combinando estilo e funcionalidade, o Tênis Infantil Novopé é a escolha certa para quem busca versatilidade e comodidade em um só calçado. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Tênis Infantil Novopé Calce Fácil Preto Indicado: Dia a dia Tipo de Tênis: Casual Material: Têxtil e sintético Palmilha: EVA Solado: Borracha Fechamento: Sem fechamento Diferencial: Respirabilidade e solado que acompanha o movimento natural dos pés Peso do produto: 400g Produto Original: Autenticidade garantida pelas Lojas Radan Dimensões aproximadas: Tamanho 17: 11 cm Tamanho 18: 12 cm Tamanho 19: 12,5 cm Tamanho 20: 13 cm Tamanho 21: 14 cm Tamanho 22: 14,5 cm Tamanho 23: 15 cm Tamanho 24: 16 cm Tamanho 25: 16,5 cm Tamanho 26: 17 cm Tamanho 27: 18 cm Tamanho 28: 18,5 cm Tamanho 29: 19 cm Tamanho 30: 20 cm Tamanho 31: 20,5 cm Tamanho 32: 21 cm Tamanho 33: 22 cm Tamanho 34: 22,5 cm Tamanho 35: 23 cm Tamanho 36: 24 cm', 129.89, 119.89, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zwg-mmup2gu51lheba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F22594430719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41669239872', 'Queijeira Plástica Redonda com Prato e Tampa Decorada Translúcida e Base Preta – Protege e Conserva', 'Queijeira com Tampa Uninjet – Praticidade e Higiene para sua Mesa A Queijeira Uninjet com Tampa é ideal para armazenar, proteger e servir queijos de forma prática e higiênica. Produzida em plástico resistente, atóxico e livre de BPA, garante segurança no contato com alimentos e preserva o sabor e a qualidade por muito mais tempo. Com tampa protetora transparente, mantém o queijo livre de poeira, insetos e odores externos, além de permitir visualizar o conteúdo com facilidade. Seu design compacto é perfeito para uso diário e também para compor a mesa em momentos especiais. Especificações: Marca: Uninjet Dimensões: 18 x 16,5 x 10 cm Material: Plástico resistente, atóxico e livre de BPA Tampa: Transparente, prática e higiênica Diferenciais: Produto seguro e livre de BPA Protege e conserva o queijo por mais tempo Compacta, prática e fácil de limpar Tampa transparente que facilita a visualização Ideal para uso diário e ocasiões especiais Leve mais praticidade e organização para sua mesa com a Queijeira com Tampa Uninjet, a escolha certa para manter seus queijos sempre frescos e bem conservados.', 19.9, 19.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-824jh-mepz6rhuqt4w10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F506112052%2F41669239872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
