INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892500609', 'Kit Shampoo + Condicionador Salon Line Hidra Babosa 300ml', 'O Shampoo e o Condicionador da linha Hidra Babosa trazem hidratação e reconstrução ao mesmo tempo, deixando seus cabelos mais saudáveis e hidratados. Indicados para fios danificados e quebradiços, esses produtinhos contém em sua composição ingredientes pensados justamente na reconstrução capilar. São eles:Babosa, que é rica em vitaminas A, C, E, B1, B3, B6, B12, B13, minerais e aminoácido que garantem fios mais fortes, macios, hidratados e saudáveis Queratina que, restaura e hidrata os fios, além de auxiliar no tratamento dos cabelos danificados. E Glicerina Vegetal que, tem alto poder de hidratação, auxilia no fortalecimento dos fios e combate as pontas duplas. A linha Hidra Babosa é uma das favoritas da internet e também é uma das mais amadas pela nossa embaixadora Amanda Mendes. Para ela, o Shampoo e o Condicionador Hidra Babosa formam uma dupla poderosa que dá um up nas madeixas ressecadas e quebradiças. Para recuperar e dá vida aos seus fios, clique em comprar! Modo de uso: Aplique o shampoo no cabelo úmido, massageie bem e enxágue. Repita o processo se achar necessário. Em seguida, passe o condicionador uniformemente no cabelo úmido e espalhe por toda a extensão dos fios. Enxágue abundantemente.', 26.13, 26.13, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbnk-lmhignxy8hmh4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22892500609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
