INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397438085', 'Gel Esfoliante Ácido Salicílico Enzimático 100ml Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - DESCRIÇÃO: O Gel Esfoliante Ácido Salicílico Enzimático 100ml Dermachem, proporciona renovação, remoção das impurezas e redução da oleosidade, promovendo uma esfoliação enzimática sem agredir a pele. Para melhores resultados, utilize a linha completa ÁCIDO SALICÍLICO DERMACHEM LABORATORY. - - - - - MODO DE USO: Utilize de 1 a 2 vezes por semana ou quando sentir necessidade. Aplique no rosto previamente umedecido em movimentos circulares. Aguarde 5 minutos e depois enxágue com água em abundância. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 18.8, 12.9, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/br-11134207-820md-mopuwju0rjlxd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F23397438085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
