INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293558831', 'Máscara de Tratamento Seda Luminous UV 300g', '• Máscara de Tratamento SEDA Luminous UV com Glycol + Vita C Complex repara intensamente até 1 ano de sinais de danos UV* • 6% Glycol + Vita C Complex sela as cutículas, repara os sinais de danos causados pelos raios UV, deixa o cabelo com a aparência mais saudável e ativa a luminosidade • Máscara de Tratamento para cabelos protegidos e com um brilho excepcional, mesmo sob o sol brilhante • Com fórmula exclusiva, facilita o desembaraço dos fios e repara os sinais de danos causados pelos raios UV • Use a linha completa Seda Luminous UV para cabelos com brilho e iluminados por mais tempo, um regime completo para todos os tipos de cabelo • Além de oferecer reparação e proteção dos sinais de danos UV nos cabelos, a linha conta com uma fragrância envolvente e revigorante de frutas cítricas, criando uma fragrância luminosa e cintilante Nova máscara de tratamento Seda Luminous UV com 6% Glycol + Vita C Complex com textura ultra cremosa. Repara até 1 ano de sinais de danos UV para um cabelo iluminado*. Brilhe com a nova Máscara de Tratamento Condicionante Seda Luminous UV! Nossa fórmula exclusiva com Glycol + Vita C Complex repara intensamente até 1 ano de sinais de danos UV*, para cabelos protegidos e com um brilho excepcional, mesmo sob o sol brilhante! O complexo de 6% Glycol + Vita C sela as cutículas, repara os sinais de danos causados pelos raios UV, deixa o cabelo com a aparência mais saudável e ativa a luminosidade. Modo de uso: com os fios umidos, aplique sobre todo o cabelo até as pontas (evite a raiz!), passando mecha a mecha de cima para baixo. Deixe por 1 minuto e depois enxágue. Use a linha completa Seda Luminous UV para cabelos com brilho e iluminados por mais tempo, um regime completo para todos os tipos de cabelo. Além de oferecer reparação e proteção dos sinais de danos UV, a linha conta com uma fragrância envolvente, uma explosão revigorante de frutas cítricas, criando uma fragrância luminosa e cintilante. *Dano à suavidade e resistencia à quebra comparado com shampoo sem agentes condicionantes.', 28.99, 23.62, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rffg-m341fh1bszx60b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23293558831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
