INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9680905280', 'Perfume Deo Colonia Feminino Donna 100ml Fiorucci', 'Fiorucci Donna Feminino New Editon e um perfume de fragrancia unica com notas de saida frescas e levemente frutais combinadas ao rico bouquet floral e sustentadas por um fundo quente balsamico. A Fiorucci se preocupa com a sua pele e desenvolve produtos de qualidade que vao beneficiar seu corpo, como o Colonia Fiorucci Donna Feminino New Editon, feito para a mulher de atitude que merece uma fragrancia duradoura e de qualidade. Fiorucci Donna e um perfume de fragrancia unica com notas de cabeca frescas e levemente frutais de Tangerina, Neroli e Flor de Laranjeira, combinadas ao rico buque Floral Oriental com balsamico de Jasmim e Lirio do Vale, sustentadas por um fundo quente de Sandalo, Baunilha e Ambar. A Marca: Greenwood iniciou suas atividades em 1967, criando produtos de perfumaria e cosmeticos, desde colonias, eau de toilette, desodorantes, sabonetes liquidos, hidratante, crenes, geis, espumas de barbear, entre outros da mais alta qualidade. Em 1981 um contrato firmado com a Nivea Alema nos permitiu a fabricacao de toda a linha Nivea no Brasil, ate a conclusao da construcao da fabrica propria 20 anos depois. Com isso, nos consolidamos entre os maiores terceirizados de cosmeticos do Brasil desenvolvendo Fiorucci com toda credibilidade, experiencia e com muita seguranca. Genero: Feminino Concentracao: Eau de Cologne - EDC Familia Olfativa: Floral, Oriental Notas de Topo: Tangerina, Neroli, Flor de Laranjeira Notas de Coracao: Jasmim, Lirio do Vale Notas de Fundo: Sandalo, Baunilha, Ambar Intensidade: Moderada Tempo de Fixacao: Longo', 66.12, 59.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lt5ef7ux2lzd3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F9680905280', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
