INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698564969', 'Arame Eletro BWG 15 1,83 mm 500 Metros Vonder', 'Arame Eletro BWG 15 1,83 mm 500 Metros VonderO Arame Eletro BWG 15 Vonder com 1,83 mm de diâmetro e 500 metros de comprimento é ideal para instalações de cercas elétricas, oferecendo resistência, durabilidade e excelente condutividade elétrica. Com acabamento galvanizado e camada de zinco de 190 g/m², esse arame garante maior proteção contra corrosão, mesmo em ambientes externos e agressivos, prolongando sua vida útil. Com resistência à tração de 250 kgf e resistência elétrica de apenas 0,0565 Ω/m, esse modelo é altamente eficiente na transmissão de corrente elétrica, contribuindo para uma cerca mais segura e funcional. Sua aplicação é indicada para propriedades rurais, chácaras e locais que exigem sistemas de contenção elétrica eficazes. Especificações Técnicas:Acabamento: Galvanizado Camada de Zinco: 190 g/m² Diâmetro nominal: 1,83 mm Resistência à tração: 250 kgf Resistência elétrica: 0,0565 Ω/m Comprimento: 500 metros Peso aproximado: 10,3 kg Categoria: Arame para cerca elétrica Marca: Vonder Código do fornecedor: 7491015050 Garantia:Garantia legal de 90 dias contra defeitos de fabricação. Itens Inclusos:1 Rolo de arame galvanizado com 500 metros Esse arame oferece desempenho confiável para aplicações onde a eficiência da condução elétrica e a resistência à corrosão são indispensáveis.', 291.9, 291.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ratg-maih7wl3utti2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F22698564969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
