INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250131173', 'Colchão Casal de Espuma Gazin Itapema ISO D28 138x188', 'Colchão Casal de Espuma Gazin Itapema ISO D28 138x188 O Colchão Casal de Espuma Gazin Itapema ISO D28 138x188 proporciona noites de sono mais agradáveis para você. Feito com Espuma D28+EPS, o produto conta com revestimento superior em Tecido plano, que é fácil de limpar e higienizar. Já o revestimento inferior é feito em Tecido antiderrapante 100 Poliéster, perfeito para o seu colchão não deslizar da base durante seu sono. O colchão tem a capacidade de suportar 90 kg, o que traz mais segurança na hora de dormir. Viva noites de sono mais tranquilas com o Colchão de Espuma Gazin Itapema. Não perca essa oportunidade e garanta já o seu! Características: Marca: Colchoes Gazin Modelo: Itapema Modelo de colchão: Casal Tipo de colchão: Espuma D28 + EPS Densidade da espuma: D28 Revestimento Superior: Tecido Plano Revestimento Inferior: Tecido antiderrapante 100 Poliéster Conteúdo da Embalagem: 01 Colchão Casal Dimensões: Altura: 17,00 cm Largura: 138,00 cm Profundidade: 188,00 cm Peso: 14,00 kg Peso suportado por pessoa: 90 kg Garantia do Fornecedor: 03 meses contra defeito de fabricação.', 617.86, 617.86, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mgf2qxi6e9zdd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F58250131173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
