INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197682943', 'Tintura Creme Koleston 40 Castanho Medio', 'Koleston Creme é a coloração permanente da Wella que te dá cor intensa e duradoura, graças a sua tecnologia resistente à água. Oferece perfeita cobertura dos fios brancos, além de hidratar tão intensamente quanto colore. Seu exclusivo Tratamento Gloss Intenso Ultra deixa seu cabelo com mais brilho e maciez e ajuda a manter a intensidade da cor. O kit Koleston também vem com o Reativador de cor que deposita mais pigmentos no seu cabelo para ajudar a reativar a cor depois de 15 dias. É Uma coloração fácil de aplicar em casa, até mesmo para aquelas que não possuem muita habilidade na hora de colorir os fios sozinha. O kit Koleston contém: • 1 bisnaga Wella Koleston Coloração Creme 55 g • 1 frasco aplicador Wella Koleston Emulsão Reveladora/Água Oxigenada 30 vol. 55 ml • 1 sachê Wella Koleston Reativador de Cor Tratamento com pigmentos 22 ml • 1 tubo Wella Koleston Tratamento Gloss Intenso Ultra que contém 4 aplicações 40 ml • 2 pares de luvas • 1 folheto explicativo Benefícios: -Cor intensa e duradoura - Cobertura perfeita dos fios brancos - Fácil de aplicar- Promove hidratação e nutrição - Garante brilho, maciez e um toque suave - Cria camada de proteção que impede que a água penetre no fio, para que não desbote.', 33.49, 33.49, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lvdlpcq2v15m63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21197682943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
