INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393652906', 'Kit Loção Hidratante Francis Cereja 400ml - 6 Unidades', 'A Loção Hidratante Francis Cereja 400ml oferece 72 horas de hidratação, deixando a pele macia e nutrida por mais tempo. Sua fórmula é enriquecida com Manteiga de Karité e Biopeptídeos de Arroz, que agem profundamente para nutrir a pele de dentro para fora. A loção tem rápida absorção, garantindo uma pele suave, com toque aveludado e um brilho natural. Além de hidratar,ela perfuma a pele com a deliciosa fragrância de cereja, proporcionando uma sensação agradável e revigorante. Ideal para quem busca praticidade e um cuidado eficiente no dia a dia. Benefícios: - Hidratação intensa por 72 horas; - Nutrição profunda com Manteiga de Karité e Biopeptídeos de Arroz; - Rápida absorção, sem sensação oleosa; - Pele macia, aveludada e com brilho natural; - Fragrância deliciosa de cereja. Modo de usar: Aplique a loção diariamente na pele limpa e seca, massageando até que o produto seja completamente absorvido. Contém no kit: - Loção Hidratante Francis Cereja 400ml - 6 Unidades Sobre a marca: Francis é uma marca brasileira de produtos para a pele, que tem como missão elevar a vida dos brasileiros através da perfumação. Como quem sempre busca transmitir sofisticação, naturalidade e jovialidade, Francis, pioneira na fabricação de sabonetes com alto poder de perfumação no país, utiliza seu potencial de construção das melhores fragrâncias para inspirar todos ao seu redor.', 178.12, 131.94, NULL, 'Beauty > Bath & Body Care > Body Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-824gc-mpl6ulszpnv208', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22393652906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22102156150', 'Escova Dental Oral B Pro Saúde 7 Benefícios Com 2 Unidades', 'A Escova Oral B Pro Saúde foi criada para proporcionar 7 benefícios para um cuidado maior garantindo uma limpeza eficaz para uma boca mais saudável, ajuda a remover a placa nos locais de difícil alcance, limpa ao longo da linha da gengiva, assim mantem ela forte e saudável, remover as manchas superficiais dos dentes e remover germes da língua e bochechas, é delicada com o esmalte dos dentes e as gengivas. Sobre a marca: A Oral- B foi fundada em 1950 pelo Dr. Robert Hudson em 1950. Seus produtos são fabricados no mais alto padrão de qualidade e devido a isso transformou-se em símbolo de respeito e organização. A marca atualmente desenvolve produtos inovadores com diferentes formulações para atender ao mais diversos públicos. Os produtos da Oral-B são recomendados por dentistas do mundo inteiro. * O Produto Pode ser enviado em Cores diversas.', 43.19, 43.19, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-820n6-mo09a5np83cz23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22102156150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
