INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799557859', 'Kit Pano De Boca Estampado Papi Bordados Amigas - 03 Peças', 'Kit Pano De Boca Estampado Papi Bordados Amigas - 03 Peças O kit de pano de boca Papi da linha Bordados Karinho é composto por 03 paninhos confeccionados em tecido 100% algodão estampados com bordado e acabamento de picueta. As fraldinhas, toalhinhas e paninho de boca são macias e ideais para secar a "babinha" dos bebês ou limpar sua boquinha durante as refeições. Informações Adicionais:Tamanho: Único Cor: Rosa Referência: 1547-1772 Merdida Aproximada: 32cm x 32cm Marca: Papi', 19.9, 19.9, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/br-11134201-820mf-mqxjcakj6hae98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F20799557859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
