INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11097896756', 'Ativador de Cachos Desembaraçante Toin 500ml', 'Para quando seus cachos precisam de um UP! QUER DESCOBRIR O SEGREDO DE CACHOS QUE VIRALIZAM?! Com sua fórmula arrasadora, o ativador de cachos Toin promete (E cumpre!) dar aquele UP no visual no day after. Além de promover uma suuuper definição dos fios, o trio Pantenol, Quinoa e Óleo de coco é tudo o que você procura nos quesitos umectação, reparação e nutrição. Indicado para adolescentes a partir dos 12 anos. AÇÃO Ação condicionante. ATIVOS Panthenol, Proteína de Quinoa e Óleo de Coco BENEFÍCIOS Produto vegano Não testado em animais Fórmula liberada RESULTADO Super definição! MODO DE USO Ideal para o day after, pode ser usado para modelar e preservar os cachos diariamente, até a próxima lavagem. Aplique com os cabelos úmidos, em toda a extensão dos fios, modelando os cachos com as pontas dos dedos. Não enxágue.', 35.0, 32.99, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/948977c1a4a8e7bdaf48cc2f07ee05cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F11097896756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
