INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15391612891', 'Kit Relacao Tração Transmissão Honda Cb 300 Cb300 2009 2010 2011 2012 2013 2015 Com Retentor Original Kmc', 'KIT RELACAO COMPLETO CB 300 CB300R (COROA/PINHAO E CORRENTE COM RETENTOR) - OFERTA LANCAMENTO!!! NOVO NA CAIXA - ORIGINAL KMC PRINCIPAIS APLICACOES: MOTOS: HONDA CB 300 / CB300R ANO: 2009 A 2015, *Aco 1045 *Corrente 520HX110L (COM RETENTOR) *37 dentes da coroa *13 dentes do pinhao Funcao da Coroa e do Pinhao: A Coroa e o Pinhao juntamente com a corrente sao conhecidos como kit relacao, e sao fundamentais para uma pilotagem segura, sendo responsaveis por transmitir o movimento da saida da transmissao ate a roda traseira. Como detectar problemas? Verifique se ha desgastes nos dentes da coroa e do pinhao. Ao trocar verifique tambem: o ideal e realizar a troca do kit inteiro (coroa, pinhao e corrente) para garantir a durabilidade do conjunto, ruidos e folga na transmissao de forca. Diferenciais: Produzida em aco 1045 Endurecimento termico para aumentar a resistencia e durabilidade Numero de dentes conforme padrao original Dentes tratados termicamente ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 329.9, 278.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/f9da760352cc2775cf773aa73ad3e99a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F840389310%2F15391612891', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394701135', 'Máquina de Gelo MGP12 Praxis - Preta 12 kg', 'Máquina de Gelo MGP12 Praxis – Gelo Fresquinho Sempre Que Você Precisar! Com a Máquina de Gelo MGP12 da Praxis, você nunca mais precisará se preocupar em comprar sacos de gelo ou ocupar espaço no freezer. Compacta, eficiente e com um design moderno, ela é ideal para quem busca praticidade e sofisticação no dia a dia. Principais Diferenciais: Alta Produção: Produz até 12 kg de gelo por dia, perfeita para reuniões, eventos ou uso diário. Velocidade: Gera 9 cubos de gelo em apenas 8 minutos, garantindo praticidade. Versatilidade: Escolha entre 2 tamanhos de cubos, ideais para diferentes bebidas e receitas. Design Moderno: Disponível na cor preta, combina com qualquer ambiente. Compacta e Funcional: Medindo apenas 28,3 cm x 21,4 cm x 29,9 cm (A x L x P), se adapta a cozinhas, áreas gourmet ou escritórios. Operação Simples: Teclado touch intuitivo e prático. Autonomia: Tanque com capacidade de 1,4 litros, evitando reabastecimentos frequentes. Versões de Voltagem: Disponível em 110V e 220V. Com a MGP12, suas bebidas favoritas, como sucos, drinks e até cafés gelados, estarão sempre no ponto. Compacta e funcional, é perfeita para agregar conforto e eficiência ao seu dia. Dados Técnicos: Modelo: MGP12PT Produção de Gelo: Até 12 kg/dia Capacidade de Água: 1,4 litros Tempo de Produção: 9 cubos em 8 minutos Tamanhos de Cubos: 2 opções Dimensões: 28,3 cm x 21,4 cm x 29,9 cm Peso: 7,5 kg Cor: Preta Voltagem: 110V ou 220V Garantia: 90 dias Por que a Praxis? A Praxis Eletrodomésticos é sinônimo de inovação e qualidade, oferecendo produtos que atendem às suas necessidades com eficiência e estilo. ?? Adquira já sua Máquina de Gelo MGP12 Praxis e tenha gelo fresquinho sempre que quiser! Seja para o dia a dia ou para momentos especiais, ela transforma sua experiência com praticidade e modernidade.', 699.0, 699.0, NULL, 'Home Appliances > Kitchen Appliances > Freezers', 'https://cf.shopee.com.br/file/sg-11134201-822x7-mi4j88eyv4010a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433856120%2F23394701135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
