INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898703372', 'Aspirador de Pó e Água Kärcher WDL 1 BLACK', 'Aspirador de Pó e Água Kärcher WDL 1 BLACK 1500W 10L com Soprador O Aspirador Kärcher WDL 1 BLACK é 3 em 1: aspira pó, líquidos e ainda funciona como soprador. Potente, com 1500W, tanque de 10 litros e alcance de 7,5 metros, é ideal para limpar pisos, estofados, cantos, carros e áreas externas. Acompanha filtro lavável, bocais, mangueira e tubos prolongadores para mais praticidade. Compacto, leve, fácil de guardar e com suporte para acessórios, o WDL 1 é perfeito para o dia a dia. Principais vantagens:Aspira pó e águaFunção sopradorFiltro lavável e reutilizávelTanque de 10LAlcance de 7,5mPotência de 1500W Voltagem: 127V ou 220V', 449.4, 419.0, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mmaubc5gwmx1d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F848951954%2F22898703372', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
