INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8870761353', 'Prancheta Tática Dupla Face Futsal Kief', 'Desenvolvida para futsal, a prancheta da Kief é ideal para monta suas estratégias e instruir sua equipe com as táticas de jogo para assim, dominar as quadras. Fabricada com plástico reforçado, a peça contém dupla face, além de durabilidade. Seu design é predominantemente branco com detalhes em azul e preto. Além disso, de um lado vem com o desenho de metade da quadra e do outro lado, traz o desenho do campo inteiro, facilitando a criação das estratégias. A prancheta possui suporte para encaixe da caneta e por fim, contém caneta na cor azul e conta com velcro, que funciona como apagador. Contém: 01 Prancheta e 01 Caneta Composição: Plástico Composição Caneta: 100% Plástico Dimensão Aproximada : Alt.40cm x Larg.25cm. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 140.0, 140.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/3eb27099b9d6f4a18e29708740d7ef2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F8870761353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
