INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45309731940', 'Desinfetante Líquido Lysoform Lavanda 1L', 'Lysoform Desinfetante Líquido é um desinfetante confiável, que mata 99,9% dos germes, bactérias e fungos. A marca mais recomendada por médicos para desinfetar sua casa, para que você possa aproveitar todos os momentos sem preocupações. Informação de Segurança Leia atentamente o rótulo antes de usar o produto. Instruções Desinfecção: Aplique e deixe agir por, no mínimo, 10 minutos. Vasos sanitários: Coloque Lysoform sobre uma reborda interna e nas paredes laterais do vaso sanitário. Lixeiras e ralos: Coloque Lysoform e deixe agir. Perfumação: Aplique Lysoform diluído. Use duas colheres de sopa (25ml) por litro d’água em pisos, azulejos e superfícies laváveis. Não é preciso enxaguar. Antes de usar sobre qualquer superfície, teste em uma pequena área. Lavagem de roupas (apenas no caso das versões Original e Suave Odor): Utilize meio copo americano (90ml) de Lysoform no processo final de lavagem. Não é necessário enxaguar. Testar em uma pequena área escondida do tecido antes de usar para certificar-se de que não mancha. Lave em água corrente os objetos usados como medida antes de reutilizá-los para outros fins.', 28.32, 28.32, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/sg-11134201-822xw-mo5j3o149b0l19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F45309731940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
