INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22622771199', 'Kit 2 caixas organizadoras empilháveis de bambu e palhinha 24cm - Oikos', 'Conheça o Kit de 2 caixas organizadoras empilháveis de bambu e palhinha 24cm da OIKOS. Multiuso, versáteis, duráveis e higiênicas, são ótimas para guardar e organizar acessórios, brinquedos, perfumes, potes e o que precisar! Caem bem em diversos ambientes e são empilháveis, ajudando a otimizar espaços. São de bambu, MDF, plástico e acrílico. Para limpar, basta utilizar um pano úmido e deixar secar em local arejado. Leve qualidade e modernidade para sua casa! O kit contém: 2 caixas organizadoras empilháveis de bambu e palhinha 24cm', 274.9, 185.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-23020-bzmefg2n4anv5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F22622771199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17862848491', 'Kit Cabide de Veludo Bege com Gancho Oikos - 60 Unidades', '"Esse é o Kit de 60 cabides de veludo da OIKOS. Não escorrega: com ele, aquelas roupas que teimam em escorregar, não vão ter mais chance - ele é de veludo, meu bem. Mais espaço no armário: se é mais espaço que você quer, esse cabide é a solução, além de ser ultrafino, ele tem um gancho frontal que permite pendurar um cabide no outro - maravilhoso! Prático: com ele, colocar a roupa no cabide para o lado errado não é um problema: seu gancho é giratório! Cor: Bege Esse Kit é composto por: 20 Unidades - KIT DE 3 CABIDES TOQ DE VELUDO COM GANCHO FRONTAL Comprimento: 45cm Altura: 21cm Largura: 0,60cm"', 518.9, 353.9, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/sg-11134201-8261y-mlemc0jg2hagcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F17862848491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
