INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394211684', 'Kemei 2797 9000RPM Conjunto de máquina de cortar cabelo sem fio DLC Máquina de corte de cabelo elétrica', 'Kit Profissional de Corte e Acabamento Kemei KM-2797 – Alta Potência e Precisão com Design Moderno. O Kemei KM-2797 é o combo ideal para profissionais exigentes ou para quem busca resultados de salão em casa. Equipado com máquinas de corte e acabamento, esse kit oferece potência, autonomia e precisão em um só produto. Destaques do Produto: ⚡ Potência profissional Corte: 10W Acabamento: 8W 🔋 Bateria de longa duração: Corte: 4600mAh Acabamento: 2000mAh Até 260 minutos de uso contínuo ⏱️ Tempo de carregamento: 3 horas 📊 Display LCD com botão de ajuste de RPM: Regule entre 7000 a 9000 RPM conforme sua necessidade ✂️ Lâminas DCL e cerâmica 🎨 Cores disponíveis: Azul ou Preto 🔌 Carregamento via cabo USB Conteúdo da Embalagem: 1X Máquina de corte 1x Máquina de acabamento 1x Protetor de lâmina 10x Pentes de corte (1.5 a 24 mm) 3x Pentes de acabamento (1.5 / 3 / 4.5 mm) 1x Cabo USB para carregamento 1x Pincel de limpeza 1x Óleo para lâmina 1x Manual de instruções Ideal para barbeiros profissionais ou uso doméstico de alto nível, o Kemei KM-2797 entrega desempenho, design moderno e uma experiência completa de corte e acabamento.', 399.99, 295.99, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc2cd77rjh5z97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1219505571%2F23394211684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198196408', 'Barbeador Kemei KM-TX1 prateado 127/220V', 'Procurando um barbeador elétrico que combine qualidade, estilo e preço acessível? Conheça a Kemei! Este modelo inovador não só oferece um desempenho excepcional, mas também se destaca por sua estética elegante e moderna, tornando-se a escolha ideal para quem valoriza tanto a funcionalidade quanto o design. A Kemei se posiciona como uma alternativa competitiva às marcas tradicionais, que muitas vezes cobram de 2 a 3 vezes mais por seus produtos, simplesmente por já estarem consolidadas no mercado. A Kemei, por outro lado, oferece uma máquina de barbear que incorpora tecnologias avançadas, com especificações que muitas vezes superam as de seus concorrentes, tudo isso a um preço justo. Uma das grandes inovações deste modelo é sua bateria de longa duração. é equipada com um sistema de recarga rápida, permitindo que a bateria seja totalmente carregada em apenas duas horas, proporcionando até duas horas de uso contínuo. Isso significa que você pode contar com ela em qualquer situação, seja para um rápido retoque antes de um compromisso ou para um barbear completo, sem se preocupar com a falta de energia. Além de sua funcionalidade impressionante, o design da Kemei é um verdadeiro destaque. Com um acabamento em metal dourado, este barbeador não é apenas uma ferramenta de cuidados pessoais, mas também um acessório que acrescenta um toque de sofisticação à sua rotina. Sua aparência elegante garante que você se sinta confiante e estiloso enquanto cuida da sua aparência. O pacote vem completo, incluindo um cabo USB para recarga, uma bolsinha prática para transporte e uma escovinha para manutenção, garantindo que você tenha tudo o que precisa para uma experiência de barbear completa e satisfatória.', 199.99, 147.91, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5pvz16kgkaa33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1219505571%2F22198196408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
