INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093132182', 'Chumbinho Gamo Ts-22 Long Distance Pesado 5.5mm (.22) - 200un', 'Chumbinho Gamo TS-22 Long Distance 5.5mm – 200 Unidades Desenvolvido para atiradores exigentes e carabinas de alta potência, o Chumbinho Gamo TS-22 Long Distance oferece máximo desempenho em tiros de longa distância. Com peso elevado e design aerodinâmico, garante penetração, impacto e expansão superiores. Fabricado na Espanha com altíssimo padrão de qualidade, o TS-22 proporciona estabilidade e precisão balística, mesmo em distâncias maiores, sendo ideal para quem busca potência aliada à performance. Por que escolher o Chumbinho TS-22? Alto impacto e precisão: ideal para tiros de longa distância Formato com cúpula: maior energia cinética e estabilidade no voo Peso elevado: 1,4g (22 grains) para máxima penetração Performance superior: velocidade de até 720 fps com 17,7 ft/lbs de energia Garanta já o Chumbinho Gamo TS-22 e eleve sua precisão e impacto nos disparos a longa distância! Características Marca: Gamo Modelo: TS-22 Long Distance Calibre: 5,5mm (.22) Peso: 1,4g | 22 grains Quantidade: 200 unidades Cor: Cinza Fabricação: Espanha Velocidade: até 720 fps (com carabinas compatíveis) Energia cinética: 17,7 ft/lbs Penetração na parafina: 1,45" Expansão na parafina: 0,31" Indicação: Tiros de longa distância com alto poder de impacto Atenção Nunca atire em superfícies duras (pedras, paredes de alvenaria ou chapas de aço), pois há risco de ricochete. Utilize sempre em um ambiente seguro e com óculos de proteção. Posicione os alvos com um fundo seguro, como barrancos de terra ou chapas de EVA, para evitar transfixação. Mantenha fora do alcance de crianças e animais e utilize com responsabilidade. Garantia 3 meses contra defeitos de fabricação Itens Inclusos: 1x Lata com 200 unidades de Chumbinho Gamo TS-22 5.5mm 1x Nota fiscal Imagens meramente ilustrativas. As cores e detalhes podem variar conforme sua tela e o produto final.', 95.0, 95.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ra28-mbbe1lmitjkge9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654132276%2F23093132182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094702656', 'Multimídia Mp5 H-tech Ht-3827 7pol Carplay/android auto', 'A multimídia H-Tech HT-3827 MP5 traz praticidade e tecnologia para o seu carro, com tela de 7” IPS Full Touch 2DIN que garante imagens nítidas e excelente resposta ao toque. Compatível com espelhamento, CarPlay e Android Auto, possibilita conexão com e sem fio (consulte versões) para maior comodidade no dia a dia. Conta com entradas USB, SD e AUX, além de Bluetooth para atender chamadas e reproduzir músicas diretamente do celular. Dispõe de 7 opções de cores de painel, controle remoto incluso e entrada para câmera de ré. Oferece ainda 1 entrada de vídeo, 2 saídas de áudio e vídeo, e potência de saída de áudio de 4x60W, proporcionando qualidade sonora e conectividade completa. Dimensões: Altura: 20,5 cm Comprimento: 11 cm Largura: 15 cm Peso: 0,651 kg', 340.97, 313.7, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/sg-11134201-8225r-mhry3xs6ojrc3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F23094702656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
