INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493410297', 'Toalha De Microfibra Dual Loop 60x40cm 360gsm Kers Original', 'Pano de Microfibra Dual Loop Amarela 360gr/m² (40x60cm) Pano para limpeza de superfícies, remoção de ceras, produtos para acabamento final do polimento e muitas outras funções de limpeza. Sua gramatura macia permite que sua utilização seja totalmente segura, pois ela não agride superfícies que já foram finalizadas. Dual Loop Kers é uma pano muito macio, ideal para acabamento final e aplicação de ceras e remoção de ceras, vitrificadores e selantes. Pano com excelente capacidade de absorção, alta durabilidade e fios macios, excelente para dar acabamento nas superfícies. //Características Pano Amarelo; Gramatura 360gr/m²; Tamanho 40x60cm; Super macio; Pano de microfibra; //Utilizações Aplicação de ceras rápidas; Aplicação de produtos para manutenção (UQD); Remoção de cera, polidores, selante e outros produtos; Secagem de veículos; Limpeza de interiores e outras superfícies. //Composição 80% Poliester 20% Nylon (Poliamida)', 21.74, 21.74, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-m10hrt821hpwab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F23493410297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22002364554', 'Bioderma Atoderm Intensive Gel Creme Hidratante Corporal 500ml', 'Gel Creme Hidratante Corporal Bioderma Atoderm Intensive desenvolvido para proporcionar sensação prolongada de bem-estar e melhorar a qualidade de vida daqueles que sofrem com irritação e ressecamento intensivo. O produto tem a função de repor os lipídios perdidos, reter a umidade necessária para a boa saúde cutânea e recuperar o perfeito equilíbrio do microbioma. Graças à sua textura gel-creme, ainda é possível assegurar delicioso frescor e garantir rápida absorção. * RESULTADO: Hidrata e suaviza a pele * SUGESTÕES DE USO: 1.Com a pele limpa; 2.Aplique uma quantidade suficiente de produto; 3.Massageie até a total absorção do produto. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Bioderma Atoderm Intensive Gel Creme Hidratante Corporal 500ml', 231.9, 231.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-22100-uah565fox5ivb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22002364554', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
