INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23732556124', 'Porta Retrato Mickey Clássico - Disney', 'Porta Retrato Mickey Clássico - Disney todos sabemos que uma foto pode ser muito especial! Ela tem o poder de nos fazer lembrar de momentos especiais com quem amamos! Esse porta retrato é perfeito para quem quer tornar ainda mais especial aquela lembrança, guarde suas histórias com muito carinho e amor! O produto é produzido em território nacional, com detalhes incríveis que vão fazer você se apaixonar! Feito em MDA, é ideal para quem quer eternizar um momento especial! O tamanho da foto é 10x10 e é perfeito para complementar a decoração do cantinho favorito da casa! Não importa qual é a sua lembrança, esse porta retrato eterniza todos os momentos com você! Especificações: Altura: 18cm | Largura: 1cm | Comprimento: 13cm | Peso: 0 ,215g | Material: MDA| Tamanho da foto: 10x10 Cuidados e recomendações de uso: Choques ou quedas podem danificar o produto. Não utilizar produtos químicos ou abrasivos. Utilizar somente uma flanela seca para tirar o pó.', 39.9, 39.9, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/sg-11134201-822xc-mi1xo8klzu2u32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23732556124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45359603147', 'Conjunto de Cristaleira 2 Portas Fita Led Espelho Reflecta Noble MDP/MDF Sala Estar Jantar de Luxo', 'Kit 2 Cristaleira 2 Portas com Fita Led e Espelho Reflecta Noble Transforme sua sala de estar ou seu espaço gourmet com a elegante Cristaleira 2 Portas com Fita Led e Espelho Reflecta Noble. Este móvel, produzido pela renomada marca Movelove, combina funcionalidade e estilo, oferecendo um toque moderno à sua decoração. Dimensões 2 Cristaleiras juntas: Com medidas ideais para qualquer ambiente, a cristaleira possui as seguintes dimensões: Altura: 198cm Largura: 86 cm Profundidade: 45 cm Peso: 35,70 kg 1 unidade , 2 unidade 71,40 kg Atributos do Produto Conheça os principais atributos que fazem da Cristaleira Torre Noble uma escolha perfeita para sua casa: Estrutura: Fabricada pela Lukaliam Móveis em MDP/MDF, garantindo durabilidade e resistência. Adega na Parte Inferior: Perfeita para armazenar suas bebidas e copos de forma organizada. Dobradiça Slow Motion com Pistão: Proporciona um fechamento suave e silencioso das portas. Porta com Vidro Reflecta: Adiciona um toque de sofisticação e estilo ao seu espaço. Iluminação LED Cor Quente: Cria uma atmosfera aconchegante e destaca seus objetos decorativos. Suporta até 60 kg: Ideal para armazenar seus itens com segurança. Pintura Fosca Brilhante: Um acabamento que combina beleza e facilidade de limpeza. Montagem e Cuidados A Cristaleira Reflecta Noble acompanha um manual de montagem detalhado, além de todos os parafusos, minifix e cavilhas necessários para uma instalação fácil e rápida. Para manter o móvel sempre bonito, recomenda-se a limpeza com pano seco ou levemente umedecido, evitando produtos químicos como álcool. Conclusão Kit 2 Cristaleira 2 Portas com Fita Led e Espelho Reflecta Noble. Com seu design moderno e funcionalidades práticas, ela é a escolha ideal para quem busca elegância e organização. Garanta já a sua e transforme seu ambiente!', 3199.0, 1889.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-820lq-mnkekvx372mea0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F444869236%2F45359603147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292497066', 'Caneca Mini Tina O Estranho Mundo de Jack - Disney', 'Quer reunir o pessoal todo para aquela resenha quentinha? A gente te ajuda! Com essa caneca, a hora de juntar a turma para aquele cafezinho é muito mais divertido e completo! Não importa se é noite do café ou chá, essa caneca acompanha todas as suas aventuras! A caneca é importada, possui detalhes incríveis que vão fazer você se apaixonar! Com 100ml de capacidade, é a companhia perfeita para quem ama a hora do café da tarde! Feita em cerâmica, com uma base empilhável perfeita que te ajuda na hora de organizar as suas minis tinas! Não importa se é um cafezinho ou um chá, essa caneca te acompanha em todas as suas aventuras! Especificações: Altura: 5,5cm| Largura: 5cm| Comprimento: 5cm| Material: Cerâmica| Capacidade: 100ml Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de Cerâmica.', 29.9, 29.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mqnmdwb4cy6a6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F22292497066', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897753189', 'Pillow Top King Buddemeyer Vision Fill Gold 100% Algodão Acetinado Branco', 'CARACTERÍSTICA DO PRODUTO: Maior volume - Mais enchimento - Altura extra Tecido 100% algodão - Cetim 233 fios - Enchimento 100% poliéster Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 pillow top 193x203x7cm COMPOSIÇÃO: Tecido da frente em 100% algodão cetim 233 fios com acabamento especial. Enchimento em 100% poliéster microfibra extra macia TIPO DE MATERIAL: Tecido da frente em 100% algodão cetim 233 fios; enchimento em 100% poliéster DESCRIÇÃO: Pillow Top king Vision Fill Gold. Em uma combinação que reúne excepcional maciez, resiliência e durabilidade, o Pillow Top Vision Fill Gold torna o momento de descanso mais que especial. Seu toque acetinado em 233 fios de puro algodão é extremamente agradável de sentir. Como diferencial, possui gramatura de 1650 g/m2 promovendo maior volume, altura e conforto extra. Não alérgico, com enchimento em microfibra muito macia e acabamento impecável. Sua higienização é simples e prática, podendo ser lavado à máquina. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 40°C em processo suave. O melhor sabão para manter as características do produto é o de coco ou neutro, não colocar diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Não passar. Não lavar a seco.', 1630.33, 1304.24, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/sg-11134201-7rfh2-m9ktxsgpgyhu38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F20897753189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19657787588', 'Colchão Queen D33 Ortopédico de Espuma Dupla face a Vácuo 158x198cm BF Colchões', 'Com suporte de até 130kg por pessoa, esse é um colchão firme e dupla face, ou seja: é o dobro de durabilidade e praticidade pra você. Ideal para quem busca um colchão com suporte ortopédico para a coluna, esse colchão é feito em 100% espuma D33 selada, certificada e aprovada pelo Instituto Nacional de Estudos do Repouso (INER), o que proporciona um sono tranquilo e reparador. Suporte de Peso: Até 130kg por pessoa Sensação de conforto: Firme Dupla face: Use dos dois lados e garanta o dobro de durabilidade Densidade: 100% espuma de densidade 33 (D33) Hipoalergênico: Tecido com tratamento antimicrobiano O que os nossos clientes amam neste colchão: “O colchão é amplamente elogiado por sua firmeza e qualidade da espuma, proporcionando noites de sono confortáveis e alívio de dores nas costas. A praticidade de transporte devido ao formato a vácuo é destacada, facilitando a instalação em locais de difícil acesso. Além disso, o custo-benefício é considerado excelente, com muitos usuários satisfeitos com a durabilidade e resistência do produto.” Esse modelo possui o Selo Pró-Espuma (INER): a maior autoridade em colchão no Brasil - seu sono merece o padrão mais alto de qualidade O Instituto Nacional de Estudos do Repouso (INER) aplica critérios mais rigorosos que o INMETRO: avalia não só o produto final, mas a matéria-prima e o processo industrial. Entre mais de 400 marcas no mercado, menos de 5% conquistam esse selo. Isso representa um nível superior de qualidade, durabilidade e confiança em cada detalhe do colchão. Conheça as tecnologias do seu colchão D33: A espuma mais indicada para atender diferentes tipos de corpo A densidade 33 é a favorita do brasileiro por um motivo: ela atende a maior diversidade de biotipos (Fonte: INER). É a densidade indicada para quem quer dormir bem de verdade e acordar com disposição. O colchão D33 oferece conforto firme e o suporte ortopédico necessário para manter a coluna alinhada, mas com um toque macio que ajuda a aliviar tensões e desconfortos nos pontos de pressão, ideal para quem busca conforto em qualquer posição do sono. Dupla face: Use dos dois lados A dupla face permite que você aproveite ao máximo o conforto e a durabilidade do seu colchão. Virar o colchão a cada três meses ajuda a preservar sua estrutura e prolonga a vida útil do produto. Além disso, você pode variar entre duas texturas de tampo: malha fresca e respirável, ou acolchoado macio em matelassê. Tecido: hipoalergênico e com design moderno O colchão é revestido com tecido hipoalergênico, que elimina ácaros, fungos e bactérias para um ambiente de sono mais limpo. O tecido também é respirável, macio ao toque e tem estilo moderno que combina com todos os estilos de quarto. Colchão a vácuo: mais praticidade Seu colchão a vácuo chega compacto, mais fácil de transportar e de passar por locais com pouco espaço, como portas e elevadores. Essa tecnologia também reduz o impacto ambiental, diminuindo o espaço necessário para transporte e ajudando a reduzir a emissão de CO2. Ficha técnica do colchão: Tamanho: Queen (17 cm x 158 cm x 198 cm); Sensação de conforto: Firme; Suporte de Peso: Até 130 Kg; Densidade: Espuma D33 certificada; Tecido Hipoalergênico; Dupla Face; Embalado a vácuo; Certificados de qualidade: Selo Pró-Espuma (INER); INMETRO; ABICOL; Garantia: 01 ano; Marca: BF Colchões. Sobre a Bf Colchões A BF Colchões é uma indústria brasileira de colchões, com fábrica, laboratório próprio e mais de 850 colaboradores em Maringá (PR). Fundada em 1968, é uma empresa familiar construída geração a geração. Com laboratório interno de pesquisa e desenvolvimento, criou tecnologias exclusivas e conquistou as principais certificações de qualidade do setor — INMETRO, Selo Pró-Espuma (INER), ABICOL, ISPA e ISO9001. Entre elas, o Selo Pró-Espuma do INER se destaca: com critérios mais rigorosos que os do INMETRO, é conquistado por menos de 5% das marcas do país. A garantia de que o que está escrito no colchão é exatamente o que está dentro dele. No varejo, faz parte do mesmo grupo da BF Casa, loja com mais de 5.000 m² em Maringá. No digital atua desde 2016 e está entre as marcas de colchão mais vendidas e bem avaliadas do Brasil. Atenção à entrega: Não fazemos entregas em estrada de terra, ou barco. Não subimos produtos por escadas e elevadores. Este colchão não acompanha a cama box. FAQ — Perguntas Frequentes O colchão D33 é firme ou macio? O colchão BF Colchões D33 possui sensação de conforto firme, ideal para quem busca mais sustentação para a coluna, estabilidade ao dormir e melhor distribuição do peso corporal. Apesar da firmeza, a espuma oferece toque aconchegante e ajuda a aliviar os pontos de pressão. O colchão D33 é indicado para quais pessoas? A espuma D33 é uma das mais indicadas para diferentes biotipos adultos, especialmente para pessoas acima de 70kg, segundo referências do INER. Este modelo suporta até 130kg por pessoa com conforto e segurança. O colchão D33 ajuda na dor nas costas?', 2634.9, 1399.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820ma-mr0aidcrib5y04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F19657787588', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19135054378', 'Capa Protetor De Colchão Viuva Impermeável 100 Algodão BF Colchões', 'Protetor de Colchão Impermeável - Veste Fácil. O Protetor de Colchão com sua grande capacidade de impermeabilidade apresentam um ótimo desempenho contra água, óleo e manchas, aumentando consideravelmente a vida útil do seu colchão. Com uma grande capacidade de impermeabilidade, os protetores para colchão apresentam um ótimo desempenho contra água, óleo e manchas, aumentando consideravelmente a vida útil do seu colchão. Não faz barulho, não esquenta, antialérgico, 100 impermeável e fácil de lavar e secar. Características: Marca: BF Colchões Tamanho: Viuva Com elástico em toda a sua borda. Composição: 100 Poliéster Tecido: Superior: 100 Algodão Inferior: 50 Polipropileno 50 Polietileno 140 Fios Dimensões: 128 x 188 x 36 cm Atenção a entrega: Não fazemos entregas em locais de acesso apenas por estrada de terra, estrada de areia, por balsa ou barco. Não subimos produtos por escadas e elevadores. Não nos responsabilizamos por montagens, desmontagens e instalações. Confira as dimensões do produto no momento da compra e certifique-se que o item passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados.', 220.87, 169.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e5lvst551cd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F19135054378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256908936', 'Case de Transporte Ipega Para Nintendo Switch 2, Com Espaços de Acessórios, Resistente, PG-SW2003', 'CASE DE TRANSPORTE IPEGA PARA NINTENDO SWITCH 2, COM ESPAÇOS DE ACESSÓRIOS, RESISTENTE, PRETO O Ipega PG-SW2003 encaixa o Nintendo Switch 2 de forma firme — nada de folgas que deixem o aparelho balançar. Isso reduz muito o risco de danos, principalmente quando o estojo estiver em movimento ou dentro de mochilas agitadas. VERSATILIDADE PARA A VIAGEM Leve, compacto, com espaço só necessário — ele entrega um ótimo balanço entre protecção e praticidade. Para quem se desloca muito ou viaja, ter tudo organizado e protegido num único estojo é uma vantagem imensa. --------------------------------------- ESPECIFICAÇÕES TÉCNICAS: *Marca: Ipega *Modelo: PG-SW2003 *Características: *Material: EVA *Encaixe e proteção perfeitos para o console Nintendo Switch 2 *Com alça de mão confortável para transporte *Com bolsa de malha para pequenos acessórios *Com bloco protetor de tela *Com espaço para armazenar 10 cartões de jogo ................................................................................................ TERABYTE SHOP OFICIAL: 20 ANOS DE LEGADO TECH A loja preferida de Gamers e Entusiastas é referência em qualidade e excelência. Montamos seu setup dos sonhos com produtos de alta performance e suporte excepcional. Sua melhor experiência em tecnologia começa aqui!', 209.97, 76.57, NULL, 'Gaming & Consoles > Console Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8260n-mls8h2it40ena8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552226494%2F58256908936', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259843370', 'Microfone Gamer Fifine AM8T, RGB, USB/XLR, Preto, Com Braço Articulado', 'MICROFONE GAMER FIFINE AM8T RGB USB/XLR - PRETO COM BRAÇO ARTICULADO DESIGN E PERFORMANCE DE ALTA QUALIDADE O conjunto Fifine AM8T é a solução definitiva para quem busca uma captação de áudio profissional com a praticidade do universo gamer. Equipado com um sistema híbrido de conexão (USB e XLR), este microfone dinâmico adapta-se desde setups casuais plug-and-play até estúdios equipados com interfaces de áudio e mixers. O design robusto na cor preta é complementado por uma iluminação RGB vibrante, oferecendo uma estética imersiva e moderna. Acompanhado por um braço articulado de alta precisão, o AM8T garante a posição ideal para sua voz enquanto mantém sua mesa livre e organizada. ................................................................................................ DESTAQUES DO PRODUTO • Conexão Híbrida (USB/XLR): Versatilidade total para usar em PCs, consoles (PS4/PS5) ou equipamentos de áudio profissionais. • Braço Articulado Incluso: Suporte extensível com ajustes de até 180°, economizando espaço e otimizando a ergonomia. • Iluminação RGB Personalizada: Adiciona um toque de estilo dinâmico ao seu setup de streaming ou gravação. • Monitoramento em Tempo Real: Entrada dedicada para fones de ouvido com controle de volume direto no microfone. • Cápsula Dinâmica: Excelente rejeição de ruídos externos, focando na clareza e no corpo da sua voz. • Função Mute Touch: Silenciamento instantâneo com um simples toque, essencial para lives e reuniões. • Compatibilidade Universal: Pronto para uso em Desktops, Notebooks, PS4/PS5, Mixers e Interfaces de Áudio. ................................................................................................ ESPECIFICAÇÕES TÉCNICAS • Marca: Fifine • Modelo: AM8T • Tipo de Microfone: Dinâmico • Resposta de Frequência: 50 Hz - 16 KHz • Sensibilidade: -50±3dB • Conexão: USB-C e XLR • Iluminação: RGB • Suporte Integrado: Roscas de 3/8'''' e 5/8'''' embutidas • Funções: Controle de ganho, volume de monitoramento e botão mudo ................................................................................................ CARACTERÍSTICAS DO BRAÇO ARTICULADO • Ajuste Vertical: 180° para cima e para baixo • Ajuste Horizontal: 135° para frente e para trás • Fixação: Braçadeira de mesa reforçada • Benefício: Maior liberdade de movimento e organização do espaço de trabalho ................................................................................................ COMPATIBILIDADE • Dispositivos: PC (Windows/Mac), PS4, PS5, Notebooks • Equipamentos Pro: Mixers, Placas de Som, Interfaces de Áudio (via XLR) ................................................................................................ ITENS INCLUSOS • 01 x Microfone Dinâmico Fifine AM8T • 01 x Braço Articulado Profissional • 01 x Braçadeira para fixação em mesa • 01 x Cabo USB-C • 01 x Manual do Usuário ................................................................................................ TERABYTE SHOP OFICIAL: 20 ANOS DE LEGADO TECH A loja preferida de Gamers e Entusiastas é referência em qualidade e excelência. Montamos seu setup dos sonhos com produtos de alta performance e suporte excepcional. Sua melhor experiência em tecnologia começa aqui!', 1079.98, 391.75, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-820n7-mnn5yzb3zoxy36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552226494%2F58259843370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299551956', 'Placa de Vídeo GALAX NVIDIA GeForce GT 730, 4GB, DDR3, 128-Bit, 73GQF8HX00HD', 'PLACA DE VÍDEO GALAX NVIDIA GEFORCE GT 730 4GB DDR3 128-BITAcelere a experiência multimídia do seu computador com a placa de vídeo dedicada NVIDIA GeForce GT 730 da Galax. Ideal para atualizar sistemas mais básicos, ela proporciona uma navegação na web muito mais fluida, melhor desempenho em edição de fotos e vídeos, além de entregar uma performance até 3 vezes mais rápida em jogos quando comparada aos gráficos integrados tradicionais. DESTAQUES DO PRODUTODesempenho Multimídia: Eleva a velocidade e a capacidade de resposta do seu sistema para tarefas diárias, reprodução de vídeos em alta qualidade e edições gráficas básicas. GeForce Experience: Garante estabilidade sólida e confiabilidade, mantendo os drivers da sua placa sempre atualizados com facilidade. Múltiplos Monitores: Suporta a conexão de até 2 telas simultâneas, ideal para quem precisa aumentar a área de trabalho e a produtividade. Praticidade e Compatibilidade: Traz um conjunto versátil de conexões (HDMI, VGA e DVI), permitindo o uso com monitores modernos ou modelos mais antigos sem a necessidade de adaptadores. ESPECIFICAÇÕES GERAISMarca: Galax Modelo: 73GQF8HX00HD Interface (Barramento): PCI-Express 2.0 x8 PROCESSADOR GRÁFICO (GPU) E MEMÓRIANúcleos CUDA: 384 Frequência Base (Clock): 700 MHz Capacidade de Memória: 4 GB (4096 MB) Tipo de Memória: DDR3 Interface de Memória: 128 bits Velocidade da Memória: 667 MHz (1333 MHz Efetiva) SAÍDAS DE VÍDEO E RESOLUÇÃOTelas Simultâneas: Suporte para até 2 monitores Resolução Digital Máxima: 4096 x 2160 @ 24 Hz (Via HDMI/DVI) Resolução Analógica Máxima: 2048 x 1536 (Via VGA) Conexões Padrão: 1x HDMI, 1x DVI-I (Dual-link), 1x VGA Áudio: Entrada de áudio interna para transmissão via HDMI RECURSOS E TECNOLOGIAS SUPORTADASTecnologias NVIDIA: CUDA, PhysX, FXAA, Adaptive VSync e 3D Vision APIs Gráficas: DirectX 12 e OpenGL 4.4 Sistemas Operacionais Compatíveis: Certificação para Windows 8.1 e Windows 10 (32 ou 64 bits) Atenção: Este modelo não oferece suporte para tecnologia SLI. ENERGIA E DIMENSÕESFonte de Alimentação Recomendada: Mínimo de 300W Dimensões Físicas (com suporte/espelho): 158,7 mm (C) x 85 mm (L) x 28 mm (A) Dimensões Físicas (sem suporte): 144,7 mm (C) x 68 mm (L) x 25 mm (A)', 509.98, 417.14, NULL, 'Computers & Accessories > Desktop & Laptop Components > Graphics Cards', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mq3fcbj9zsi60f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552226494%2F23299551956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44230052404', 'Kit Óleo Bengala Teneré 250 2016-2019 / Lander 250 2016-2018 Yamalube 10w + Retentores', 'Garanta a proteção e o desempenho da suspensão: troque os retentores da bengala e o óleo e mantenha sua moto segura e estável! Os retentores Vedamotors são elaborados a partir de matérias-primas selecionadas, com modernos processos de fabricação, seguindo os mesmos padrões de qualidade dos produtos originais, garantindo assim uma maior qualidade e desempenho. Borracha De Alta Resistência A Desgastes, Impactos, Óleo Mineral E Calor. Produto de alta durabilidade, projetado para manter sua suspensão funcionando como nova, garantindo conforto, segurança e a performance que sua moto merece. Compatível com KAWASAKI: ZX 9 R 1994 A 1997 YAMAHA: WR 200 TODOS XTZ 250 LANDER 2016 A 2018 XTZ 250 Z TENERE 2016 A 2019 XT 600 E 1993 A 2005 YX 600 TODOS YZF 750 1993 A 1998 Conteúdo da Embalagem: 02 Frascos de Óleo da Bengala Yamalube Mineral 10W (Totalizando 1 Litro) 02 Retentores da Bengala (Garfo) Vedamotors Código Original (OEM) do Retentor: 3SP2314500 Medidas: 26,0 X 37,0 X 10,3 Especificações do óleo: - Base mineral; - SAE 10W; - VISCOSIDADE - 10W - Densidade a 15ºC - 0.85 - Viscosidade a 40ºC - 39,2 - Viscosidade a 100ºC - 6,7 - Índice de Viscosidade - 128 - Ponto de Congelamento - (-39ºC) Benefícios do óleo: - Desempenho garantido pela Yamaha Motor Co. Ltd.; - Yamalube Fork Oil 10W é constituído por bases minerais reforçadas por aditivos específicos, com um alto poder antidesgaste e boa fluidez a baixas temperaturas; - Possibilita um ótimo amortecimento em qualquer clima e estável ao longo do tempo; Importante! As Peças Genuinas Yamaha preservam características originais da motocicleta, garantindo desta forma o seu perfeito funcionamento e segurança. Ao utiliza-las, você garante que sua motocicleta se mantenha da mesma maneira em que saiu da fábrica. Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Elaborado com matéria-prima de alta qualidade - Testado e aprovado dentro das normas de segurança. Vedamotors é referência nacional em vedação para motos, reconhecida pela qualidade e confiabilidade. Importante !! - Antes de comprar, verifique o modelo compatível a sua moto. - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo mau uso do produto.', 199.9, 199.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-81zuz-mn1n18jgjqbm52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F44230052404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897992886', 'Par Lonas de Freio P/ Shineray Phoenix 50 / Super Smart 50 Cobreq', 'Par de Lonas de Freio Cobreq Standard Quando a questão é a utilização em ambientes urbanos e que exigem grande mobilidade em Frenagens com performance e segurança, a linha street é a escolha ideal a ser utilizada para todas as motos de até 400cc, que exigem melhor poder de frenagem e baixo desgaste do cubo Compatível com: SHINERAY PHOENIX 50 2007 Em Diante Super Smart 50 DAFRA Super 100 2008 Em Diante Conteúdo da Embalagem: - 01 Par de Lonas de Freio Dianteira Cobreq Street (standard) - 01 Par de Lonas de Freio Traseira Cobreq Street (standard) - 02 Pares de Molas A lona de freio é de fundamental importância na hora da frenagem. É a grande responsável por garantir a fricção que acionará os freios. Reduz consideravelmente os níveis de ruídos e oferece uma frenagem segura. As lonas são fabricadas com matéria prima de primeira qualidade, predominando pelo alto desempenho e durabilidade. Atuando com maquinário de última geração, isso garante um produto de altíssima qualidade, respeitando as normas técnicas de segurança. O produto possui características similares ao produto original: em medidas e composição. Especificações Técnicas: - Chapa traseira de cobre revestido - Maior ligação mecânica entre os materiais de atrito - Redução de corrosão (Menos ferrugem) - Desgaste do cubo de 20% menos- Sapatas de freio em alumínio injetado sem emenda - Com baixos percentuais de metais ferrosos - Acabamento superficial antioxidante - Aplicação dianteira e traseira- Sapata de freio com medidas originais - Reduz o nível de ruídos e oferece frenagens seguras - Ideal Para Reposição - Alta qualidade e resistência Importante: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 79.9, 71.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi4h3v58ie4j59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F21897992886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594326869', 'Alicate De Corte Diagonal 6 Gedore 8314', 'O Alicate Corte Diagonal 6 Polegadas Gedore é uma ferramenta profissional de alto desempenho, desenvolvida para oferecer segurança, precisão e durabilidade em trabalhos elétricos e de manutenção. Fabricado em aço cromo-vanádio fosfatizado, proporciona resistência superior ao desgaste e longa vida útil. Com cabo isolado até 1.000 volts, este alicate é ideal para eletricistas e profissionais que trabalham com redes energizadas, garantindo maior proteção contra choques elétricos. Além disso, sua capacidade de corte permite cortar arames duros de até 1,6 mm, oferecendo versatilidade para diversas aplicações no dia a dia. Detalhes do produto: Tamanho: 6"polegadas; Material: Aço Cromo-Vanádio fosfatizado; Isolação: Cabo isolado até 1.000V; Capacidade de corte: Arame duro até 1,6 mm; Indicação de uso: Trabalhos elétricos, manutenção, oficinas, uso profissional.', 188.9, 96.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvfa-lg54uy73tibp08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F22594326869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18220326208', 'Relé de Pisca Lead 110 2009 A 2015 Magnetron', 'Relé de Pisca Magnetron: pisca na medida certa, sem erro, com qualidade e segurança para sua moto! O relé de pisca tem a função de acionar as lâmpadas de pisca através do comando do condutor. Compatível Com HONDA: LEAD 110 2009 LEAD 110 2010 LEAD 110 2011 LEAD 110 2012 LEAD 110 2013 LEAD 110 2014 LEAD 110 2015 Conteúdo da Embalagem: 01 Relé de Pisca para lâmpadas Led Magnetron Código Original (OEM) do Produto: 38301-KVJ-840 Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Testado e aprovado dentro das normas de segurança. Vantagem: - Agora você pode desfrutar de um produto com qualidade do original, para uma melhor reposição em sua moto e com baixo custo. Importante !! - Antes de comprar, verifique o modelo compatível a sua moto. - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo mal uso do produto.', 119.9, 107.91, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mftrbspvti4k01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F18220326208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
