INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10448410713', 'Shampoo Palmolive Cachos Livres Extrato de Coco 350ml', 'Shampoo desenvolvido especialmente para limpeza de cabelos cacheados que precisam de um cuidado reforçado para combater ressecamento e frizz. O principal ativo é o extrato de coco que permite libertar seus cachos e usá-los como seu melhor acessório! Hidratação sem frizz para cabelos cacheados Brilho e definição para cabelos crespos Nutrição para os cabelos cacheados', 18.39, 18.39, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-23010-4i09i5s0n0lvbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10448410713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
