INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094018027', 'Purificador Electrolux Eletrônico c/ Painel Digital Blue Touch Bivolt Branco (PA21G)', 'Desenvolvido para oferecer uma vida mais saudável a você e toda sua família, o Purificador PA21G Electrolux proporciona água livre de impurezas, cloro e odores. O aparelho possui um design moderno que se destaca pelo painel Blue Touch com todas as funções bem sinalizadas e sensíveis ao toque, além de contar com eficiente sistema eletrônico de refrigeração que permite selecionar até três temperaturas. Com classificação máxima recebida pelo Inmetro (P1/C1), o filtro Acqua Clean tem longa duração e aciona um alerta automático quando estiver na hora de trocar. O Purificador PA21G ainda conta com bandeja flexível, controle de porções de água e fluxo contínuo ou controlado, dependendo da sua preferência.', 759.9, 759.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-7rfgz-m9yigw3a2krma8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F23094018027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
