INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9557529865', 'Kit 2x L-carnitina + Coenzima Q10 180 Caps 2000mg + Garrafa Squeeze Bodyaction', 'L-CARNITINE + COQ10 INGREDIENTES: L-Carnitina (L-Carnitina L-Tartarato), Coenzima Q10 e Antiumectantes Talco Farmacêutico e Dióxido de Silício. INGREDIENTES DA CÁPSULA: Gelatina, Água Potável Filtrada e Corante Dióxido de Titânio. NÃO CONTÉM GLÚTEN SUGESTÃO DE USO: Consumir 3 (três) cápsulas 1 (uma) vez ao dia. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO”. “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM”. “MANTENHA FORA DO ALCANCE DE CRIANÇAS”. “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se a embalagem de proteção estiver violada. Após aberto, consumir preferencialmente em 60 dias.', 131.12, 99.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjjw6nilocuad2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F9557529865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
