INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898829794', 'Subwoofer Slim Jbl Club 102sl 350w 2 Ou 4 Ohms', 'Os subwoofers slim JBL Club proporcionam graves profundos e potentes que levarão o seu sistema para o próximo nível. Através do nosso design de cone patenteado e os surrounds de alta qualidade, são extremamente eficientes e requerem menos potência para produzir os seus efeitos. Os subwoofers slim JBL CLUB também estão disponíveis em configurações de caixa selada e de passagem de faixa, o que proporciona graves potentes, vigorosos e precisos em tudo. Eles também incluem SSI™ (Impedância Inteligente Selecionável), um interruptor de impedância exclusivo que permite selecionar a impedância ideal, 2 ou 4 ohms para o amplificador escolhido e a disposição geral do sistema. Especificações Subwoofer - Controlador de alumínio de 250 mm (10 pol.) Potência - 350 W RMS, pico de 1050 W Sensibilidade (1 W/1 m) - 82,5 dB Resposta em frequência (-6 dB) - 35 Hz – 500 Hz Impedância nominal - 2 ou 4 ohms, selecionável através de um interruptor Diâmetro da bobina de voz - 50 mm (2 pol.) Diâmetro do recorte - 228,61 mm (9 pol.) Profundidade de montagem - 82,5 mm (3-1/4 pol.) Conteúdo da Caixa 1x Subwoofer de 10 pol. 1x Junta de espuma EVA 1x Manual do utilizador', 1054.67, 964.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820le-mlp2ofrz5ame74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F22898829794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799151485', 'Módulo Amplificador Soundigital Basstronik 1600.1 4 Ohms 1600w Rms 1canal', 'O Módulo Amplificador Soundigital Basstronik 1600.1 4 Ohms é a escolha ideal para quem busca potência de verdade com graves intensos e máxima eficiência. Com entrega de 1600W RMS em 4 Ohms, ele garante desempenho de alto impacto para subs e woofers mais robustos em sistemas automotivos. Sua resposta de frequência de 5Hz a 250Hz permite explorar subgraves profundos com total controle. Para maior versatilidade, conta com filtro passa-baixa e filtro subsônico ajustáveis, além do reforço de graves que permite modelar o som conforme o gosto do usuário. Mesmo com grande potência, oferece áudio limpo graças à relação sinal-ruído de 90,8dB. Compacto e resistente, o Basstronik 1600.1 é perfeito para projetos profissionais com instalação discreta e eficiente. A Soundigital une inovação eletrônica, força e confiabilidade em um amplificador projetado para quem exige performance extrema no car audio. Itens inclusos na embalagem 1 Módulo Amplificador Soundigital Basstronik 1600.1 4 Ohms 1 Manual de instruções 1 Certificado de garantia Soundigital Especificações Técnicas Potência RMS @ 4O: 1 x 1600W Resposta de frequência: 5Hz ~ 250Hz Filtro subsônico: 5Hz ~ 40Hz (12dB/oitava) Filtro passa-baixa: 50Hz ~ 250Hz (12dB/oitava) Reforço de graves: 0dB ~ 10dB @ 35Hz Tensão de alimentação: 10V ~ 16V Relação sinal-ruído: 90,8dB Sensibilidade de entrada (RCA): 0.2V ~ 2V Consumo musical: 77,4A Eficiência total: 83,8% Cabo de alimentação: 16mm² (5 AWG) Cabo dos alto-falantes: 2,5mm² (13 AWG) Cabo do remoto: 1,5mm² (15 AWG) Fusível recomendado: 100A Bateria mínima recomendada: 120Ah Dimensões (C x L x A): 18 x 13,6 x 5,4 cm Peso: 1,23kg', 958.67, 958.67, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-821ex-mgicgc1wak241e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F22799151485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
