INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399459621', 'Papel Higiênico Mimmo Folha Tripla 12 Rolos 20 Metros', 'O Papel Higiênico Mimmo Folha Tripla 12 Rolos 20 Metros foi desenvolvido para proporcionar máximo conforto, maciez e resistência no uso diário. Produzido com folha tripla, oferece maior espessura e absorção, garantindo uma experiência mais suave e eficiente, além de reduzir o desperdício. Cada embalagem contém 12 rolos com 20 metros cada, proporcionando excelente rendimento e ótimo custo-benefício para a rotina da casa. Sua textura macia foi pensada para oferecer cuidado e delicadeza no contato com a pele, ao mesmo tempo em que mantém alta resistência mesmo quando úmido. Ideal para quem busca qualidade superior, conforto e segurança na higiene pessoal, o Papel Higiênico Mimmo Folha Tripla combina desempenho, durabilidade e praticidade, sendo uma escolha confiável para manter o bem-estar de toda a família.', 24.49, 24.49, NULL, 'Home & Living > Home Care Supplies > Toilet Paper', 'https://cf.shopee.com.br/file/sg-11134201-825as-mqnelvnaw1zh4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F22399459621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
