INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893732458', 'Sandália Dakota Anabela Feminina Y9811', 'Produto marca Dakota. A Sandália Dakota Anabela é a união perfeita entre o estilo artesanal e a elegância moderna. o destaque fica por conta do salto anabela com revestimento tramado, que adiciona um toque artesanal e sofisticado ao seu visual. Com fechamento de fivela no tornozelo, ela garante praticidade e agilidade, enquanto as sobreposições com recortes na parte frontal deixam os pés à mostra, contrastando com o pin metalizado da marca, um detalhe que eleva o design do calçado. Essa sandália é um investimento em conforto e estilo para o seu dia a dia e momentos de lazer. Leve, pesando 0,549 kg e com salto de 5,80 cm que oferece a altura ideal sem abrir mão da estabilidade, permitindo que você se mova com total confiança. É a peça-chave para compor looks incríveis, cheios de personalidade e encanto. Aproveite a oportunidade de adquirir um produto de qualidade superior e design exclusivo. a Sandália Dakota Anabela é a escolha inteligente para quem valoriza a durabilidade, o conforto e a versatilidade. Peso: 0,749 kg Altura da sola: 5,80 cm', 209.9, 199.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j5-me7msmk3fchwf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23893732458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
