INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22496699597', 'Kit 6 Farol RGB AJK 3 Leds 6W', 'Kit 6 Farol RGB AJK 3 Leds 6W O Farol RGB AJK com 3 LEDs de 6W é um produto inovador e versátil que oferece uma iluminação de alta qualidade e personalizável para diversos propósitos. Com sua tecnologia RGB, você pode escolher entre uma ampla gama de cores, permitindo criar ambientes únicos e envolventes. Seu design compacto e resistente o torna ideal para uso em veículos, embarcações ou até mesmo em projetos de iluminação decorativa. Com potência de 6W por LED, esse par de faróis proporciona um desempenho excepcional, garantindo uma iluminação eficiente e brilhante onde quer que você esteja. Experimente a liberdade de personalizar suas luzes de acordo com o seu gosto e necessidade com o Par de Farol RGB AJK 3 Leds 6W. Especificações Técnicas: • Produto Patenteado • Lente em Policarbonato • Farol com: 3 LEDs • Potência Máxima: 6W • Consumo máximo: 415mA • Alimentação: 12V • Ângulo de Abertura da Lente: 45° • Alta Resistência a Impactos • Número de fios: 4 (Positivo, Negativo, Entrada de sinal, saída de sinal) • Dimensões: 28x79x17mm • Peso: 28g • Sistema endereçamento 2811 • Este produto NÃO é à prova d’agua • Totalmente produzido no Brasil Conteúdo da Embalagem: • 06 Farois RGB AJK 3 Leds 6W • Manual e Certificado de Garantia Importante: • Garantia de 90 Dias. • Valor do Kit.', 166.31, 156.33, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkse7qou8z7rff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F22496699597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
