INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52953535773', 'Barra de Proteína Vo2 Whey Bar Coco - Integral Médica', 'A VO2 Whey Bar Sabor Coco é perfeita para quem busca praticidade, sabor e reforço proteico no dia a dia. Com uma combinação equilibrada de proteínas e carboidratos, ela auxilia na recuperação muscular, aumenta a saciedade e oferece energia para treinos e rotina. Sua textura macia com toque de coco torna o lanche ainda mais gostoso e fácil de consumir em qualquer lugar. Benefícios: ✅ Rica em proteínas – auxilia na recuperação e construção muscular ✅ Sabor delicioso de coco ✅ Ajuda na saciedade ao longo do dia ✅ Prática para levar na bolsa, mochila ou trabalho ✅ Ideal para lanches, pré ou pós-treino Ficha Técnica: ✅ Produto: VO2 Whey Bar ✅ Sabor: Coco ✅ Perfil nutricional: Rico em proteínas ✅ Indicação: Lanches, pré/pós-treino, reposição proteica ✅ Pronta para consumo', 8.9, 8.9, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-81ztn-milyiiji5gcg3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F52953535773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
