INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194866455', 'Óleo Seco de Algodão - Pós Banho', 'O Óleo pós banho é um cuidado diário que transforma o momento do banho em uma experiência única de hidratação e bem-estar. Desenvolvido para proporcionar conforto, leveza e um toque sofisticado para a pele, sua fórmula exclusiva combina ativos que promovem uma sensação agradável logo após a aplicação. Além de hidratar e nutrir a pele, proporciona uma experiência sensorial completa, deixando a pele macia e acetinada ao longo do dia, proporcionando praticidade e conforto para todos os tipos de pele. O Óleo pós banho perfuma a pele com fragrância de baunilha, deixando um aroma suave e delicado. • Um óleo pós banho diferente de todos que você conhece • Combina o óleo de algodão à silicones e partículas ultrafinas que garantem toque seco e acetinado • Hidrata e nutre sem deixar a pele oleosa • Maciez, sedosidade e pele suavemente perfumada', 229.0, 229.0, NULL, 'Beauty > Bath & Body Care > Body Oil', 'https://cf.shopee.com.br/file/sg-11134201-823ra-mozwkyft9vcx3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648711414%2F23194866455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897883141', 'Sal Marinho Integral Mossoró Moído 1kg Natural - Sosal', 'Sal Marinho Integral Moído Salinas Mossoró 1kg Natural - Sosal Produzido no parque salineiro da Cimsal, é obtido naturalmente por meio da evaporação da água do mar. Passa apenas pelo processo de moagem, sem qualquer beneficiamento ou refinamento. Tenha a garantia de um produto de origem e qualidade comprovada. O sal Sosal é de origem marinha. Ideal para finalizar pratos de carne, aves, peixes e saladas. A Cimsal é uma indústria salineira fundada em 1.974, possui Matriz em Areia Branca/RN, e Filiais em Mossoró/RN. A pureza e qualidade do sal Sosal se devem pelas excelentes condições climáticas e ambientais das Salinas de Mossoró, no nordeste brasileiro. São riquíssimos em traços minerais. Ingredientes: Cloreto de sódio, iodato de potássio, antiumectante ferrocianeto de sódio INS 535. Este produto é enriquecido com 15mg a 45mg de iodo por quilograma. Após abertura da embalagem, mantenha bem fechada, armazenando-a em local seco e arejado. NÃO CONTÉM GLÚTEN.', 20.0, 5.97, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1vicwn34rsaa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F23897883141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
