INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15848575772', 'Lupa Luminária de 120 Leds com Tripé Flexível Estética Lorben', 'Voltagem:110V ou 220V (Escolha a voltagem no momento da compra) A Lupa Luminária de 120 Leds com Tripé Flexível possui lente de cristal óptico com aumento de 5 vezes e botão para regulagem de intensidade de iluminação (dimmer), que também serve para ligar e desligar o aparelho. Tem uma das maiores iluminações do mercado, com regulagem até 24W de potência e 2400 lúmens. Seus leds especiais SMD, além de econômicos, não alteram a cor da pele, por isso são ideais para procedimentos estéticos, como micropigmentação e design de sobrancelhas. A pintura epóxi torna o produto mais durável e bonito. Marca: Lorben Material: Aço, Alumínio e Plástico ABS Cor: Branca Frequencia: 50/60hz Potência: 24W (regulável) Iluminação: 2400 lúmens Aumento: 5 vezes Quantidade de Leds: 120 Led SMD Dimensões do produto: Diâmetro da luminária: 23cm Altura máxima: aproximadamente 165cm Altura mínima: aproximadamente 110cm Tamanho da base: 30x25x10cm Peso da base: 2,975kg Peso total do produto: 4,3kg Tamanho da embalagem: 80x29x12cm Peso da embalagem: 5,49kg Código do produto: GT725 Imagens meramente ilustrativas. Autor: Alex Enrique Editora: LORBEN Ano de publicação: 2025 Idioma: Português Formato: PDF (compatível com celular, tablet e computador) Número de páginas: entre 65 e 95 (varia por volume) ISBN: registrado Produto inclui e-book digital complementar, entregue eletronicamente após a compra. Leve para onde quiser conhecimento prático, direto ao ponto e que você pode aplicar no dia a dia. A Série “à Vida” é composta por e-books independentes que abordam temas essenciais para melhorar sua rotina, sua organização e sua qualidade de vida. Cada volume é escrito com linguagem clara e objetiva, trazendo dicas e estratégias testadas e aprovadas para facilitar o seu cotidiano, seja no trabalho, em casa ou nos seus projetos pessoais.', 380.0, 380.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/e5a8e229b34b016a76d32325c797cfc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F15848575772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
