INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209663909', 'Álcool Zumbi Tradicional', 'O Álcool Zumbi 46° INPM é ideal para a limpeza geral da casa, removendo sujeiras difíceis com praticidade e eficiência. Modo de uso: Aplique o produto sobre a superfície a ser limpa e espalhe com um pano. Para limpeza, utilize 100ml do produto para cada 1l de água. Produto não recomendado para superfícies sensíveis ao álcool.', 13.49, 13.49, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262q-mj72liw1g5c7d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554850%2F58209663909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994626952', 'PNEU TRASEIRO 90/90-17 49P ST 600 USO SEM CAMARA DAFRA APACHE 150', 'PNEU VIPAL 90/90-17 49P ST600 TL (SEM CÂMARA) - 920333 FICHA TÉCNICA Pneu: VIPAL ST600 Medida: 90/90-17 Posição: TRASEIRO Tipo de Montagem: SEM CÂMARA (TL) Algumas aplicações: - Dafra - APACHE RTR 150, 2010 a 2015 - APACHE RTR 200, 2019 a 2024 INFORMAÇÕES E ALERTAS CRUCIAIS QUALIDADE: Produto NOVO, ORIGINAL e NÃO REMOLD. DOT/FABRICAÇÃO: Não enviamos DOT específico. Pneus de fabricação recente. COMPATIBILIDADE: Confirme a medida correta no manual de sua moto antes da compra. GARANTIA E INSTALAÇÃO GARANTIA: 5 anos contra defeitos de fabricação (fabricante). ANULAÇÃO: A garantia é ANULADA por mau uso, danos em pista ou MÁ INSTALAÇÃO. INSTALAÇÃO: Deve ser realizada por profissional especializado. REGRAS DE DEVOLUÇÃO E USO NÃO ACEITAMOS DEVOLUÇÕES de produtos que já foram MONTADOS ou UTILIZADOS. A devolução deve ser feita com o produto em sua embalagem original, sem danos e com todos os acessórios inclusos. GARANTIA: Todas as garantias são fornecidas DIRETAMENTE PELO FABRICANTE. O prazo e as condições devem ser acompanhados na embalagem e manual que acompanham o produto. NOTA FISCAL E DADOS CADASTRAIS: Produto novo, original e com Nota Fiscal Eletrônica (NF-e). Confira e atualize seus dados (CPF/CNPJ) antes de comprar para a emissão correta da NF-e. PRAZO DE ENVIO: O prazo de entrega e o valor do frete são calculados e exibidos diretamente na página do produto, abaixo do preço. DÚVIDAS: Evite Transtornos: Tire todas as suas dúvidas no campo de perguntas ANTES de comprar. Enviamos para todo o Brasil. Imagem meramente ilustrativa.', 346.0, 346.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-824i1-mps6qyt39r0u98', 'h