INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250290643', 'Batedeira Philco Crome Base Cristal Duo Turbo Preta 550W 110V', 'Batedeira Philco Crome Base Cristal Duo Turbo Preta 550W 110V2 receitas, 1 batedeira. A Batedeira Philco Crome Base Cristal Duo acompanha 2 tigelas para você preparar duas receitas diferentes ou uma em grande quantidade. Muito mais praticidade e agilidade na cozinha. Ela é turbo e junto com seus 550W de potência e 4 velocidades, sobra performance para variação de velocidade. Com as tigelas plásticas, sendo uma transparente cristal de 4 litros e a outra de plástico preta de 3,1 litros, não vai faltar bolo. Acompanha também batedores para massas leves, como: bolos, pudins, mousses e outros cremes. E o melhor de tudo, o botão de articulação que permite movimentar a plataforma que encaixa a unidade motora, para melhor utilização. Principais Características: - Potência de 550W - 4 velocidades + Turbo - 01 tigela plástica com capacidade de 3,1 litros - 01 tigela cristal com capacidade de 4,3 litros - 01 par de batedores para massas leves - Unidade motora pode ser usada fora da base (pode ser usada como portátil) - Botão para destravar a unidade motora para ser retirada - Tigela giratória (movimentação manual) - Botão ejetor dos batedores - Botão de articulação. Especificações Técnicas: Marca: Philco Modelo: CRISTAL DUO TURBO PR Cor: Preto Tipo: Comum Estado: Tigela extra: Sim Capacidade da tigela (L): 4 Capacidade da tigela extra (L): 3,1 Potência (W): 550 Velocidades: 4 Batedores: 1 par Função portátil: Sim Função turbo: Sim Altura do produto: 39 cm Largura do produto: 32 cm Comprimento do produto: 22,5 cm Peso do produto: 1,952 kg Altura com embalagem: 25,6 cm Largura com embalagem: 34,6 cm Comprimento com embalagem: 22,5 cm Peso com embalagem: 2,182 kg Garantia (Dias): 360 Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas;', 139.9, 139.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-821di-mgmn7tg4atjfcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F58250290643', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
