INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24191366712', 'Volante Classico Revival Fiat 147 Oggi Panorama', 'Elegância e durabilidade em cada detalhe. O volante Revival R PU é a peça chave que faltava em seu clássico. Este volante combina beleza atemporal do Poliuretano com a resistência incomparável do aço inoxidável. A missão da Revival é garantir o conforto ao dirigir e é indispensável para quem deseja elevar o nível de seu veículo. CONTEÚDO DA EMBALAGEM: * Volante Clássico Revival R PU; * Diâmetro 355mm; * Cubo Adaptativo com capa de metálica * Emblema * Parafusos para instalação COMPATIBILIDADES: • Fiat 147 1976 À 1986 • Fiat 1980 À 1986 • Fiat Oggi Até 1980 EXCLUSIVIDADE * Nossos volantes de poliuretano possuem um manuseio suave e preciso, com cubos adaptativos e emblemas metálicos, garantindo a segurança de nossos clientes; * Fabricamos volantes de diversos estilos, materiais e compatibilidades para deixar seu veículo cada vez mais clássico e sofisticado; * Portanto, caso não encontre seu veículo em nossa tabela de compatibilidade, basta entrar em contato com nossa equipe de atendimento. IMPORTANTE * Certifique-se de que o anúncio seja compatível com seu veículo. Em caso de dúvida realize uma pergunta ANTES da compra; * Recomendamos que a instalação seja realizada por um profissional; * Perguntar se a geração do seu veículo é compatível com este anúncio. Eleve seu carro clássico ao próximo nível com perfeição em cada detalhe.', 624.99, 406.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rcdn-m65vsptkpq6i45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401494968%2F24191366712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
