INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56406339875', 'Mangá - Maruru E Hachi: Os Gatinhos Companheiros 01 - Novo/Lacrado', 'Maruru E Hachi: Os Gatinhos Companheiros 01 Devido a certo acontecimento, Maruru deixou a casa de sua dona e se tornou um gato de rua. O mundo lá fora era mais cruel do que imaginava... Em meio a isso, ele conhece um gato mal-encarado chamado Hachi. Os dois resolvem fazer companhia um ao outro, mas... Esta história retrata a intensa luta diária desses gatos de rua (e das pessoas que os cercam) neste mundo difícil de se viver! Segmentos: Mangás Marcas: Planet Manga Autor(es): Yuri Sonoda ISBN: 9786525943480 Check-List: Janeiro/2026 Classificação Etária: 12 anos Editora: Panini Número de páginas: 176 Tipo de capa: Capa Cartão Data de Lançamento: 21/01/2026 Idioma: Português Condição: Novo/Lacrado', 50.9, 50.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8261k-ml2vhnhypds2e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F56406339875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
