INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50409571581', '50 Envelopes (350 Figurinhas) Copa do Mundo 2026 - Oficial Panini', 'Copa do Mundo 2026 - Contém 50 Envelopes (350 Figurinhas) Este Kit contém:50envelopes - cada envelope contém 7 figurinhas.Os envelopes são lacrados e as figurinhas são aleatórias e sortidasPrepare-se para viver a maior Copa do Mundo de todos os tempos! A Coleção Oficial Panini FIFA World Cup 2026T chegou para registrar cada capítulo dessa jornada histórica. Pela primeira vez com 48 seleções e disputada em três países - Canadá, México e Estados Unidos -, esta é a maior coleção já produzida na história dos mundiais! São 112 páginas repletas de adrenalina e 980 figurinhas para colecionar, incluindo figurinhas especiais com efeito metalizado, estádios, cidades-sede e os craques que prometem brilhar nos gramados. Cada envelope agora vem com 7 figurinhas, garantindo ainda mais emoção a cada abertura. Comece agora sua coleção, convoque os amigos para as trocas e complete o guia definitivo do maior espetáculo da Terra! Seja você um colecionador veterano ou um iniciante, o Álbum da Copa 2026 é o seu passaporte para o evento esportivo mais assistido do planeta. Não fique de fora dessa tradição! Segmentos: Colecionáveis, Colecionáveis - Esportes Marcas: Panini Editora: Panini Data de Lançamento: 07/05/2026 Idioma: Português Condição: Novo/Lacrado', 399.99, 348.0, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-820o0-mnk4c91pflkycb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F50409571581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
