INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204163362', 'Sallve Antimanchas FPS 90 Cor 3 - Protetor Solar 15g', 'Protetor solar com cor para todo tipo de pele. Sallve Antimanchas FPS 90 mantém a pele com tom uniforme, sendo ideal para o cotidiano. O Protetor Solar Sallve Antimanchas FPS 90 protege contra radiação UVA/UVB e luz visível enquanto uniformiza a pele com cobertura média. Um toque de proteção e beleza no dia a dia. *Produto livre de parabenos. Como Usar: Aplique uma quantidade generosa de protetor solar na pele seca 15 a 30 minutos antes da exposição ao sol. Espalhe uniformemente pelo rosto e corpo, incluindo áreas frequentemente esquecidas, como orelhas, pescoço e dorso das mãos. Reaplique a cada 2 horas ou após suar, nadar ou secar-se com toalha, mesmo em dias nublados. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 99.9, 99.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8260r-mlme6oy0cy6g42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204163362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
