INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093679406', 'Palito em Bambu para Petiscos - Naipes - 20 unidades - Rizzo', 'Palito em Bambu para Petiscos - Naipes - 20 unidades - Rizzo Transforme sua mesa em um jogo de cartas elegante com o Palito Decorativo para Petisco Naipes! Com um design charmoso inspirado nos naipes de cartas, é perfeito para adicionar um toque divertido e sofisticado às suas festas. Ideal para servir petiscos e aperitivos de forma criativa. Adquira o seu hoje e impressione seus convidados com detalhes únicos! Composição: Bambu e Plástico Medidas Aproximadas: 14cm Contém 20 unidades. Observações Enfeite bambu espeto com naipes Palito;Decorativo;para;Petisco;Naipes;Baralho;Cartas;Original;Presente;Decoração;Festa;Criativo;Resistente;Durável;Estilo;Ornamento;Elegante;Design;Charmoso;Utensílio;Jantar;Exclusivo;Divertido;Colorido;Fino 7899675549340;7899675564145;7899675557758 Aqui tudo é de extrema qualidade. Transformamos simples momentos, em grandes realizações. * Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor * Imagens ilustrativas, as cores podem alterar conforme o seu monitor * Medidas aproximadas * Todas as imagens e descrições são meramente ilustrativas. Caso exista alguma imagem do produto aplicado, ou decorado, saiba que é apenas uma inspiração da Rizzo e sugestão de uso. Outros itens que possam aparecer na foto são vendidos separadamente. * A representação visual dos produtos pode não ser perfeitamente precisa. * As especificações, funções e aparência do produto podem variar de acordo com o modelo e de país para país. * Todas as especificações estão sujeitas a alterações sem aviso prévio. * Embora nos esforcemos para apresentar as informações mais precisas e abrangentes no momento da publicação, um pequeno número de itens pode conter erros de tipografia ou fotografia.', 12.9, 12.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbm4-m5csnymhlk0028', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400124163%2F22093679406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298505647', 'Bíblia Devocional Da Princesinha | Histórias e orações para a hora de dormir | Sheila Walsh', 'A princesinha vai dormir segura e confortável no amor de Deus. A hora de dormir é um momento especial entre pais e fi lhas, e a Bíblia devocional da princesinha vai ajudar a encerrar o dia do melhor jeito possível. São mais de 100 devocionais, orações e atividades para tornar o coração de cada menina mais aberto para a verdade e o amor de Deus. Os devocionais ressaltam as maravilhas do Senhor em palavras que a princesinha consegue entender e a seção Graça e gracejos de boa noite oferece maneiras práticas de tornar a Palavra de Deus real na vida dela, enquanto a oração suave ajuda a embalar tudo, como um cobertor aconchegante. Não importa se o dia foi longo ou cansativo, não há maneira melhor de encerrá-lo junto de Deus do que lendo este lindo livro perfeito para todas as meninas. Autor (a): Sheila Walsh Editora: Thomas Nelson Brasil Acabamento: Capa Dura Número de Páginas: 224 Dimensões: 13 larg. x 18 alt.', 44.99, 44.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvft-lgo49by7yy4f5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F21298505647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26980186505', 'Livro Comfy & cozy books Comfy and Fluffy Purple | Para Colorir Wire-o', 'Livro Comfy & cozy books Comfy and Fluffy Purple | Para Colorir Wire-o O livro COMFY & FLUFFY é uma excelente escolha para quem busca transformar pequenos momentos em experiências de relaxamento e conforto. Inspirado no sucesso dos livros de colorir no TikTok, ele combina criatividade com bem-estar.Com 96 páginas, 48 desenhos exclusivos para colorir e impressos em papel de alta gramatura, o livro oferece uma experiência de pintura de alta qualidade, ideal tanto para lápis de cor quanto para marcadores. Suas ilustrações capturam a essência do cotidianos e momentos aconchegantes, incentivando a exploração artística de forma descomplicada.Livre para todas as idades, COMFY & FLUFFY é mais que um livro de colorir: é uma ferramenta perfeita para aliviar o estresse, desacelerar e se desconectar da rotina atribulada. Uma verdadeira pausa criativa para o corpo e a mente! Autor: Ciranda Cultural Ilustrador: Jeferson Silva Editora: Ciranda Cultural Faixa Etária: + 9 anos Acabamento: Capa Dura Dimensões: 22 cm larg. x 16 cm alt. Número de páginas: 96', 29.99, 7.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-m7jns9mmbzvcb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F26980186505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
