INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47911572439', 'Creme de Avelã com Cacau Pote 1,01kg Vabene', 'Creme de Avelã Com Cacau é uma opção deliciosa e cremosa para quem ama sabores intensos e sofisticados. Feito com avelãs selecionadas e cacau de alta qualidade, esse creme tem uma textura suave e um sabor irresistível, perfeito para ser consumido puro, com pães, torradas, panquecas ou utilizado em diversas receitas de confeitaria e sobremesas. Com um pote de 1,01 kg, é ideal tanto para consumo doméstico quanto para uso profissional em padarias, confeitarias e lanchonetes, garantindo rendimento e praticidade. Sua fórmula equilibrada proporciona um sabor rico e indulgente, perfeito para recheios de bolos, tortas, crepes, brigadeiros gourmet e outras preparações doces. Ingredientes: Açúcar, gordura vegetal, avelã, soro de leite em pó, cacau em pó, aromatizantes e emulsificante lecitina de soja. ALÉRGICOS: CONTÉM AVELÃ E DERIVADOS DE LEITE E SOJA. PODE CONTER AMENDOIM, AMÊNDOA, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ E CEVADA. CONTÉM LACTOSE. CONTÉM GLÚTEN. INFORMAÇÃO NUTRICIONAL (Porção de 100g): Valor Energético: 542kcal Carboidratos: 62g Açúcares Totais: 61g Açúcares Adicionados: 53g Proteínas: 3,8g Gorduras Totais: 31g Gorduras Saturadas: 10g Gorduras Trans: 0g Fibras Alimentares: 2,3g Sódio: 92mg', 82.22, 69.06, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-823o8-mozoaann3rbg2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F47911572439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19265264488', 'Mix de Sementes Chia Girassol Abobora Linhaça Marrom e Dourada Quinoa Branca P&P', 'Mix de Sementes Premium P&P Fit – Nutrição e Saúde em Cada Colherada O Mix de Sementes da P&P Fit é uma combinação poderosa e nutritiva de chia, semente de girassol, abóbora e linhaça. Fonte de fibras, ômega-3 e proteínas vegetais, é ideal para complementar iogurtes, vitaminas, saladas e receitas fitness. Um produto 100% natural e funcional, sem conservantes e rico em benefícios para o organismo. ℹ Benefícios: ✅ Chia, girassol, abóbora e linhaça em equilíbrio perfeito ✅ Fonte de fibras, ômega-3 e proteínas vegetais ✅ Aumenta a saciedade e favorece o trânsito intestinal ✅ Ideal para adicionar a iogurtes, frutas, saladas e receitas ✅ Produto 100% natural, sem conservantes ✅ Embalagem econômica e prática para o dia a dia ℹ Ficha Técnica: ✅ Produto: Mix de Sementes Premium ✅ Marca: P&P Fit ✅ Ingredientes: Sementes de chia, girassol, abóbora e linhaça ✅ Não contém glúten ✅ Conservação: Local seco, fresco e protegido da luz ✅ Validade: Vide embalagem ✅ Indicação: Uso culinário, funcional ou diário', 39.9, 34.95, NULL, 'Food & Beverages > Snacks > Seeds', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meognbkj6rk0eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F19265264488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55653522358', 'Molho De Pimenta Extra Forte 180ML CIA DO TEMPERO', 'Para os corajosos e verdadeiros amantes de pimenta, o Molho de Pimenta Ultrapicante da Cia do Tempero é o desafio que faltava. Desenvolvido com uma seleção das pimentas mais potentes, este molho entrega uma experiência de picância extrema e sabor autêntico. Ideal para quem busca elevar o nível de qualquer prato, desde carnes e salgados até caldos e feijoadas, adicionando uma onda de calor inesquecível a cada gota. ℹ️ Benefícios ✅ Nível de picância extremamente elevado. ✅ Sabor intenso e marcante das pimentas selecionadas. ✅ Ideal para os paladares mais aventureiros. ✅ Apenas algumas gotas são suficientes para transformar um prato. ✅ Produto com a qualidade e tradição Cia do Tempero. ℹ️ Ficha Técnica Produto: Molho de Pimenta Ultrapicante Marca: Cia do Tempero Nível de Picância: Extremo / Ultrapicante Indicação de uso: Perfeito para carnes vermelhas, feijoada, salgados e pratos que exigem um alto nível de picância. Advertência: Manusear com cuidado. Produto extremamente picante. Conservação: Manter em local fresco e seco. Após aberto, conservar em geladeira.', 9.8, 9.8, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-81zwu-mim0l1lhon421c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F55653522358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
