INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16129098263', 'Jogo De Velas De Ignicao NGK LZKAR7AD', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Jogo De Velas De Ignicao - NGK APLICACAO: PEUGEOT 206 1.0 16V GASOLINA DE 2000 A 2006 RENAULT CLIO 1.0 16V GASOLINA DE 1999 A 2008 CLIO 1.0 16V FLEX DE 2005 A 2017 KANGOO 1.0 16V GASOLINA DE 2000 A 2005 KANGOO 1.0 16V FLEX DE 2005 A 2018 LOGAN 1.0 16V FLEX DE 2007 A 2017 SANDERO 1.0 16V FLEX DE 2008 A 2017 TWINGO 1.0 16V GASOLINA DE 1995 A 2000 NISSAN MARCH 1.0 16V FLEX DE 2011 A 2019 DESCRICAO DO PRODUTO A funcao principal das velas de ignicao e gerar a centelha eletrica responsavel pela ignicao do combustivel no motor. Entretanto alem disso, elas tambem servem como termometro para o carro, visto que seu estado apos o desgaste pode indicar diversos problemas do motor.', 146.9, 146.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/85729fc23e4b848d1f031fbeca007e8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F16129098263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693816895', 'ASAS RELUZENTES EDIÇÃO COM BRINDE!', 'ASAS RELUZENTES EDIÇÃO COM BRINDE! ACOMPANHA 1 PÔSTER 1 MARCA PÁGINADescubra as origens do romance entre a rainha do Refúgio das Fadas e o senhor do Bosque do InvernoSéculos se passaram desde a última vez que uma fada das estações quentes no Refúgio das Fadas cruzou a fronteira para o Bosque do Inverno, e enquanto a maioria teme as lendas de monstros espreitando nas terras congeladas, Clarion não consegue deixar de ficar fascinada pela beleza do Inverno. Mas sob os olhos atentos da atual monarca e dos Ministros das Estações da corte, Clarion tem pouco tempo para devaneios enquanto o dia de sua coroação se aproxima.Isto é, até que relatos de um monstro que pode assolar a Primavera vindo do Inverno chegam ao palácio. Derrotar essa ameaça é algo que Clarion vislumbra como uma oportunidade de provar que é digna de seu novo papel. Mas, em vez de encontrar um monstro na fronteira do Inverno, ela se depara com Milori, um jovem guardião do Bosque do Inverno. Juntos, eles criam um vínculo improvável enquanto correm para salvar seus respectivos reinos.No entanto, à medida que a aliança entre ambos evolui para algo mais, eles descobrirão que há uma razão pela qual fadas das estações quentes e do inverno não devem se misturar. E o preço disso pode ser tão mortal quanto os monstros que rondam o Bosque do Inverno. Sobre a autoraAllison Saft é autora best seller do The New York Times, Sunday Times e USA Today, com ênfase no gênero fantasia romântica. Depois de receber seu mestrado em Literatura Inglesa pela Universidade de Tulane, ela se mudou da Costa do Golfo para a Costa Oeste, onde passa seu tempo praticando exercícios em tecido acrobático. Sobre Disney Consumer ProductsDisney Consumer Products (DCP) traz a magia das marcas e franquias da The Walt Disney Company – incluindo Disney, Pixar, Marvel, Star Wars, National Geographic e mais – no cotidiano de famílias e fãs de todo o mundo por meio de produtos e experiências em mais de 100 categorias de varejo, de brinquedos e camisetas a aplicativos, livros, videogames e muito mais. Uma divisão do segmento de Parques, Experiências e Produtos da Disney, as operações globais da DCP incluem o maior negócio de licenciamento do mundo, uma das maiores marcas de publicações infantis, um dos principais licenciadores de jogos interativos entre plataformas, Store in Stores por toda a região, e o e shop no disney latino. comshop e disney. com. br shop (disponível no Brasil, Colômbia e México).. Informações Adicionais Autor: SAFT, ALLISON Data Publicação: 04/04/2025 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ASAS RELUZENTES EDIÇÃO COM BRINDE! Idioma: INDEFINIDO Páginas: 336 Edição: 1 ISBN-13: 9786556097459 ISBN-10: 6556097454', 79.9, 71.91, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m76sywoc51pr67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23693816895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15259777548', 'Sonda Lambda Gol Fox Saveiro Voyage SpaceCross CrossFox', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Sonda Lambda – Original NTK APLICAÇÃO Cross Fox 1.6 8v Flex De 2008 A 2015 Pré Catalizador Fox 1.0 1.6 8v Flex De 2008 A 2015 Pré Catalizador Gol 1.0 1.6 8v Flex De 2008 A 2015 Pré Catalizador Saveiro 1.6 8v Flex De 2008 A 2015 Pré Catalizador Space Cross 1.6 8v Flex De 2008 A 2015 Pré Catalizador Voyage 1.0 1.6 8v Flex De 2008 A 2015 Pré Catalizador CÓDIGO DO FABRICANTE OZA659-EE89 - OZA723-EE20 - OZA806-EE4 CONTEÚDO DA EMBALAGEM 1 Sonda Lambda QUALIDADE Produto Novo, Primeira Linha com Padrão Original de Aplicação e Durabilidade GARANTIA 03 Meses de Garantia NOTA FISCAL SIM SUPORTE PÓS VENDA SIM SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER!', 336.9, 336.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/825a02cfc710e79416c4e4ea5699af8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F15259777548', NULL, NULL, '