INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202121820', 'TRUSS Frizz Zero - Tratamento Condicionante 260ml', 'Tratamento condicionante para todos os tipos de cabelos. TRUSS Frizz Zero pode ser usado como pré-shampoo ou máscara líquida nas lavagens. O Tratamento Condicionante TRUSS Frizz Zero é ultraconcentrado e de fácil absorção, foi desenvolvido para condicionar, hidratar, selar a cutícula capilar e devolver rapidamente a maciez, o brilho e a maleabilidade aos fios. Possui efeito instantâneo e ação antifrizz, pode ser usado antes, durante ou depois dos seus cuidados com os cabelos. Como usar: Cabelos finos: Após lavar o cabelo com shampoo, aplique a máscara no comprimento e pontas. Massageie, deixe agir de 5 a 10 minutos e enxágue. Não é necessário o uso de condicionador. Cabelos grossos: Após lavar o cabelo com shampoo, aplique a máscara no comprimento e pontas. Massageie, deixe agir de 5 a 10 minutos e enxágue para ter o efeito condicionante. Para finalizar, borrife no cabelo a uma distância de 20 a 30 cm e finalize como desejar. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 169.99, 144.49, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mjydcjelrmkn89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58202121820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894821335', 'L''Oréal Professionnel Serie Expert Curl Expression - Máscara de Tratamento 250ml', 'Máscara de tratamento para cabelos cacheados e crespos. L''Oréal Professionnel Serie Expert Curl Expression proporciona hidratação intensa e 2x mais brilho. A Máscara L''Oréal Curl Expression é o produto que você procura para conquistar uma curvatura definida, hidratada e com um movimento natural de tirar o fôlego! Sua fórmula inovadora, enriquecida com Glicerina, Urea H e Extrato de Semente de Hibisco, penetra profundamente na fibra capilar, proporcionando uma hidratação intensa e duradoura, sem pesar nos fios. Com a máscara Curl Expression você recupera o viço e a beleza capilar, com resultados visíveis desde o primeiro dia de uso. Isso porque a sua composição foi pensada para atender as necessidades do seu tipo de cabelo. Leve a sua e experimente a sensação de cachos macios, brilhantes, definidos e sem frizz, com um toque suave e natural que você vai amar! **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 254.9, 254.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mjyjh503op3873', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22894821335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993965940', 'CD De La Soul - The Grind Date (20th Anniversary Special Edition 2CD) - Importado', 'CD De La Soul - The Grind Date (20th Anniversary Special Edition 2CD) - Importado Lançado em 5 de outubro de 2004, The Grind Date é o sétimo álbum de estúdio do grupo americano de hip-hop De La Soul. Esta é uma edição especial comemorativa dos 20 anos do lançamento do álbum! Repertório dos CDs: CD-1: 1. The Future 2. Verbal Clap 3. Much More (Feat. Yummy) 4. Shopping Bags (She Got From You) 5. The Grind Date 6. Church 7. Doo Good in Church (Skit) 8. It’s Like That (Feat. Carl Thomas) 9. He Comes (Feat. Ghostface Killah) 10. Days of our Lives (Feat. Common) 11. Come on Down (Feat. Flavor Flav) 12. No (Feat. Butta Verses) 13. Rock Co.Kane Flow (Feat. MF DOOM) 14. Shoomp (Feat. Sean Paul) CD-2: 1. Bigger (Feat Choklate)* 2. Respect* 3. Verbal Clap (Instrumental) 4. Shopping Bags (She Got From You) (Instrumental) 5. The Grind Date (Instrumental) 6. Days of our Lives (Instrumental) Content owned and licensed by BMG (Conteúdo de propriedade e licenciado pela BMG).', 99.9, 99.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mkmqcnbxf5s0cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22993965940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
