INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209399728', 'Frutas Vermelhas Congeladas IQF De Marchi', 'Aproveite a praticidade e o sabor das frutas vermelhas congeladas De Marchi, perfeitas para suas receitas! Elas são congeladas individualmente através do processo IQF (Individual Quick Freezing), preservando suas propriedades e sabor. Versátil e saudável, experimente em sobremesas, bebidas, molhos, smoothies, geleias, caldas para sorvetes ou iogurtes. Ideal para usar em crumble de frutas vermelhas ou sangria refrescante.', 27.79, 27.79, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-82585-mqnekrub4i6jb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554932%2F58209399728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262324545', 'Tênis Masculino Puma Bmw Mms Caven 2.0 Estiloso Lançamento Original', 'Descubra o estilo e a performance com o Tênis Masculino Puma BMW Caven 2.0 BDP. Este lançamento original combina a tradição da Puma com a inovação da BMW Motorsport, trazendo um design inspirado no BMW M4 GT4 EVO. Com gráficos modernos e uma paleta de cores renovada, este tênis é perfeito para quem busca velocidade, precisão e inovação. O Puma BMW Caven 2.0 BDP é mais do que um simples tênis; é uma experiência de conforto e sustentabilidade. Equipado com a palmilha SOFTFOAM+, ele oferece um amortecimento suave e um conforto prolongado, ideal para o uso diário, esportes leves e ocasiões casuais. O cabedal é confeccionado com pelo menos 20% de materiais reciclados, enquanto a parte inferior utiliza 10% de materiais reciclados, refletindo o compromisso da Puma com a sustentabilidade. Na Galpão dos Esportes, você encontra produtos 100% originais, com foco em qualidade e performance. Desde 2019, oferecemos uma experiência de compra única, com atendimento especializado e uma seleção cuidadosa das melhores marcas do mercado. Nossa loja física, com mais de 300 m², é um espaço dedicado aos amantes do esporte. ESPECIFICAÇÕES TÉCNICAS: - Marca: Puma - Modelo: BMW MMS CAVEN 2.0 BDP - Tipos de ajuste: Cadarços - Materiais do exterior: Sintético e malha - Materiais do interior: Têxtil acolchoado - Materiais da sola: Borracha - Tipo de calçado: Tênis - Gênero: Masculino - Tipo de largura: Padrão - Usos recomendados: Casual, esportes leves, uso diário ITENS INCLUSOS: - 1 Par de Tênis Puma BMW Caven 2.0 BDP Cuide bem do seu Puma BMW Caven 2.0 BDP para garantir sua durabilidade. Recomendamos limpar com um pano úmido e evitar a exposição prolongada ao sol. Não perca a oportunidade de elevar seu estilo e conforto com o Tênis Masculino Puma BMW Caven 2.0 BDP. Garanta o seu agora mesmo e sinta a diferença!', 899.85, 599.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lp-mpcavqfyymf6f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F58262324545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
