INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097207439', 'Par Lanterna de placa Parati Bola G3 G4 Com Soquete e led', '- Conjunto de lanterna de placa para os modelos Parati G3 e G4 da Volkswagen. - O kit inclui o soquete apropriado para a instalação da lâmpada na lanterna de placa. - Acompanha lâmpada LED de alta qualidade para iluminar a placa traseira do veículo. - A tecnologia LED oferece maior eficiência energética e maior durabilidade em comparação com lâmpadas convencionais. - A luz branca e brilhante do LED facilita a leitura da placa em diversas condições de luminosidade. - A substituição das lanternas de placa originais pelas de LED contribui para uma estética mais moderna do veículo. - Produto projetado para se ajustar perfeitamente ao design e especificações dos modelos Parati G3 e G4. - A melhoria na iluminação da placa traseira ajuda a garantir a segurança ao dirigir à noite ou em locais com pouca visibilidade. - Verificar a compatibilidade com o ano específico do veículo antes de fazer a compra.', 38.6, 38.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdys-lxs9ora4d74cc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397577506%2F18097207439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594869371', 'Protetor Solar NeoStrata Minesol Corpo & Rosto FPS 99 120ml', 'Protetor solar para peles equilibradas a secas. NeoStrata Minesol Corpo & Rosto Antioxidante FPS 99 protege dos raios UVA, UVB e luz visível enquanto hidrata por até 8 horas a pele. O Protetor Solar Fluido Hidratante NeoStrata Minesol Corpo & Rosto Antioxidante FPS 99 possui textura fluída e toque seco, com rápida absorção, se espalhando facilmente na pele sem deixar resíduos brancos. Além disso, tem um triplo complexo antioxidante, que previne a ação dos radicais livres, combate o envelhecimento e ainda ajuda a manter a integridade da pele. Possui fragrância suave e é resistente à água e ao suor. Dermatologicamente testado. Não comedogênico. Experimente também o Esfoliante Facial NeoStrata Skin Active Exfoliating Wash, para remover impurezas e células mortas. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 172.9, 172.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mlnp8yz99l39eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23594869371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399332705', 'Elseve Liso dos Sonhos - Condicionador 400ml', 'Condicionador para todos os tipos de cabelo. Elseve Liso dos Sonhos deixa os fios lisos, brilhantes e à prova de umidade. O Condicionador Elseve Liso dos Sonhos transforma os fios desde a primeira aplicação. Ele sela a fibra capilar, reduz o frizz e proporciona um liso desmaiado com movimento natural, deixando os cabelos sedosos, brilhantes e protegidos contra a umidade. *Produto livre de parabenos. Vegano. Como Usar: Após o uso do shampoo, aplique no comprimento até as pontas. Deixe agir e enxágue. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 43.9, 43.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82628-mk00ddeo19txf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22399332705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598473197', 'BARALHO BATMAN 85 ANOS COPAG 55 CARTAS PERSONALIZADO COLECIONÁVEL CORINGA DC SUPER HERÓIS PERSONAGEM', '***PRODUTO COPAG EM PORTUGUÊS ORIGINAL, OFICIAL, LACRADO E COM NOTA FISCAL*** BARALHO BATMAN 85 ANOS COPAG 55 CARTAS PERSONALIZADO COLECIONÁVEL CORINGA DC SUPER HERÓIS PERSONAGEM Informações Técnicas: - Material: Plástico e Papel Recicláveis. - Contém: 55 Unidades de Cartas personalizadas no formato 63mm x 88mm - EAN: 7896192346063 - Peso: 100g - COPAG - Garantia: Contra defeitos de fabricação - Prazo de Validade: Indeterminado - Tamanho da carta: Poker Size (63mm x 88mm) - Indicado para: Truco, Poker, Buraco, Cacheta, Paciência, BlackJack, Canastra, Buraco, Rummy, Bridge e muito mais! *Este produto não é um brinquedo. Produto destinado a colecionadores com mais de 14 anos. Obs: O tamanho de cada peça pode sofrer variações. Faça o descarte consciente e preserve o meio ambiente. Imagens meramente ilustrativas. BARALHO BATMAN Celebre os 85 anos do icônico herói da DC com o Baralho Batman 85 Anos, uma verdadeira obra-prima para colecionadores e fãs apaixonados! Cada carta foi cuidadosamente elaborada para trazer os personagens mais emblemáticos da franquia, capturando a essência única do universo do Batman. Uma homenagem à longa trajetória do Batman, repleta de emoção, aventura e legado. Adicione essa peça exclusiva à sua coleção e mergulhe no fascinante mundo do Cavaleiro das Trevas. --------------------------------------------------- SEJA MUITO BEM VINDO(A) A LOJA DE BRINQUEDOS DO CANAL 40 POR QUÊ COMPRAR NA LOJA DE BRINQUEDOS DO CANAL 40? *Enviamos seu pedido sempre no mesmo dia ou no máximo no próximo dia útil dependendo do horário da sua compra! *Produtos lacrados, originais e oficiais da mais alta qualidade; *Experiência única de compra (incluindo a experi