INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14073478588', 'Kit 2 Travesseiros Antialérgico Percal 180 Fios Ecoplumas Fibra Siliconada 50x70x14cm BF Colchões', 'A fibra siliconada é um produto não alérgico, inodoro, de alta resistência, que pode ser lavado várias vezes sem comprometer a sua qualidade. O travesseiro, por ser 100 lavável, inclusive à máquina, é ideal para pessoas que sofrem com os agentes alergênicos. Acomoda-se perfeitamente ao corpo, assegurando encaixe suave, macio e confortável em qualquer posição. Características: Tecido em Microfibra. Fibra de poliéster siliconada Não alérgico e lavável Macio Tamanho: 50 cm x 70 cm x 14 cm Composição: Revestimento: Tecido Percal 180 fios - 50 Poliéster 50 Algodão Enchimento - Fibra de poliéster siliconada - 100 Poliéster Contém: 02 Travesseiros Marca: BF Cor Branco', 199.9, 179.0, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6idlja9lued', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F14073478588', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
