INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794955135', 'Macarrão com Ovos Pena Adria', 'O Macarrão Adria com Ovos Pena é perfeito para uma macarronada mais suculenta. A forma de pena, com ranhuras, garante maior adesão do molho ao macarrão. Ideal para quem busca praticidade e versatilidade na cozinha sem abrir mão do sabor único da linha Adria Macarrão com Ovos. Modo de Preparo: 1. Ferva 1 litro de água para cada 100g de massa. Se desejar acrescente um fio de óleo ou azeite. 2. Quando a água ferver, acrescente 5g de sal (1 colher de chá) e o macarrão. 3. Cozinhe por 8 a 12 minutos, mexendo de vez em quando para que a massa não grude. 4. Escorra a massa e sirva com o molho de sua preferência. Tempo de cozimento: Firme: 8 minutos. Al dente: 10 minutos. Macio: 12 minutos.', 4.49, 4.49, NULL, 'Food & Beverages > Food Staples > Noodles', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqnel2rphr0i0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F22794955135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
