INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29790109855', 'Sabonete Íntimo Hidraderm Neutro 200ml', 'Sabonete Íntimo Hidraderm Neutro 200ml Principais Características: Desenvolvido para a higiene íntima diária, proporcionando cuidado delicado e eficaz. Fórmula com pH balanceado que auxilia na manutenção da flora natural da região íntima. Textura suave que promove frescor e conforto durante o uso. Benefícios: Ajuda a prevenir desconfortos causados por alterações na flora íntima. Proporciona sensação de limpeza prolongada e bem-estar ao longo do dia. Pode ser utilizado diariamente sem agredir a pele delicada da região íntima. Mantém a região protegida e equilibrada. Diferenciais do Produto: Fórmula neutra, especialmente desenvolvida para peles e mucosas sensíveis. Dermatologicamente e ginecologicamente testado, garantindo segurança e eficácia. Embalagem prática de 200ml, ideal para uso contínuo. Especificações Técnicas: Peso: 200ml Instruções de Uso: Aplicar pequena quantidade do sabonete íntimo na região externa previamente umedecida, massageando suavemente. Enxaguar abundantemente com água. Pode ser usado diariamente. Avisos e Precauções: Produto de uso externo. Não utilizar em áreas internas da mucosa. Em caso de irritação, suspenda o uso e consulte um médico. Manter fora do alcance de crianças. O que está incluso? 1 unidade de Sabonete Íntimo Hidraderm Neutro 200ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 29.79, 22.79, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfe2v85fbf2fd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F29790109855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44409033908', 'Sabonete Lux Liquido Orquidea Negra 250Ml', 'Sabonete Lux Líquido Orquídea Negra 250ml Principais Características: • Fragrância sofisticada de Orquídea Negra, com notas florais marcantes e envolventes. • Enriquecido com óleos florais, que deixam a pele macia e suavemente hidratada. • Textura cremosa que forma uma espuma abundante, proporcionando uma limpeza eficaz e delicada. Benefícios: • Higieniza suavemente, respeitando o equilíbrio natural da pele. • Proporciona sensação de pele perfumada e toque sedoso. • Ideal para momentos de autocuidado e relaxamento. Diferenciais do Produto: • Desenvolvido com perfumistas internacionais, garantindo fragrância duradoura e marcante. • Combinação única entre limpeza, suavidade e sofisticação. • Produto dermatologicamente testado. Especificações Técnicas: • Peso: 250ml Instruções de Uso: • Aplique o produto sobre a pele molhada ou em uma esponja. • Espalhe até formar espuma abundante. • Enxágue completamente em seguida. • Uso diário. Avisos e Precauções: • Uso externo. • Evite contato com os olhos. • Em caso de irritação, descontinue o uso e procure orientação médica. • Mantenha fora do alcance de crianças. O que está incluso? • 1 unidade de Sabonete Lux Líquido Orquídea Negra 250ml DÚVIDAS FREQUENTES Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 28.89, 21.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdw5-mccia38rczi98a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F44409033908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
