INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212366519', 'Caneta hidrográfica jumbo com 24 cores 150224J Faber-Castell', 'INMETRO 008053/2017 As canetinhas hidrográficas Faber-Castell da linha Jumbo estimulam a criatividade das crianças com a formulação exclusiva de corantes de alta qualidade com cores mais vivas. As canetinhas tem formato triangular ergonômico, ideal para mãozinhas pequenas. Sua ponta é super-resistente, a tinta é lavável e o produto é atóxico. Detalhes: - Formato triangular - Ideal para mãos pequenas - Cores Vivas e pontas super resistentes - Lavável na maioria dos tecidos - Contém 24 cores', 124.76, 99.9, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-823qj-mpcr1md4luz160', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F58212366519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898043039', 'Widi Care Juba Shampoo Transição Capilar 500ml', 'Características principais: Auxílio na transição capilar: Cuida dos fios com química enquanto promove a hidratação e o fortalecimento dos fios naturais. Hidratação profunda: Deixa os fios macios e hidratados, reduzindo o frizz e a quebra. Fortalece os fios: Ajuda a fortalecer os fios frágeis e quebradiços durante o período de transição. Cabelos equilibrados: Controla o ressecamento e mantém o couro cabeludo saudável. Ação suave: Limpeza eficaz sem agredir os fios ou o couro cabeludo. Ativos principais: Óleo de Argan: Rico em ácidos graxos e vitamina E, proporciona nutrição e proteção aos fios, evitando o ressecamento e a quebra. D-Pantenol: Hidrata profundamente, garantindo fios mais fortes e com menos frizz. Proteínas vegetais: Reforçam a estrutura do fio, restaurando a saúde e a elasticidade durante a transição. Indicação: Tipo de cabelo: Ideal para quem está em transição capilar, com fios mistos (naturais e com química), ou cabelos que necessitam de hidratação e fortalecimento. Uso ideal: Para quem deseja cuidar dos fios durante a transição, promovendo um crescimento saudável e hidratado, sem deixar de lado o cuidado com os fios quimicamente tratados. Modo de uso: Aplique o shampoo nos cabelos molhados. Massageie o couro cabeludo e o comprimento dos fios até formar espuma. Enxágue bem e, se necessário, repita a aplicação. Para melhores resultados, use com outros produtos da linha Juba para transição capilar, como condicionador e máscaras.', 139.28, 67.33, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rfhl-m30urwk2wkh948', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F22898043039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293056854', 'Cristalizador de Vidros Impermeabilizante Repele Água Parabrisa Orbi 100ml', 'Cristalizador de Vidros Impermeabilizante Orbi 100ml – Máxima Visibilidade e Proteção Tenha mais segurança e visibilidade ao dirigir em dias de chuva com o Cristalizador de Vidros Orbi. Com fórmula avançada, ele repele a água instantaneamente, formando uma película protetora que facilita o escoamento da água e reduz o acúmulo de sujeira no para-brisa e demais vidros do veículo. ✅ Efeito hidrorrepelente: Gotas de chuva deslizam com facilidade, melhorando a visão em condições adversas. ✅ Mais segurança na direção: Reduz a necessidade de uso constante do limpador de para-brisa. ✅ Fácil aplicação: Rende até várias aplicações com apenas 100ml. ✅ Compatível com todos os tipos de vidro automotivo. Ideal para quem busca proteção, praticidade e mais tranquilidade na estrada. Cristalize seus vidros com qualidade Orbi!', 22.14, 22.14, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvfc5wsz5d405a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F22293056854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194039183', 'Pincel marcador permanente Multimark 1.0mm Preto e Branco MM/ES102PBZF Faber-Castell', 'O Pincel Marcador Permanente Multimark 1.0 mm da Faber-Castell é ideal para quem busca versatilidade, precisão e durabilidade em superfícies diversas. Com tinta de secagem rápida e resistente à água, ele proporciona marcações permanentes em materiais como papel, plástico, vidro, metal e madeira. Sua ponta oferece traço médio e uniforme, perfeito para escrita técnica, identificação de objetos, organização de arquivos ou uso artístico. A estrutura robusta e o corpo ergonômico garantem conforto durante o uso prolongado, enquanto a tampa com sistema de vedação evita o ressecamento da ponta. Detalhes: - Embalagem com 2 marcadores - Cor: Preto e Branco - Design exclusivo. - Cobertura translúcida. - Ponta cônica: 1.0 mm. - Corpo ergonômico - Excelente cobertura nas mais diversas superfícies: papel, cartão, madeira, plástico, vidro, metal, cerâmica, parede e muito mais - O marcador é permanente em superfícies porosas e pode ser removido em vidro ou superfícies lisas - Tinta não lavável em tecidos.', 29.52, 24.9, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-7rfgu-m9zugsrwyvjg03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F22194039183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
